// 🔺mcpCommand holds the data fields for a mcpCommand record.
func mcpCommand(factory EngineFactory, config *Config) *cobra.Command {
	var dryRun bool
	cmd := &cobra.Command{
		Use:   "mcp",
		Short: "Run MCP server",
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRun {
				return nil
			}
			engine, err := factory(*config)
			if err != nil {
				return err
			}
			ctx := context.Background()
			if config.Timeout > 0 {
				ctxWithTimeout, cancel := context.WithTimeout(ctx, config.Timeout)
				defer cancel()
				ctx = ctxWithTimeout
			}
			return serveMcp(ctx, engine)
		},
	}
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Initialize and exit without starting server")
	return cmd
}

func serveMcp(ctx context.Context, engine *Engine) error {
	_ = ctx
	_ = engine
	return runMcpServer(nil, nil)
}

// 🕸️graphqlCommand holds the data fields for a graphqlCommand record.
func graphqlCommand(factory EngineFactory, config *Config) *cobra.Command {
	var query string
	var variablesJSON string
	cmd := &cobra.Command{
		Use:   "graphql [query]",
		Short: "Execute a GraphQL query",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			resolvedQuery := query
			if resolvedQuery == "" && len(args) > 0 {
				resolvedQuery = args[0]
			}
			if resolvedQuery == "" {
				return fmt.Errorf("missing query")
			}
			var variables map[string]interface{}
			if variablesJSON != "" {
				if err := json.Unmarshal([]byte(variablesJSON), &variables); err != nil {
					return fmt.Errorf("invalid variables JSON: %w", err)
				}
			}
			var payload struct {
				Query     string                 `json:"query"`
				Variables map[string]interface{} `json:"variables"`
			}
			if err := json.Unmarshal([]byte(resolvedQuery), &payload); err == nil && payload.Query != "" {
				resolvedQuery = payload.Query
				if variables == nil {
					variables = map[string]interface{}{}
				}
				for key, value := range payload.Variables {
					if _, exists := variables[key]; !exists {
						variables[key] = value
					}
				}
			}
			return runGraphQL(cmd, factory, config, resolvedQuery, variables)
		},
	}
	cmd.Flags().StringVar(&query, "query", "", "GraphQL query")
	cmd.Flags().StringVarP(&variablesJSON, "vars", "v", "", "GraphQL variables JSON")
	return cmd
}

// #region 🪅Analyze Command
func analyzeCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "analyze <id>",
		Short: "Analyze an entity by its ID",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			id := args[0]
			buildOpts := TreeBuildOptions{}
			tree := BuildMonorepoTreeCached(ctx, buildOpts)
			var found *TreeNode
			var findByID func(node *TreeNode)
			findByID = func(node *TreeNode) {
				if found != nil {
					return
				}
				if node.ID == id {
					found = node
					return
				}
				for _, c := range node.Children {
					findByID(c)
				}
			}
			findByID(tree)
			if found == nil {
				return fmt.Errorf("entity not found: %s", id)
			}
			type summaryOutput struct {
				ID      string `json:"id"`
				Kind    string `json:"kind"`
				Label   string `json:"label"`
				Summary string `json:"summary"`
				URI     string `json:"uri"`
			}
			out := summaryOutput{
				ID:      found.ID,
				Kind:    string(found.Kind),
				Label:   found.Label,
				Summary: found.Summary,
				URI:     found.URI,
			}
			switch {
			case config.IsJSON():
				encoded, err := json.Marshal(out)
				if err != nil {
					return err
				}
				fmt.Fprintln(cmd.OutOrStdout(), string(encoded))
			default:
				fmt.Fprintf(cmd.OutOrStdout(), "[%s] %s\n", out.Kind, out.Label)
				if out.Summary != "" {
					fmt.Fprintf(cmd.OutOrStdout(), "  %s\n", out.Summary)
				}
				if out.URI != "" {
					fmt.Fprintf(cmd.OutOrStdout(), "  %s\n", out.URI)
				}
			}
			return nil
		},
	}
	return cmd
}

// #endregion 🪅Analyze Command

