// ⌨️searchCommand holds the data fields for a searchCommand record.
func searchCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "search [query]",
		Short: "Search monorepo tree",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()

			filter := buildTreeFilterFromFlags(cmd)
			if len(args) > 0 {
				filter.Query = args[0]
			}
			if queryFlag, _ := cmd.Flags().GetString("query"); queryFlag != "" && filter.Query == "" {
				filter.Query = queryFlag
			}

			buildOpts := TreeBuildOptions{
				IncludeSections: filter.OnlyKinds[TreeNodeSection] ||
					filter.OnlyKinds[TreeNodeDefinition] ||
					filter.Query != "",
			}
			tree := BuildMonorepoTreeCached(ctx, buildOpts)
			tree = searchMonorepoTreeWithCache(ctx, tree, filter.Query)
			tree = FilterMonorepoTree(tree, &filter)

			var output string
			switch {
			case config.IsJSON():
				encoded, err := json.Marshal(tree)
				if err != nil {
					return err
				}
				output = string(encoded) + "\n"
			case config.IsMarkdown():
				output = RenderMonorepoTreeMarkdown(tree)
			default:
				output = RenderMonorepoTree(tree)
			}
			fmt.Fprint(cmd.OutOrStdout(), output)
			return nil
		},
	}
	bindTreeFlags(cmd)
	return cmd
}

// 🌳flattenTreeNodes holds the data fields for a flattenTreeNodes record.
func flattenTreeNodes(node *TreeNode, out *[]*TreeNode) {
	if node.Kind != TreeNodeCategory {
		*out = append(*out, node)
	}
	for _, c := range node.Children {
		flattenTreeNodes(c, out)
	}
}

// ⬛listCommand holds the data fields for a listCommand record.
func listCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "list [query]",
		Short: "Stream a flat list of monorepo items",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			sorted, _ := cmd.Flags().GetBool("sorted")
			limit, _ := cmd.Flags().GetInt("limit")
			filter := buildTreeFilterFromFlags(cmd)
			if len(args) > 0 {
				filter.Query = args[0]
			}
			if queryFlag, _ := cmd.Flags().GetString("query"); queryFlag != "" && filter.Query == "" {
				filter.Query = queryFlag
			}
			buildOpts := TreeBuildOptions{
				IncludeSections: filter.OnlyKinds[TreeNodeSection] ||
					filter.OnlyKinds[TreeNodeDefinition] ||
					filter.Query != "",
			}
			tree := BuildMonorepoTreeCached(ctx, buildOpts)
			tree = searchMonorepoTreeWithCache(ctx, tree, filter.Query)
			tree = FilterMonorepoTree(tree, &filter)
			var nodes []*TreeNode
			flattenTreeNodes(tree, &nodes)
			if sorted {
				sort.Slice(nodes, func(i, j int) bool { return nodes[i].ID < nodes[j].ID })
			}
			if limit > 0 && len(nodes) > limit {
				nodes = nodes[:limit]
			}
			switch {
			case config.IsJSON():
				for _, n := range nodes {
					entityKind := treeNodeKindToEntityKind(n.Kind)
					if entityKind == "" {
						entityKind = string(n.Kind)
					}
					if n.Data != nil {
						wrapped := map[string]interface{}{entityKind: n.Data}
						encoded, err := json.Marshal(wrapped)
						if err != nil {
							continue
						}
						fmt.Fprintln(cmd.OutOrStdout(), string(encoded))
					} else {
						encoded, err := json.Marshal(n)
						if err != nil {
							continue
						}
						fmt.Fprintln(cmd.OutOrStdout(), string(encoded))
					}
				}
			case config.IsMarkdown():
				for _, n := range nodes {
					entityKind := treeNodeKindToEntityKind(n.Kind)
					if entityKind == "" {
						entityKind = string(n.Kind)
					}
					if n.Data != nil {
						fmt.Fprintln(cmd.OutOrStdout(), renderEntityMarkdown(entityKind, n.Data))
					} else {
						label := n.Label
						if n.URI != "" {
							label = "[" + n.Label + "](" + n.URI + ")"
						}
						fmt.Fprintln(cmd.OutOrStdout(), "- "+label)
					}
				}
			default:
				for _, n := range nodes {
					entityKind := treeNodeKindToEntityKind(n.Kind)
					if entityKind != "" && n.Data != nil {
						fmt.Fprintln(cmd.OutOrStdout(), renderEntityHuman(entityKind, n.Data, false))
					} else {
						label := n.Label
						if n.URI != "" {
							label = "[" + n.Label + "](" + n.URI + ")"
						}
						fmt.Fprintln(cmd.OutOrStdout(), label)
					}
				}
			}
			return nil
		},
	}
	cmd.Flags().Int("limit", 0, "Maximum number of items to output (0 = unlimited)")
	bindTreeFlags(cmd)
	cmd.Flags().Bool("sorted", false, "Collect all results and sort by ID before output")
	return cmd
}

type boolFlagSpec struct {
	Name  string
	Usage string
}

type boolFlagPairSpec struct {
	OnlyName  string
	NoName    string
	OnlyUsage string
	NoUsage   string
}

// 🔘bindBoolFlags MUST register all boolean flags from the input specs.
func bindBoolFlags(cmd *cobra.Command, specs []boolFlagSpec) {
	for _, spec := range specs {
		cmd.Flags().Bool(spec.Name, false, spec.Usage)
	}
}

// 🚩bindOnlyNoFlagPairs MUST register only/no boolean flag pairs from the input specs.
func bindOnlyNoFlagPairs(cmd *cobra.Command, specs []boolFlagPairSpec) {
	for _, spec := range specs {
		cmd.Flags().Bool(spec.OnlyName, false, spec.OnlyUsage)
		cmd.Flags().Bool(spec.NoName, false, spec.NoUsage)
	}
}

