// 🛠️technologyCommand holds the data fields for a technologyCommand record.
func technologyCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:                "technology",
		Short:              "Manage technologies",
		DisableFlagParsing: false,
		Args:               cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 3 && args[1] == "generate" {
				technologyName := args[0]
				kind := args[2]
				switch kind {
				case "requirements":
					return GenerateTechnologyRequirements(technologyName)
				case "docs":
					return GenerateTechnologyDocs(technologyName)
				case "todos":
					return GenerateTechnologyTodos(technologyName)
				default:
					return fmt.Errorf("unknown generate kind %q (use requirements, docs, or todos)", kind)
				}
			}
			return cmd.Help()
		},
	}

	listCmd := &cobra.Command{
		Use:   "list",
		Short: "List technologies",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runTechnologyList(factory, *config, cmd, args)
		},
	}
	bindStreamFlags(listCmd)
	cmd.AddCommand(listCmd)

	treeCmd := &cobra.Command{
		Use:   "tree",
		Short: "Show technology tree Structure",
		RunE: func(cmd *cobra.Command, args []string) error {
			return runTechnologyTree(factory, *config, cmd, args)
		},
	}
	bindStreamFlags(treeCmd)
	cmd.AddCommand(treeCmd)

	return cmd
}

// 😀headingEmojiRe holds the data fields for a headingEmojiRe record.
var headingEmojiRe = regexp.MustCompile(`^[\x{1F000}-\x{1FFFF}\x{2600}-\x{27FF}\x{FE00}-\x{FE0F}]+\s*`)

// 📑ExtractMarkdownSection holds the data fields for a ExtractMarkdownSection record.
func ExtractMarkdownSection(content string, sectionName string) string {
	lines := strings.Split(content, "\n")
	headerRe := regexp.MustCompile(`^(#{1,6})\s+(.+?)\s*$`)
	inSection := false
	sectionLevel := 0
	var result []string
	for _, line := range lines {
		if match := headerRe.FindStringSubmatch(line); match != nil {
			level := len(match[1])
			name := strings.TrimSpace(headingEmojiRe.ReplaceAllString(match[2], ""))
			if !inSection && name == sectionName && level == 1 {
				inSection = true
				sectionLevel = level
				continue
			}
			if inSection && level <= sectionLevel {
				break
			}
		}
		if inSection {
			result = append(result, line)
		}
	}
	text := strings.TrimSpace(strings.Join(result, "\n"))
	return text
}

// 🗃️isLicenseText holds the data fields for a isLicenseText record.
func isLicenseText(text string) bool {
	lower := strings.ToLower(text)
	return strings.Contains(lower, "gnu") ||
		strings.Contains(lower, "license") ||
		strings.Contains(lower, "free software") ||
		strings.Contains(lower, "warranty") ||
		strings.Contains(lower, "redistribute") ||
		strings.Contains(lower, "copyright")
}

// 🟨isHeaderMetaLine holds the data fields for a isHeaderMetaLine record.
func isHeaderMetaLine(text string) bool {
	if strings.HasPrefix(text, "[") && strings.Contains(text, "](") {
		return true
	}
	if strings.HasPrefix(text, "#region") || strings.HasPrefix(text, "#endregion") ||
		strings.HasPrefix(text, "region ") || text == "region" ||
		strings.HasPrefix(text, "endregion") {
		return true
	}
	if len(text) > 0 && text[0] >= '0' && text[0] <= '9' {
		return true
	}
	if strings.HasPrefix(text, "💻") || strings.HasPrefix(text, "🧰") || strings.HasPrefix(text, "🔬") {
		return true
	}
	return false
}

func ExtractFileHeaderSummary(filePath string) string {
	absPath := filepath.Join(rootDir, filePath)
	content, err := ReadTextFile(absPath)
	if err != nil {
		return ""
	}
	lang := GetLanguage(filePath)
	if lang == nil || !lang.SupportsHeaders() {
		return ""
	}
	prefix := lang.CommentPrefix()
	sections := lang.ParseSections(content)
	var headerSection *Section
	for i := range sections {
		if strings.ToLower(sections[i].Name) == "header" {
			headerSection = &sections[i]
			break
		}
	}
	if headerSection == nil {
		return ""
	}
	lines := strings.Split(content, "\n")
	type commentBlock struct {
		lines []string
	}
	var blocks []commentBlock
	var currentBlock []string
	inBlock := false
	for i := headerSection.StartLine; i < headerSection.EndLine && i <= len(lines); i++ {
		line := strings.TrimSpace(lines[i-1])
		if line == "" {
			if inBlock {
				blocks = append(blocks, commentBlock{lines: currentBlock})
				currentBlock = nil
				inBlock = false
			}
			continue
		}
		if !strings.HasPrefix(line, prefix) {
			continue
		}
		inBlock = true
		commentText := strings.TrimSpace(strings.TrimPrefix(line, prefix))
		currentBlock = append(currentBlock, commentText)
	}
	if len(currentBlock) > 0 {
		blocks = append(blocks, commentBlock{lines: currentBlock})
	}
	for _, block := range blocks {
		allMeta := true
		anyLicense := false
		hasSpec := false
		for _, l := range block.lines {
			if !isHeaderMetaLine(l) {
				allMeta = false
			}
			if isLicenseText(l) {
				anyLicense = true
			}
			if isSpecText(l) {
				hasSpec = true
			}
		}
		if allMeta || anyLicense || hasSpec {
			continue
		}
		return strings.TrimSpace(strings.Join(block.lines, "\n"))
	}
	return ""
}

// 📄ExtractFileHeaderRequirements holds the data fields for a ExtractFileHeaderRequirements record.
func ExtractFileHeaderRequirements(filePath string) string {
	absPath := filepath.Join(rootDir, filePath)
	content, err := ReadTextFile(absPath)
	if err != nil {
		return ""
	}
	lang := GetLanguage(filePath)
	if lang == nil || !lang.SupportsHeaders() {
		return ""
	}
	prefix := lang.CommentPrefix()
	sections := lang.ParseSections(content)
	var headerSection *Section
	for i := range sections {
		if strings.ToLower(sections[i].Name) == "header" {
			headerSection = &sections[i]
			break
		}
	}
	if headerSection == nil {
		return ""
	}
	lines := strings.Split(content, "\n")
	type commentBlock struct {
		lines []string
	}
	var blocks []commentBlock
	var currentBlock []string
	inBlock := false
	for i := headerSection.StartLine; i < headerSection.EndLine && i <= len(lines); i++ {
		line := strings.TrimSpace(lines[i-1])
		if line == "" {
			if inBlock {
				blocks = append(blocks, commentBlock{lines: currentBlock})
				currentBlock = nil
				inBlock = false
			}
			continue
		}
		if !strings.HasPrefix(line, prefix) {
			continue
		}
		inBlock = true
		commentText := strings.TrimSpace(strings.TrimPrefix(line, prefix))
		currentBlock = append(currentBlock, commentText)
	}
	if len(currentBlock) > 0 {
		blocks = append(blocks, commentBlock{lines: currentBlock})
	}
	var requirementsLines []string
	for _, block := range blocks {
		hasSpec := false
		for _, l := range block.lines {
			if isSpecText(l) {
				hasSpec = true
				break
			}
		}
		if hasSpec {
			requirementsLines = append(requirementsLines, block.lines...)
		}
	}
	return strings.TrimSpace(strings.Join(requirementsLines, "\n"))
}

func ExtractSectionLeadComments(content string, section Section, prefix string) (requirements string, summary string) {
	lines := strings.Split(content, "\n")
	lowerName := strings.ToLower(section.Name)
	if lowerName == "header" || lowerName == "license" {
		return "", ""
	}
	var specLines []string
	var summaryLines []string
	for i := section.StartLine; i < section.EndLine && i <= len(lines); i++ {
		line := strings.TrimSpace(lines[i-1])
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, prefix) {
			break
		}
		commentText := strings.TrimSpace(strings.TrimPrefix(line, prefix))
		if isHeaderMetaLine(commentText) {
			continue
		}
		if strings.HasPrefix(commentText, "[") && strings.Contains(commentText, "](repo://") {
			continue
		}
		if isLicenseText(commentText) {
			continue
		}
		if isSpecText(commentText) {
			specLines = append(specLines, commentText)
		} else {
			summaryLines = append(summaryLines, commentText)
		}
	}
	return strings.TrimSpace(strings.Join(specLines, "\n")), strings.TrimSpace(strings.Join(summaryLines, "\n"))
}

// 📖ExtractDefinitionDocstring holds the data fields for a ExtractDefinitionDocstring record.
func ExtractDefinitionDocstring(content string, def Definition, prefix string) (requirements string, summary string) {
	lines := strings.Split(content, "\n")
	for i := def.StartLine - 2; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			break
		}
		if !strings.HasPrefix(line, prefix) {
			break
		}
		commentText := strings.TrimSpace(strings.TrimPrefix(line, prefix))
		if strings.HasPrefix(commentText, "[") && strings.Contains(commentText, "](repo://") {
			continue
		}
		if isSpecText(commentText) {
			requirements = commentText + "\n" + requirements
		} else {
			summary = commentText + "\n" + summary
		}
	}
	return strings.TrimSpace(requirements), strings.TrimSpace(summary)
}

// 🟩findTechnologyByName holds the data fields for a findTechnologyByName record.
func findTechnologyByName(name string) *Technology {
	technologies := LoadTechnologies()
	for i := range technologies {
		if technologies[i].Name == name {
			return &technologies[i]
		}
	}
	return nil
}

// 🟦walkTechnologyFiles holds the data fields for a walkTechnologyFiles record.
func walkTechnologyFiles(technology *Technology) []File {
	var files []File
	for _, bundle := range technology.Bundles {
		bundleRoot := filepath.Join(rootDir, bundle.Root)
		err := filepath.WalkDir(bundleRoot, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return nil
			}
			if d.IsDir() {
				name := d.Name()
				if strings.HasPrefix(name, ".") || name == "node_modules" || name == "dist" || name == "build" || name == "target" || name == "__pycache__" {
					return fs.SkipDir
				}
				return nil
			}
			relPath, _ := filepath.Rel(rootDir, path)
			relPath = NormalizePath(relPath)
			if isGitIgnored(path) || IsGenerated(path) {
				return nil
			}
			kind := DeriveFileKind(d.Name())
			bundleID := bundle.GetID()
			files = append(files, File{
				ID:        buildFileID(relPath, &bundleID),
				Path:      relPath,
				URI:       buildFileUriFromPath(relPath),
				Name:      d.Name(),
				Extension: filepath.Ext(d.Name()),
				BundleID:  &bundleID,
				Kind:      kind,
			})
			return nil
		})
		_ = err
	}
	return files
}

// 📍EntityEntry holds the data fields for a EntityEntry record.
type EntityEntry struct {
	ID   string
	URI  string
	Text string
}

func GenerateTechnologyRequirements(technologyName string) error {
	technology := findTechnologyByName(technologyName)
	if technology == nil {
		return fmt.Errorf("technology %q not found", technologyName)
	}
	var entries []EntityEntry
	technologyReadmePath := filepath.Join(rootDir, technology.Root, "README.md")
	if content, err := ReadTextFile(technologyReadmePath); err == nil {
		requirements := ExtractMarkdownSection(content, "Requirements")
		if requirements != "" {
			p := &Technology{Name: technology.Name, Root: technology.Root, Kind: technology.Kind}
			entries = append(entries, EntityEntry{ID: p.GetID(), URI: p.GetURI(), Text: requirements})
		}
	}
	for _, bundle := range technology.Bundles {
		readmePath := filepath.Join(rootDir, bundle.Root, "README.md")
		if content, err := ReadTextFile(readmePath); err == nil {
			requirements := ExtractMarkdownSection(content, "Requirements")
			if requirements != "" {
				entries = append(entries, EntityEntry{ID: bundle.GetID(), URI: bundle.GetURI(), Text: requirements})
			}
		}
		folderReadmes := findFolderReadmes(bundle.Root)
		for _, frp := range folderReadmes {
			if content, err := ReadTextFile(filepath.Join(rootDir, frp)); err == nil {
				requirements := ExtractMarkdownSection(content, "Requirements")
				if requirements != "" {
					folderPath := filepath.Dir(frp)
					f := &Folder{Path: folderPath, Name: filepath.Base(folderPath)}
					entries = append(entries, EntityEntry{ID: f.GetID(), URI: f.GetURI(), Text: requirements})
				}
			}
		}
	}
	files := walkTechnologyFiles(technology)
	for _, file := range files {
		if file.Kind != FileKindCode && file.Kind != FileKindScript {
			continue
		}
		headerRequirements := ExtractFileHeaderRequirements(file.Path)
		if headerRequirements != "" {
			entries = append(entries, EntityEntry{ID: file.ID, URI: file.URI, Text: headerRequirements})
		}
		absPath := filepath.Join(rootDir, file.Path)
		content, err := ReadTextFile(absPath)
		if err != nil {
			continue
		}
		lang := GetLanguage(file.Path)
		if lang == nil {
			continue
		}
		sections := lang.ParseSections(content)
		prefix := lang.CommentPrefix()
		var walkSections func(secs []Section)
		walkSections = func(secs []Section) {
			for _, s := range secs {
				if strings.ToLower(s.Name) == "header" {
					walkSections(s.Children)
					continue
				}
				requirements, _ := ExtractSectionLeadComments(content, s, prefix)
				if requirements != "" {
					s.FilePath = file.Path
					entries = append(entries, EntityEntry{ID: s.GetID(), URI: s.GetURI(), Text: requirements})
				}
				walkSections(s.Children)
			}
		}
		walkSections(sections)
		if lang.SupportsDefinitions() {
			lines := strings.Split(content, "\n")
			defs := lang.ParseDefinitions(content, lines)
			for _, dr := range defs {
				def := Definition{
					Name:      dr.Name,
					Kind:      DeriveDefinitionKind(dr.Kind),
					FilePath:  file.Path,
					StartLine: dr.Start,
					EndLine:   dr.End,
				}
				requirements, _ := ExtractDefinitionDocstring(content, def, prefix)
				if requirements != "" {
					entries = append(entries, EntityEntry{ID: def.GetID(), URI: def.GetURI(), Text: requirements})
				}
			}
		}
	}
	var sb strings.Builder
	sb.WriteString("# \U0001F4AF Requirements\n")
	for _, e := range entries {
		sb.WriteString("\n## [" + e.ID + "](" + e.URI + ")\n\n")
		sb.WriteString(e.Text + "\n")
	}
	outputPath := filepath.Join(rootDir, technology.Root, "SPECS.md")
	return WriteTextFile(outputPath, sb.String())
}

// 🟪GenerateTechnologyDocs holds the data fields for a GenerateTechnologyDocs record.
func GenerateTechnologyDocs(technologyName string) error {
	technology := findTechnologyByName(technologyName)
	if technology == nil {
		return fmt.Errorf("technology %q not found", technologyName)
	}
	var entries []EntityEntry
	technologyReadmePath := filepath.Join(rootDir, technology.Root, "README.md")
	if content, err := ReadTextFile(technologyReadmePath); err == nil {
		docs := ExtractMarkdownSection(content, "Docs")
		if docs != "" {
			p := &Technology{Name: technology.Name, Root: technology.Root, Kind: technology.Kind}
			entries = append(entries, EntityEntry{ID: p.GetID(), URI: p.GetURI(), Text: docs})
		}
	}
	for _, bundle := range technology.Bundles {
		readmePath := filepath.Join(rootDir, bundle.Root, "README.md")
		if content, err := ReadTextFile(readmePath); err == nil {
			docs := ExtractMarkdownSection(content, "Docs")
			if docs != "" {
				entries = append(entries, EntityEntry{ID: bundle.GetID(), URI: bundle.GetURI(), Text: docs})
			}
		}
		folderReadmes := findFolderReadmes(bundle.Root)
		for _, frp := range folderReadmes {
			if content, err := ReadTextFile(filepath.Join(rootDir, frp)); err == nil {
				docs := ExtractMarkdownSection(content, "Docs")
				if docs != "" {
					folderPath := filepath.Dir(frp)
					f := &Folder{Path: folderPath, Name: filepath.Base(folderPath)}
					entries = append(entries, EntityEntry{ID: f.GetID(), URI: f.GetURI(), Text: docs})
				}
			}
		}
	}
	files := walkTechnologyFiles(technology)
	for _, file := range files {
		if file.Kind != FileKindCode && file.Kind != FileKindScript {
			continue
		}
		summary := ExtractFileHeaderSummary(file.Path)
		if summary != "" {
			entries = append(entries, EntityEntry{ID: file.ID, URI: file.URI, Text: summary})
		}
		absPath := filepath.Join(rootDir, file.Path)
		content, err := ReadTextFile(absPath)
		if err != nil {
			continue
		}
		lang := GetLanguage(file.Path)
		if lang == nil {
			continue
		}
		sections := lang.ParseSections(content)
		prefix := lang.CommentPrefix()
		var walkSections func(secs []Section)
		walkSections = func(secs []Section) {
			for _, s := range secs {
				if strings.ToLower(s.Name) == "header" {
					walkSections(s.Children)
					continue
				}
				_, summaryText := ExtractSectionLeadComments(content, s, prefix)
				if summaryText != "" {
					s.FilePath = file.Path
					entries = append(entries, EntityEntry{ID: s.GetID(), URI: s.GetURI(), Text: summaryText})
				}
				walkSections(s.Children)
			}
		}
		walkSections(sections)
		if lang.SupportsDefinitions() {
			lines := strings.Split(content, "\n")
			defs := lang.ParseDefinitions(content, lines)
			for _, dr := range defs {
				def := Definition{
					Name:      dr.Name,
					Kind:      DeriveDefinitionKind(dr.Kind),
					FilePath:  file.Path,
					StartLine: dr.Start,
					EndLine:   dr.End,
				}
				_, summaryText := ExtractDefinitionDocstring(content, def, prefix)
				if summaryText != "" {
					entries = append(entries, EntityEntry{ID: def.GetID(), URI: def.GetURI(), Text: summaryText})
				}
			}
		}
	}
	var sb strings.Builder
	sb.WriteString("# \U0001F4DA Docs\n")
	for _, e := range entries {
		sb.WriteString("\n## [" + e.ID + "](" + e.URI + ")\n\n")
		text := e.Text
		if text != "" {
			var filtered []string
			for _, line := range strings.Split(text, "\n") {
				trimmed := strings.TrimSpace(line)
				if strings.HasPrefix(trimmed, "// #region") || strings.HasPrefix(trimmed, "// #endregion") || strings.HasPrefix(trimmed, "#region") || strings.HasPrefix(trimmed, "#endregion") {
					continue
				}
				filtered = append(filtered, line)
			}
			text = strings.TrimSpace(strings.Join(filtered, "\n"))
		}
		if text == "" {
			continue
		}
		sb.WriteString(text + "\n")
	}
	outputPath := filepath.Join(rootDir, technology.Root, "DOCS.md")
	return WriteTextFile(outputPath, sb.String())
}

// 🟫GenerateTechnologyTodos holds the data fields for a GenerateTechnologyTodos record.
func GenerateTechnologyTodos(technologyName string) error {
	technology := findTechnologyByName(technologyName)
	if technology == nil {
		return fmt.Errorf("technology %q not found", technologyName)
	}
	var entries []EntityEntry
	for _, bundle := range technology.Bundles {
		bundleRoot := filepath.Join(rootDir, bundle.Root)
		todos, _ := ScanTodos(bundleRoot)
		for _, todo := range todos {
			if todo.Location != nil && isGitIgnored(todo.Location.FilePath) {
				continue
			}
			if todo.Location != nil && IsGenerated(todo.Location.FilePath) {
				continue
			}
			title := todo.Name
			desc := todo.Description
			parentPath := todo.ParentID
			relParent, _ := filepath.Rel(rootDir, parentPath)
			relParent = NormalizePath(relParent)
			entityID := relParent
			entityURI := buildFileUriFromPath(relParent)
			if todo.Location != nil {
				relLoc, _ := filepath.Rel(rootDir, todo.Location.FilePath)
				relLoc = NormalizePath(relLoc)
				entityID = relLoc
				entityURI = buildFileUriFromPath(relLoc)
			}
			text := "### TODO: " + title
			if desc != "" {
				text += "\n" + desc
			}
			entries = append(entries, EntityEntry{ID: entityID, URI: entityURI, Text: text})
		}
	}
	var sb strings.Builder
	sb.WriteString("# \U0001F533 TODOs\n")
	for _, e := range entries {
		sb.WriteString("\n## [" + e.ID + "](" + e.URI + ")\n\n")
		sb.WriteString(e.Text + "\n")
	}
	outputPath := filepath.Join(rootDir, technology.Root, "TODOS.md")
	return WriteTextFile(outputPath, sb.String())
}

// 📁findFolderReadmes holds the data fields for a findFolderReadmes record.
func findFolderReadmes(bundleRoot string) []string {
	var readmes []string
	absRoot := filepath.Join(rootDir, bundleRoot)
	filepath.WalkDir(absRoot, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			name := d.Name()
			if strings.HasPrefix(name, ".") || name == "node_modules" || name == "dist" || name == "build" || name == "target" || name == "__pycache__" {
				return fs.SkipDir
			}
			return nil
		}
		if d.Name() == "README.md" {
			relPath, _ := filepath.Rel(rootDir, path)
			relPath = NormalizePath(relPath)
			if relPath != NormalizePath(filepath.Join(bundleRoot, "README.md")) {
				readmes = append(readmes, relPath)
			}
		}
		return nil
	})
	return readmes
}

// 📦bundleCommand holds the data fields for a bundleCommand record.
func bundleCommand(factory EngineFactory, config *Config) *cobra.Command {
	root := &cobra.Command{Use: "bundle", Short: "Bundle management commands"}
	listCmd := &cobra.Command{
		Use:   "list",
		Short: "List bundles",
		RunE: func(cmd *cobra.Command, args []string) error {
			opts := getStreamOptions(cmd)
			statusFilter := getStatusFilter(cmd)
			var bundlesWithOpenTickets map[string]bool
			if statusFilter != nil {
				bundlesWithOpenTickets = getBundlesWithOpenTickets()
			}

			stream := make(chan Event)
			go func() {
				defer close(stream)
				stream <- Event{Kind: KindStart, Command: "bundle list"}

				bundleChan := make(chan Bundle)
				go func() {
					StreamBundles(context.Background(), bundleChan, opts)
				}()

				for b := range bundleChan {

					if statusFilter != nil {
						hasOpenTicket := bundlesWithOpenTickets[b.Name]
						if *statusFilter == "open" && !hasOpenTicket {
							continue
						}
						if *statusFilter == "closed" && hasOpenTicket {
							continue
						}
					}

					data, err := json.Marshal(map[string]interface{}{"bundle": b})
					if err != nil {
						continue
					}
					stream <- Event{Kind: KindResult, Command: "bundle list", Data: data}
				}
				stream <- Event{Kind: KindDone, Done: &DonePayload{ExitCode: 0, Status: "ok"}}
			}()

			return renderStream(cmd, config, stream)
		},
	}
	bindStreamFlags(listCmd)
	bindStatusFlags(listCmd)

	treeCmd := &cobra.Command{
		Use:   "tree",
		Short: "Show bundle tree",
		RunE: func(cmd *cobra.Command, args []string) error {
			opts := getStreamOptions(cmd)
			statusFilter := getStatusFilter(cmd)
			var bundlesWithOpenTickets map[string]bool
			if statusFilter != nil {
				bundlesWithOpenTickets = getBundlesWithOpenTickets()
			}
			_ = bundlesWithOpenTickets

			stream := make(chan Event)
			go func() {
				defer close(stream)
				stream <- Event{Kind: KindStart, Command: "bundle tree"}

				bundleChan := make(chan Bundle)
				go func() {
					StreamBundles(context.Background(), bundleChan, opts)
				}()

				var bundles []Bundle
				for b := range bundleChan {
					bundles = append(bundles, b)
				}

				sort.Slice(bundles, func(i, j int) bool {
					return bundles[i].Name < bundles[j].Name
				})

				if config.IsMarkdown() {
					var sb strings.Builder
					for _, b := range bundles {
						bMap := map[string]interface{}{}
						bBytes, _ := json.Marshal(b)
						json.Unmarshal(bBytes, &bMap)
						line := renderEntityMarkdown("bundle", bMap)
						sb.WriteString(line + "\n")
					}
					data, _ := json.Marshal(map[string]string{"markdown": sb.String()})
					stream <- Event{Kind: KindResult, Command: "bundle tree", Data: data}
				} else {
					stream <- Event{Kind: KindLog, Level: "info", Command: "bundle tree", Message: "."}
					for i, b := range bundles {
						connector := "├── "
						if i == len(bundles)-1 {
							connector = "└── "
						}
						stream <- Event{Kind: KindLog, Level: "info", Command: "bundle tree", Message: connector + b.Name}
					}
				}
				stream <- Event{Kind: KindDone, Done: &DonePayload{ExitCode: 0, Status: "ok"}}
			}()
			return renderStream(cmd, config, stream)
		},
	}
	bindStreamFlags(treeCmd)
	bindStatusFlags(treeCmd)

	root.AddCommand(listCmd)
	root.AddCommand(treeCmd)
	return root
}

