// 🌳TreeNodeKind represents a tree node kind value.
type TreeNodeKind string

const (
	TreeNodeTechnology  TreeNodeKind = "technology"
	TreeNodeBundle      TreeNodeKind = "bundle"
	TreeNodeFolder      TreeNodeKind = "folder"
	TreeNodeFile        TreeNodeKind = "file"
	TreeNodeSection     TreeNodeKind = "section"
	TreeNodeDefinition  TreeNodeKind = "definition"
	TreeNodeGoal        TreeNodeKind = "goal"
	TreeNodeTicket      TreeNodeKind = "ticket"
	TreeNodeDraft       TreeNodeKind = "draft"
	TreeNodeTodo        TreeNodeKind = "todo"
	TreeNodePolicy      TreeNodeKind = "policy"
	TreeNodeBreach      TreeNodeKind = "breach"
	TreeNodeContributor TreeNodeKind = "contributor"
	TreeNodeCheckpoint  TreeNodeKind = "checkpoint"
	TreeNodeSession     TreeNodeKind = "session"
	TreeNodeStatute     TreeNodeKind = "statute"
	TreeNodeCategory    TreeNodeKind = "category"
)

// 🌿TreeNode holds the data fields for a tree node record.
type TreeNode struct {
	Kind        TreeNodeKind
	ID          string
	Label       string
	URI         string
	SubKind     string
	Description string
	Summary     string
	Year        int
	Month       int
	Day         int
	Status      string
	Contributor string
	Data        map[string]interface{}
	Children    []*TreeNode
	matched     bool
}

// 🧹TreeFilter holds the data fields for a tree filter record.
type TreeFilter struct {
	Query               string
	OnlyKinds           map[TreeNodeKind]bool
	ExcludeKinds        map[TreeNodeKind]bool
	OnlySubKinds        map[TreeNodeKind][]string
	ExcludeSubKinds     map[TreeNodeKind][]string
	OnlyYears           []int
	ExcludeYears        []int
	OnlyMonths          []int
	ExcludeMonths       []int
	OnlyDays            []int
	ExcludeDays         []int
	OnlyStatus          string
	OnlyContributors    []string
	ExcludeContributors []string
	OnlyPolicies        []string
	ExcludePolicies     []string
}

// 🏷️HasOnlyKinds MUST return true only when the property is present.
// 🔍HasOnlyKinds reports whether the TreeFilter has only kinds.
func (f *TreeFilter) HasOnlyKinds() bool {
	return len(f.OnlyKinds) > 0
}

// 🔷IsKindVisible MUST return true only when the condition is met.
// ❓IsKindVisible reports whether the TreeFilter is kind visible.
func (f *TreeFilter) IsKindVisible(kind TreeNodeKind) bool {
	if kind == TreeNodeCategory {
		return true
	}
	if f.HasOnlyKinds() {
		return f.OnlyKinds[kind]
	}
	return !f.ExcludeKinds[kind]
}

// 📥MatchesSubKind MUST operate on the TreeFilter receiver and return consistent results.
func (f *TreeFilter) MatchesSubKind(kind TreeNodeKind, subKind string) bool {
	if subKind == "" {
		return true
	}
	if only, ok := f.OnlySubKinds[kind]; ok && len(only) > 0 {
		for _, s := range only {
			if strings.EqualFold(s, subKind) {
				return true
			}
		}
		return false
	}
	if exclude, ok := f.ExcludeSubKinds[kind]; ok {
		for _, s := range exclude {
			if strings.EqualFold(s, subKind) {
				return false
			}
		}
	}
	return true
}

// 🎯MatchesDate MUST operate on the TreeFilter receiver and return consistent results.
func (f *TreeFilter) MatchesDate(year, month, day int) bool {
	if len(f.OnlyYears) > 0 {
		found := false
		for _, y := range f.OnlyYears {
			if y == year {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, y := range f.ExcludeYears {
		if y == year {
			return false
		}
	}
	if len(f.OnlyMonths) > 0 && month > 0 {
		found := false
		for _, m := range f.OnlyMonths {
			if m == month {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, m := range f.ExcludeMonths {
		if m == month {
			return false
		}
	}
	if len(f.OnlyDays) > 0 && day > 0 {
		found := false
		for _, d := range f.OnlyDays {
			if d == day {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, d := range f.ExcludeDays {
		if d == day {
			return false
		}
	}
	return true
}

// 🔶MatchesStatus MUST operate on the TreeFilter receiver and return consistent results.
func (f *TreeFilter) MatchesStatus(status string) bool {
	if f.OnlyStatus == "" {
		return true
	}
	return strings.EqualFold(f.OnlyStatus, status)
}

// 🤝MatchesContributor MUST operate on the TreeFilter receiver and return consistent results.
func (f *TreeFilter) MatchesContributor(contributor string) bool {
	if len(f.OnlyContributors) > 0 {
		for _, c := range f.OnlyContributors {
			if strings.EqualFold(c, contributor) {
				return true
			}
		}
		return false
	}
	for _, c := range f.ExcludeContributors {
		if strings.EqualFold(c, contributor) {
			return false
		}
	}
	return true
}

// #endregion 🧨Monorepo Tree Types

// #endregion 🎺Models

// #region 🏩Tree Logic
// 🏢Tree construction, filtering, searching, and rendering for goals, sections, and monorepo nodes.
func buildGoalTree(goalsRaw []interface{}, ticketsRaw []interface{}) []*GoalNode {
	goalMap := make(map[string]*GoalNode)

	for _, g := range goalsRaw {
		if gm, ok := g.(map[string]interface{}); ok {
			id, _ := gm["id"].(string)
			title, _ := gm["title"].(string)
			status, _ := gm["status"].(string)
			dueDate, _ := gm["dueDate"].(string)
			createdAt, _ := gm["createdAt"].(string)
			description, _ := gm["description"].(string)
			node := &GoalNode{ID: id, Title: title, Status: status, DueDate: dueDate, CreatedAt: createdAt, Description: description}
			goalMap[id] = node
		}
	}

	var rootGoals []*GoalNode
	for _, g := range goalMap {
		parentID := ""
		if idx := strings.LastIndex(g.ID, "/"); idx >= 0 {
			parentID = g.ID[:idx]
		}
		if parentID != "" && parentID != g.ID {
			if parent, ok := goalMap[parentID]; ok {
				parent.Children = append(parent.Children, g)
			} else {
				rootGoals = append(rootGoals, g)
			}
		} else {
			rootGoals = append(rootGoals, g)
		}
	}

	var sortGoals func(goals []*GoalNode)
	sortGoals = func(goals []*GoalNode) {
		sort.SliceStable(goals, func(i, j int) bool {
			a, b := goals[i], goals[j]
			if a.DueDate != b.DueDate {
				if a.DueDate == "" {
					return false
				}
				if b.DueDate == "" {
					return true
				}
				return a.DueDate < b.DueDate
			}
			return a.ID < b.ID
		})
		for _, g := range goals {
			if len(g.Children) > 0 {
				sortGoals(g.Children)
			}
		}
	}
	sortGoals(rootGoals)

	allTickets := make([]*TicketNode, 0)
	for _, t := range ticketsRaw {
		if tm, ok := t.(map[string]interface{}); ok {
			id, _ := tm["id"].(string)
			slug, _ := tm["slug"].(string)
			status, _ := tm["status"].(string)
			title, _ := tm["title"].(string)
			goalID, _ := tm["goal"].(string)
			parentID, _ := tm["parent"].(string)
			prompt, _ := tm["prompt"].(string)
			summary, _ := tm["summary"].(string)

			created := ""
			finished := ""
			if dates, ok := tm["date"].(map[string]interface{}); ok {
				created, _ = dates["created"].(string)
				finished, _ = dates["finished"].(string)
			}

			if created == "" {
				created, _ = tm["createdAt"].(string)
			}

			uri := fmt.Sprintf("repo://ticket/%s%s", emojiText(EmojiTicket), Flat(slug))

			node := &TicketNode{ID: id, Slug: slug, Status: status, Title: title, URI: uri, GoalID: goalID, ParentID: parentID, Created: created, Finished: finished, Description: prompt, Summary: summary}
			allTickets = append(allTickets, node)
		}
	}

	var noGoalTickets []*TicketNode
	for _, t := range allTickets {
		if t.GoalID != "" {
			if g, ok := goalMap[t.GoalID]; ok {
				g.Tickets = append(g.Tickets, t)
			} else {
				noGoalTickets = append(noGoalTickets, t)
			}
		} else {
			noGoalTickets = append(noGoalTickets, t)
		}
	}

	nestTickets := func(nodes []*TicketNode) []*TicketNode {
		var roots []*TicketNode
		lookup := make(map[string]*TicketNode)
		for _, n := range nodes {
			lookup[n.ID] = n
		}
		for _, n := range nodes {
			if n.ParentID != "" && lookup[n.ParentID] != nil {
				lookup[n.ParentID].Children = append(lookup[n.ParentID].Children, n)
			} else {
				roots = append(roots, n)
			}
		}
		return roots
	}

	for _, g := range goalMap {
		g.Tickets = nestTickets(g.Tickets)
	}

	if len(noGoalTickets) > 0 {
		noGoal := &GoalNode{Title: "No Goal", Children: nil, Tickets: nestTickets(noGoalTickets)}
		rootGoals = append(rootGoals, noGoal)
	}

	return rootGoals
}

func countOpenSubgoals(g *GoalNode) int {
	c := 0
	for _, child := range g.Children {
		if child.Status == "open" {
			c++
		}
		c += countOpenSubgoals(child)
	}
	return c
}

// 🎫countOpenTickets holds the data fields for a countOpenTickets record.
func countOpenTickets(g *GoalNode) int {
	c := 0
	var countT func(ts []*TicketNode)
	countT = func(ts []*TicketNode) {
		for _, t := range ts {
			if t.Status == "open" {
				c++
			}
			countT(t.Children)
		}
	}
	countT(g.Tickets)
	for _, child := range g.Children {
		c += countOpenTickets(child)
	}
	return c
}

// 🎨renderGoalTree holds the data fields for a renderGoalTree record.
func renderGoalTree(goalsRaw []interface{}, ticketsRaw []interface{}, isTTY bool, useMD bool) string {
	roots := buildGoalTree(goalsRaw, ticketsRaw)
	format := "text"
	if useMD {
		format = "md"
	}
	return renderGoalTreeNodes(roots, format)
}

// 💿goalNodeToData holds the data fields for a goalNodeToData record.
func goalNodeToData(n *GoalNode) map[string]interface{} {
	return map[string]interface{}{
		"id":          n.ID,
		"title":       n.Title,
		"status":      n.Status,
		"dueDate":     n.DueDate,
		"createdAt":   n.CreatedAt,
		"description": n.Description,
	}
}

// 🌿ticketNodeToData holds the data fields for a ticketNodeToData record.
func ticketNodeToData(n *TicketNode) map[string]interface{} {
	data := map[string]interface{}{
		"slug":     n.Slug,
		"title":    n.Title,
		"status":   n.Status,
		"started":  n.Created,
		"finished": n.Finished,
		"prompt":   n.Description,
		"summary":  n.Summary,
	}
	return data
}

// ⛳renderGoalTreeNodes holds the data fields for a renderGoalTreeNodes record.
func renderGoalTreeNodes(roots []*GoalNode, format string) string {
	var sb strings.Builder

	var render func(node interface{}, prefix string, isLast bool, isRoot bool)
	render = func(node interface{}, prefix string, isLast bool, isRoot bool) {
		var lineContent string
		var children []interface{}

		switch n := node.(type) {
		case *GoalNode:
			data := goalNodeToData(n)
			if format == "md" {
				lineContent = renderEntityMarkdownLink("goal", data)
			} else {
				lineContent = renderEntityHuman("goal", data, false)
			}
			for _, c := range n.Children {
				children = append(children, c)
			}
			for _, t := range n.Tickets {
				children = append(children, t)
			}
		case *TicketNode:
			data := ticketNodeToData(n)
			if format == "md" {
				lineContent = renderEntityMarkdownLink("ticket", data)
			} else {
				lineContent = renderEntityHuman("ticket", data, false)
			}
			for _, c := range n.Children {
				children = append(children, c)
			}
		}

		if format == "text" {
			connector := ""
			if !isRoot {
				if isLast {
					connector = "└── "
				} else {
					connector = "├── "
				}
			}
			sb.WriteString(prefix + connector + lineContent + "\n")

			newPrefix := prefix
			if !isRoot {
				if isLast {
					newPrefix += "    "
				} else {
					newPrefix += "│   "
				}
			}

			for i, child := range children {
				render(child, newPrefix, i == len(children)-1, false)
			}
		} else {

			sb.WriteString(prefix + "- " + lineContent + "\n")
			newPrefix := prefix + "  "
			for i, child := range children {
				render(child, newPrefix, i == len(children)-1, false)
			}
		}
	}

	for i, root := range roots {
		render(root, "", i == len(roots)-1, true)
	}
	return sb.String()
}

func renderSectionTree(root *Section, isTTY bool, useMD bool) string {
	var sb strings.Builder

	var render func(s *Section, prefix string, isLast bool, isRoot bool)
	render = func(s *Section, prefix string, isLast bool, isRoot bool) {
		data := map[string]interface{}{
			"path":      s.Path,
			"name":      s.Name,
			"startLine": float64(s.StartLine),
			"endLine":   float64(s.EndLine),
		}

		var lineContent string
		if useMD {
			lineContent = renderEntityMarkdown("section", data)
		} else {
			lineContent = renderEntityHuman("section", data, false)
		}

		if !useMD {
			connector := ""
			if !isRoot {
				if isLast {
					connector = "└── "
				} else {
					connector = "├── "
				}
			}
			sb.WriteString(prefix + connector + lineContent + "\n")
			newPrefix := prefix
			if !isRoot {
				if isLast {
					newPrefix += "    "
				} else {
					newPrefix += "│   "
				}
			}
			for i := range s.Children {
				childPtr := &s.Children[i]
				render(childPtr, newPrefix, i == len(s.Children)-1, false)
			}
		} else {
			sb.WriteString(prefix + lineContent + "\n")
			newPrefix := prefix + "  "
			for i := range s.Children {
				childPtr := &s.Children[i]
				render(childPtr, newPrefix, i == len(s.Children)-1, false)
			}
		}
	}

	render(root, "", true, true)
	return sb.String()
}

// 📋renderTicketList holds the data fields for a renderTicketList record.
func renderTicketList(ticketsRaw []interface{}, isTTY bool, useMD bool) string {
	var sb strings.Builder

	for _, t := range ticketsRaw {
		if tm, ok := t.(map[string]interface{}); ok {
			if useMD {
				sb.WriteString(renderEntityMarkdown("ticket", tm) + "\n")
			} else {
				sb.WriteString("  " + renderEntityHuman("ticket", tm, false) + "\n")
			}
		}
	}
	return sb.String()
}

// #region 🩻Monorepo Tree
// Monorepo tree builder that assembles all entity nodes into a unified tree.

// 🌳TreeBuildOptions holds the data fields for a tree build options record.
type TreeBuildOptions struct {
	IncludeSections bool
}

// 🏢BuildMonorepoTree MUST assemble the monorepo tree from the available context data.
// 🏢BuildMonorepoTree constructs and returns the monorepo tree structure.
func BuildMonorepoTree(ctx context.Context, opts ...TreeBuildOptions) *TreeNode {
	var options TreeBuildOptions
	if len(opts) > 0 {
		options = opts[0]
	}
	root := &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}

	var technologies []Technology
	var goals []*Goal
	var drafts []*Draft
	var policies []PolicyDef
	var contributors []Contributor
	var checkpoints []Checkpoint
	var allFolders []Folder
	var allFiles []File
	var sessions []Session

	var wg sync.WaitGroup
	wg.Add(9)

	go func() {
		defer wg.Done()
		technologies = LoadTechnologies()
	}()
	go func() {
		defer wg.Done()
		goalCh := make(chan *Goal)
		go func() { StreamGoals(ctx, goalCh) }()
		for g := range goalCh {
			goals = append(goals, g)
		}
	}()
	go func() {
		defer wg.Done()
		drafts, _ = ListDrafts()
	}()
	go func() {
		defer wg.Done()
		policyCh := make(chan PolicyDef)
		go func() { StreamPolicies(ctx, policyCh) }()
		for p := range policyCh {
			policies = append(policies, p)
		}
	}()
	go func() {
		defer wg.Done()
		contribCh := make(chan Contributor)
		go func() { StreamContributors(ctx, contribCh) }()
		for c := range contribCh {
			contributors = append(contributors, c)
		}
	}()
	go func() {
		defer wg.Done()
		limit := 100
		checkpoints = LoadCheckpoints(&limit)
	}()
	go func() {
		defer wg.Done()
		folderCh := make(chan Folder)
		go func() { StreamFolders(ctx, "", folderCh) }()
		for f := range folderCh {
			allFolders = append(allFolders, f)
		}
	}()
	go func() {
		defer wg.Done()
		fileCh := make(chan File)
		go func() { StreamFiles(ctx, "", fileCh) }()
		for f := range fileCh {
			allFiles = append(allFiles, f)
		}
	}()
	go func() {
		defer wg.Done()
		sessionCh := make(chan Session)
		go func() { StreamSessions(ctx, sessionCh) }()
		for s := range sessionCh {
			sessions = append(sessions, s)
		}
	}()
	wg.Wait()

	codebaseNode := &TreeNode{Kind: TreeNodeCategory, ID: "codebase", Label: emojiText(EmojiCodebase) + "Codebase", URI: "repo://codebase"}
	sort.Slice(technologies, func(i, j int) bool { return technologies[i].Name < technologies[j].Name })

	type folderEntry struct {
		folder *Folder
		node   *TreeNode
	}
	globalFolderMap := make(map[string]*folderEntry)
	for fi := range allFolders {
		f := &allFolders[fi]
		fNode := &TreeNode{
			Kind:    TreeNodeFolder,
			ID:      f.GetID(),
			Label:   f.Name,
			URI:     f.GetURI(),
			SubKind: string(f.Kind),
			Data:    map[string]interface{}{"path": f.Path, "name": f.Name, "kind": string(f.Kind)},
		}
		globalFolderMap[f.Path] = &folderEntry{folder: f, node: fNode}
	}

	globalFileNodes := make(map[string]*TreeNode)
	for fi := range allFiles {
		f := &allFiles[fi]
		fileNode := &TreeNode{
			Kind:    TreeNodeFile,
			ID:      f.GetID(),
			Label:   f.Name,
			URI:     f.GetURI(),
			SubKind: f.Kind,
			Data:    map[string]interface{}{"path": f.Path, "name": f.Name, "kind": f.Kind},
		}
		if options.IncludeSections {
			absPath := filepath.Join(GetRootDir(), f.Path)
			content, err := ReadTextFile(absPath)
			if err == nil {
				sections := ParseSections(content, f.Path)
				definitions := ParseDefinitions(content, f.Path)
				sections = HydrateSectionsWithDefinitions(sections, definitions)
				for si := range sections {
					s := &sections[si]
					sNode := buildSectionTreeNode(s)
					fileNode.Children = append(fileNode.Children, sNode)
				}
			}
		}
		globalFileNodes[f.Path] = fileNode
	}

	folderRoots := buildFolderRoots(allFolders)
	for _, folderRoot := range folderRoots {
		codebaseNode.Children = append(codebaseNode.Children, folderRoot)
	}
	attachFilesToFolders(codebaseNode, allFiles, globalFileNodes)

	for pi := range technologies {
		p := &technologies[pi]
		pNode := &TreeNode{
			Kind:    TreeNodeTechnology,
			ID:      p.GetID(),
			Label:   p.Name,
			URI:     p.GetURI(),
			SubKind: string(p.Kind),
			Data:    map[string]interface{}{"name": p.Name, "kind": string(p.Kind), "emoji": p.Emoji},
		}
		sort.Slice(p.Bundles, func(i, j int) bool { return p.Bundles[i].Name < p.Bundles[j].Name })
		for bi := range p.Bundles {
			b := &p.Bundles[bi]
			bNode := &TreeNode{
				Kind:    TreeNodeBundle,
				ID:      b.GetID(),
				Label:   b.Name,
				URI:     b.GetURI(),
				SubKind: string(b.Kind),
				Data:    map[string]interface{}{"name": b.Name, "root": b.Root, "kind": string(b.Kind), "emoji": b.Emoji},
			}

			bundleRoot := b.Root
			if b.SourceRoot != "" {
				bundleRoot = b.SourceRoot
			}

			bundleFolderMap := make(map[string]*folderEntry)
			for path, fe := range globalFolderMap {
				if path == bundleRoot || strings.HasPrefix(path, bundleRoot+"/") {
					bundleFolderMap[path] = fe
				}
			}

			for path, fe := range bundleFolderMap {
				parentPath := filepath.Dir(path)
				if _, ok := bundleFolderMap[parentPath]; ok {
					continue
				}
				bNode.Children = append(bNode.Children, fe.node)
			}
			for path, fe := range bundleFolderMap {
				parentPath := filepath.Dir(path)
				if pfe, ok := bundleFolderMap[parentPath]; ok {
					pfe.node.Children = append(pfe.node.Children, fe.node)
				}
			}

			for path, fileNode := range globalFileNodes {
				if path != bundleRoot && !strings.HasPrefix(path, bundleRoot+"/") {
					continue
				}
				folderPath := filepath.Dir(path)
				if fe, ok := bundleFolderMap[folderPath]; ok {
					fe.node.Children = append(fe.node.Children, fileNode)
				} else {
					bNode.Children = append(bNode.Children, fileNode)
				}
			}

			sortTreeChildren(bNode)
			pNode.Children = append(pNode.Children, bNode)
		}
		codebaseNode.Children = append(codebaseNode.Children, pNode)
	}
	sortTreeChildren(codebaseNode)
	root.Children = append(root.Children, codebaseNode)

	goalsNode := &TreeNode{Kind: TreeNodeCategory, ID: "goals", Label: "🎯Goals", URI: "repo://goals"}
	goalMap := make(map[string]*TreeNode)
	sort.Slice(goals, func(i, j int) bool { return goals[i].ID < goals[j].ID })
	for _, g := range goals {
		goalCreatedAt := ""
		gNode := &TreeNode{
			Kind:        TreeNodeGoal,
			ID:          g.GetID(),
			Label:       g.Title,
			URI:         g.GetURI(),
			SubKind:     g.Status,
			Description: g.Description,
			Status:      g.Status,
			Data: map[string]interface{}{
				"id":          g.ID,
				"title":       g.Title,
				"status":      g.Status,
				"dueDate":     g.DueDate,
				"createdAt":   goalCreatedAt,
				"description": g.Description,
			},
		}
		goalMap[g.ID] = gNode
	}
	var rootGoals []*TreeNode
	for _, g := range goals {
		gNode := goalMap[g.ID]
		parentID := ""
		if idx := strings.LastIndex(g.ID, "/"); idx >= 0 {
			parentID = g.ID[:idx]
		}
		if parentID != "" && parentID != g.ID {
			if parent, ok := goalMap[parentID]; ok {
				parent.Children = append(parent.Children, gNode)
			} else {
				rootGoals = append(rootGoals, gNode)
			}
		} else {
			rootGoals = append(rootGoals, gNode)
		}
	}
	goalsNode.Children = rootGoals

	ticketCh := make(chan Ticket)
	go func() { StreamTickets(ctx, nil, nil, nil, ticketCh) }()
	var tickets []Ticket
	for t := range ticketCh {
		tickets = append(tickets, t)
	}
	for ti := range tickets {
		t := &tickets[ti]
		ticketStarted := t.GetDateStarted().Format(time.RFC3339)
		ticketFinished := ""
		if finished := t.GetDateFinished(); finished != nil {
			ticketFinished = finished.Format(time.RFC3339)
		}
		tNode := &TreeNode{
			Kind:        TreeNodeTicket,
			ID:          t.GetID(),
			Label:       t.Title,
			URI:         t.GetURI(),
			Description: t.Description,
			Year:        t.Year,
			Month:       t.Month,
			Day:         t.Day,
			Status:      string(t.Status),
			Data: map[string]interface{}{
				"year":     float64(t.Year),
				"month":    float64(t.Month),
				"day":      float64(t.Day),
				"slug":     t.Slug,
				"title":    t.Title,
				"status":   string(t.Status),
				"started":  ticketStarted,
				"finished": ticketFinished,
				"prompt":   t.Description,
				"summary":  t.Summary,
				"goalId":   t.Goal,
			},
		}
		if t.Goal != "" {
			if gNode, ok := goalMap[t.Goal]; ok {
				gNode.Children = append(gNode.Children, tNode)
				continue
			}
		}
		goalsNode.Children = append(goalsNode.Children, tNode)
	}
	root.Children = append(root.Children, goalsNode)

	draftsNode := &TreeNode{Kind: TreeNodeCategory, ID: "drafts", Label: "✍Drafts", URI: "repo://drafts"}
	if drafts != nil {
		for _, d := range drafts {
			dNode := &TreeNode{
				Kind:  TreeNodeDraft,
				ID:    d.GetID(),
				Label: d.ID,
				URI:   d.GetURI(),
				Data:  map[string]interface{}{"id": d.ID, "slug": d.ID},
			}
			draftsNode.Children = append(draftsNode.Children, dNode)
		}
	}
	root.Children = append(root.Children, draftsNode)

	policiesNode := &TreeNode{Kind: TreeNodeCategory, ID: "policies", Label: "🛡️️Policies", URI: "repo://policies"}
	sort.Slice(policies, func(i, j int) bool { return policies[i].ID < policies[j].ID })
	for _, p := range policies {
		policyId := emojiText(EmojiPolicy) + Flat(strings.TrimPrefix(p.ID, "/"))
		pNode := &TreeNode{
			Kind:        TreeNodePolicy,
			ID:          fmt.Sprintf("%s/%s", emojiText(EmojiPolicy), p.ID),
			Label:       p.Name,
			URI:         "repo://policy/" + policyId,
			Description: p.Description,
			Data:        map[string]interface{}{"id": p.ID, "name": p.Name, "description": p.Description},
		}
		pNode.Children = buildPolicyEntityKindTree(p.Groups)
		policiesNode.Children = append(policiesNode.Children, pNode)
	}
	root.Children = append(root.Children, policiesNode)

	contributorsNode := &TreeNode{Kind: TreeNodeCategory, ID: "contributors", Label: "🧑‍💻Contributors", URI: "repo://contributors"}
	sort.Slice(contributors, func(i, j int) bool { return contributors[i].Alias < contributors[j].Alias })
	for _, c := range contributors {
		label := c.Alias
		if c.Name != "" {
			label = c.Name + " (" + c.Alias + ")"
		}
		contributorData := map[string]interface{}{
			"alias":   c.Alias,
			"aliases": c.Aliases,
			"github":  c.Github,
			"githubs": c.Githubs,
			"name":    c.Name,
			"names":   c.Names,
			"email":   c.Email,
			"emails":  c.Emails,
		}
		cNode := &TreeNode{
			Kind:        TreeNodeContributor,
			ID:          c.GetID(),
			Label:       label,
			URI:         c.GetURI(),
			Contributor: c.Alias,
			Data:        contributorData,
		}
		contributorsNode.Children = append(contributorsNode.Children, cNode)
	}
	root.Children = append(root.Children, contributorsNode)

	checkpointsNode := &TreeNode{Kind: TreeNodeCategory, ID: "checkpoints", Label: "🔀Checkpoints", URI: "repo://checkpoints"}
	for ci := range checkpoints {
		c := &checkpoints[ci]
		cNode := &TreeNode{
			Kind:  TreeNodeCheckpoint,
			ID:    c.GetID(),
			Label: c.SHA[:8] + " " + c.Title,
			URI:   c.GetURI(),
			Year:  c.Date.Year(),
			Month: int(c.Date.Month()),
			Day:   c.Date.Day(),
			Data: map[string]interface{}{"sha": c.SHA, "message": c.Title, "authorId": func() string {
				if c.AuthorID != nil {
					return *c.AuthorID
				}
				return ""
			}()},
		}
		checkpointsNode.Children = append(checkpointsNode.Children, cNode)
	}
	root.Children = append(root.Children, checkpointsNode)

	sessionsNode := &TreeNode{Kind: TreeNodeCategory, ID: "sessions", Label: "⚪Sessions", URI: "repo://sessions"}
	sort.Slice(sessions, func(i, j int) bool { return sessions[i].StartedAt > sessions[j].StartedAt })
	for si := range sessions {
		s := &sessions[si]
		kindEmoji := SessionKindEmoji(s.Kind)
		label := kindEmoji + " " + s.UUID
		if s.Client != "" {
			label += " (" + s.Client + ")"
		}
		sNode := &TreeNode{
			Kind:    TreeNodeSession,
			ID:      s.GetID(),
			Label:   label,
			URI:     s.GetURI(),
			SubKind: string(s.Kind),
			Year:    s.Year,
			Month:   s.Month,
			Day:     s.Day,
			Status:  string(s.Kind),
			Data: map[string]interface{}{
				"uuid":       s.UUID,
				"kind":       string(s.Kind),
				"client":     s.Client,
				"startedAt":  s.StartedAt,
				"year":       float64(s.Year),
				"month":      float64(s.Month),
				"day":        float64(s.Day),
				"checkpoint": s.Checkpoint,
			},
		}
		sessionsNode.Children = append(sessionsNode.Children, sNode)
	}
	root.Children = append(root.Children, sessionsNode)

	PropagateParentIDs(root, "")
	return root
}

// 💿PropagateParentIDs holds the data fields for a PropagateParentIDs record.
func PropagateParentIDs(node *TreeNode, parentArtifactID string) {
	if node.Data == nil {
		node.Data = map[string]interface{}{}
	}
	entityKind := treeNodeKindToEntityKind(node.Kind)
	currentID := ""
	if entityKind != "" && node.Data != nil {
		node.Data["parentId"] = parentArtifactID
		currentID = GetArtifactID(entityKind, node.Data)
	} else {
		currentID = parentArtifactID
	}
	for _, child := range node.Children {
		PropagateParentIDs(child, currentID)
	}
}

// 📑buildSectionTreeNode holds the data fields for a buildSectionTreeNode record.
func buildSectionTreeNode(s *Section) *TreeNode {
	sNode := &TreeNode{
		Kind:  TreeNodeSection,
		ID:    s.GetID(),
		Label: s.Name,
		URI:   s.GetURI(),
		Data:  map[string]interface{}{"path": s.Path, "name": s.Name, "startLine": float64(s.StartLine), "endLine": float64(s.EndLine)},
	}
	for di := range s.Definitions {
		d := &s.Definitions[di]
		dNode := &TreeNode{
			Kind:    TreeNodeDefinition,
			ID:      d.GetID(),
			Label:   d.Name,
			URI:     d.GetURI(),
			SubKind: string(d.Kind),
			Data:    map[string]interface{}{"path": d.FilePath, "name": d.Name, "kind": string(d.Kind), "startLine": float64(d.StartLine), "endLine": float64(d.EndLine)},
		}
		sNode.Children = append(sNode.Children, dNode)
	}
	for ci := range s.Children {
		child := &s.Children[ci]
		sNode.Children = append(sNode.Children, buildSectionTreeNode(child))
	}
	return sNode
}

// 🏗️buildStatuteTree holds the data fields for a buildStatuteTree record.
func buildStatuteTree(kinds []Statute) []*TreeNode {
	type treeEntry struct {
		node     *TreeNode
		children map[string]*treeEntry
	}
	rootEntries := make(map[string]*treeEntry)
	orderedRootKeys := []string{}

	for _, k := range kinds {
		parts := strings.Split(string(k), "/")
		current := rootEntries
		currentOrdered := &orderedRootKeys
		for i, part := range parts {
			if _, ok := current[part]; !ok {
				isLeaf := i == len(parts)-1
				meta := k.Info()
				n := &TreeNode{
					Kind:  TreeNodeStatute,
					ID:    string(k),
					Label: part,
					URI:   meta.GetURI(),
				}
				if isLeaf {
					n.Description = meta.Reason
					priorityIcon := "🟢"
					if meta.Priority == BreachPriorityHigh {
						priorityIcon = "🔴"
					} else if meta.Priority == BreachPriorityMedium {
						priorityIcon = "🟡"
					}
					n.Label = priorityIcon + part
					if meta.Autofixable {
						n.SubKind = "autofixable"
					}
					n.Data = map[string]interface{}{
						"id":          string(k),
						"priority":    string(meta.Priority),
						"autofixable": meta.Autofixable,
						"reason":      meta.Reason,
						"solution":    meta.Solution,
					}
				} else {
					prefix := strings.Join(parts[:i+1], "/")
					n.ID = "breachCategory:" + prefix
					n.URI = "repo://statute/" + Flat(prefix)
					n.Kind = TreeNodeCategory
				}
				current[part] = &treeEntry{node: n, children: make(map[string]*treeEntry)}
				*currentOrdered = append(*currentOrdered, part)
			}
			entry := current[part]
			current = entry.children
			childKeys := []string{}
			for ck := range entry.children {
				childKeys = append(childKeys, ck)
			}
			currentOrdered = &childKeys
		}
	}

	var buildNodes func(entries map[string]*treeEntry, keys []string) []*TreeNode
	buildNodes = func(entries map[string]*treeEntry, keys []string) []*TreeNode {
		seen := map[string]bool{}
		var result []*TreeNode
		for _, key := range keys {
			if seen[key] {
				continue
			}
			seen[key] = true
			entry := entries[key]
			childKeys := []string{}
			for ck := range entry.children {
				childKeys = append(childKeys, ck)
			}
			sort.Strings(childKeys)
			entry.node.Children = buildNodes(entry.children, childKeys)
			result = append(result, entry.node)
		}
		return result
	}

	return buildNodes(rootEntries, orderedRootKeys)
}

// 🔷buildTerritoryTree holds the data fields for a buildTerritoryTree record.
func buildTerritoryTree(groups []Territory) []*TreeNode {
	var result []*TreeNode
	for _, g := range groups {
		groupNode := &TreeNode{
			Kind:        TreeNodeCategory,
			ID:          fmt.Sprintf("%s%s", emojiText(EmojiTerritory), g.Name),
			Label:       g.Name,
			URI:         "repo://territory/" + g.GetID(),
			Description: g.Description,
			SubKind:     "territory",
			Data: map[string]interface{}{
				"name":        g.Name,
				"description": g.Description,
				"scopes":      g.Scopes,
			},
		}
		for _, k := range g.Kinds {
			meta := k.Info()
			priorityIcon := "🟢"
			if meta.Priority == BreachPriorityHigh {
				priorityIcon = "🔴"
			} else if meta.Priority == BreachPriorityMedium {
				priorityIcon = "🟡"
			}
			label := priorityIcon + StatutePathToIdValue(string(k))
			vkNode := &TreeNode{
				Kind:        TreeNodeStatute,
				ID:          meta.GetID(),
				Label:       label,
				URI:         meta.GetURI(),
				Description: meta.Reason,
				Data: map[string]interface{}{
					"id":          string(k),
					"priority":    string(meta.Priority),
					"autofixable": meta.Autofixable,
					"reason":      meta.Reason,
					"solution":    meta.Solution,
				},
			}
			if meta.Autofixable {
				vkNode.SubKind = "autofixable"
			}
			groupNode.Children = append(groupNode.Children, vkNode)
		}
		groupNode.Children = append(groupNode.Children, buildTerritoryTree(g.Groups)...)
		result = append(result, groupNode)
	}
	return result
}

// 📶sortTreeChildren holds the data fields for a sortTreeChildren record.
func sortTreeChildren(node *TreeNode) {
	sort.Slice(node.Children, func(i, j int) bool {
		a, b := node.Children[i], node.Children[j]
		if a.Kind != b.Kind {
			aIsFolder := a.Kind == TreeNodeFolder
			bIsFolder := b.Kind == TreeNodeFolder
			if aIsFolder != bIsFolder {
				return aIsFolder
			}
		}
		return a.Label < b.Label
	})
	for _, c := range node.Children {
		sortTreeChildren(c)
	}
}

// 🧹FilterMonorepoTree MUST preserve the tree structure while removing non-matching nodes.
// 🔍FilterMonorepoTree filters the monorepo tree based on the given criteria.
func FilterMonorepoTree(root *TreeNode, filter *TreeFilter) *TreeNode {
	if filter == nil {
		return root
	}

	filtered := filterNode(root, filter)
	if filtered == nil {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}

	if filter.HasOnlyKinds() || len(filter.ExcludeKinds) > 0 {
		collapseFilteredKinds(filtered, filter)
	}

	return filtered
}

func filterNode(node *TreeNode, filter *TreeFilter) *TreeNode {
	if node.Kind != TreeNodeCategory {
		if !filter.IsKindVisible(node.Kind) {
			var kept []*TreeNode
			for _, c := range node.Children {
				fc := filterNode(c, filter)
				if fc != nil {
					kept = append(kept, fc)
				}
			}
			if len(kept) > 0 {
				copy := *node
				copy.Children = kept
				return &copy
			}
			return nil
		}
		if !filter.MatchesSubKind(node.Kind, node.SubKind) {
			return nil
		}
		if node.Year > 0 && !filter.MatchesDate(node.Year, node.Month, node.Day) {
			return nil
		}
		if node.Status != "" && !filter.MatchesStatus(node.Status) {
			return nil
		}
		if node.Contributor != "" && !filter.MatchesContributor(node.Contributor) {
			return nil
		}
	}

	var kept []*TreeNode
	for _, c := range node.Children {
		fc := filterNode(c, filter)
		if fc != nil {
			kept = append(kept, fc)
		}
	}

	if node.Kind == TreeNodeCategory && len(kept) == 0 {
		return nil
	}

	copy := *node
	copy.Children = kept
	return &copy
}

// 🏷️collapseFilteredKinds holds the data fields for a collapseFilteredKinds record.
func collapseFilteredKinds(node *TreeNode, filter *TreeFilter) {
	var newChildren []*TreeNode
	for _, c := range node.Children {
		if c.Kind != TreeNodeCategory && !filter.IsKindVisible(c.Kind) {
			collapseFilteredKinds(c, filter)
			newChildren = append(newChildren, c.Children...)
		} else {
			collapseFilteredKinds(c, filter)
			newChildren = append(newChildren, c)
		}
	}
	node.Children = newChildren
}

func searchMonorepoTreeWithCache(ctx context.Context, root *TreeNode, query string) *TreeNode {
	if query == "" {
		return root
	}
	idx, err := ensureCacheIndexed(ctx, root)
	if err != nil {
		return searchTreeInMemory(root, query)
	}
	defer idx.Close()

	matchedIDs, err := queryCacheIndex(idx, query, countSearchableTreeNodes(root))
	if err != nil {
		return searchTreeInMemory(root, query)
	}
	if len(matchedIDs) == 0 {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	pruned := pruneUnmatched(root, sliceToSet(matchedIDs))
	if pruned == nil {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	return pruned
}

// 📝SearchMonorepoTree MUST match case-insensitively against node labels and descriptions.
// 🔤SearchMonorepoTree performs a text search across the monorepo tree.
func SearchMonorepoTree(root *TreeNode, query string) *TreeNode {
	if query == "" {
		return root
	}
	return searchTreeInMemory(root, query)
}

func countSearchableTreeNodes(root *TreeNode) int {
	count := 0
	var walk func(node *TreeNode)
	walk = func(node *TreeNode) {
		if node.Kind != TreeNodeCategory {
			count++
		}
		for _, child := range node.Children {
			walk(child)
		}
	}
	walk(root)
	if count == 0 {
		return 1
	}
	return count
}

func sliceToSet(values []string) map[string]bool {
	result := make(map[string]bool, len(values))
	for _, value := range values {
		result[value] = true
	}
	return result
}

func serializeTreeNodeData(data map[string]interface{}) string {
	if len(data) == 0 {
		return ""
	}
	parts := make([]string, 0, len(data))
	for _, value := range data {
		switch typed := value.(type) {
		case string:
			parts = append(parts, typed)
		case []string:
			parts = append(parts, strings.Join(typed, " "))
		case []interface{}:
			var values []string
			for _, item := range typed {
				values = append(values, fmt.Sprint(item))
			}
			parts = append(parts, strings.Join(values, " "))
		default:
			parts = append(parts, fmt.Sprint(typed))
		}
	}
	return strings.Join(parts, " ")
}

func buildSearchDocumentText(node *TreeNode) string {
	parts := []string{
		node.Label,
		node.ID,
		node.SubKind,
		node.Description,
		node.URI,
		node.Status,
		node.Contributor,
		string(node.Kind),
		serializeTreeNodeData(node.Data),
	}
	for _, child := range node.Children {
		if child.Kind != TreeNodeCategory {
			parts = append(parts, child.Label, child.ID, child.Description, serializeTreeNodeData(child.Data))
		}
	}
	return strings.Join(parts, " ")
}

// 🔶levenshtein holds the data fields for a levenshtein record.
func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	curr := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		curr[0] = i
		for j := 1; j <= lb; j++ {
			cost := 0
			if a[i-1] != b[j-1] {
				cost = 1
			}
			ins := curr[j-1] + 1
			del := prev[j] + 1
			sub := prev[j-1] + cost
			m := ins
			if del < m {
				m = del
			}
			if sub < m {
				m = sub
			}
			curr[j] = m
		}
		prev, curr = curr, prev
	}
	return prev[lb]
}

// 🔹fuzzyContains holds the data fields for a fuzzyContains record.
func fuzzyContains(text, term string) bool {
	if strings.Contains(text, term) {
		return true
	}
	maxDist := 1
	if len(term) > 5 {
		maxDist = 2
	}
	words := strings.Fields(text)
	for _, w := range words {
		if levenshtein(w, term) <= maxDist {
			return true
		}
		if len(w) >= len(term) {
			for i := 0; i <= len(w)-len(term)+maxDist && i <= len(w)-1; i++ {
				end := i + len(term) + maxDist
				if end > len(w) {
					end = len(w)
				}
				sub := w[i:end]
				if levenshtein(sub, term) <= maxDist {
					return true
				}
			}
		}
	}
	return false
}

// 🔎searchTreeInMemory holds the data fields for a searchTreeInMemory record.
func searchTreeInMemory(root *TreeNode, query string) *TreeNode {
	terms := strings.Fields(strings.ToLower(query))
	if len(terms) == 0 {
		return root
	}
	matchedIDs := make(map[string]bool)
	var walk func(node *TreeNode)
	walk = func(node *TreeNode) {
		if node.Kind != TreeNodeCategory {
			docID := node.ID
			if docID == "" {
				docID = node.Label
			}
			text := strings.ToLower(buildSearchDocumentText(node))
			allMatch := true
			for _, term := range terms {
				if !fuzzyContains(text, term) {
					allMatch = false
					break
				}
			}
			if allMatch {
				matchedIDs[docID] = true
			}
		}
		for _, c := range node.Children {
			walk(c)
		}
	}
	walk(root)
	if len(matchedIDs) == 0 {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	pruned := pruneUnmatched(root, matchedIDs)
	if pruned == nil {
		return &TreeNode{Kind: TreeNodeCategory, Label: ".", Children: []*TreeNode{}}
	}
	return pruned
}

// 🎯pruneUnmatched holds the data fields for a pruneUnmatched record.
func pruneUnmatched(node *TreeNode, matchedIDs map[string]bool) *TreeNode {
	return pruneUnmatchedInner(node, matchedIDs, false)
}

// 🔸pruneUnmatchedInner holds the data fields for a pruneUnmatchedInner record.
func pruneUnmatchedInner(node *TreeNode, matchedIDs map[string]bool, ancestorMatched bool) *TreeNode {
	docID := node.ID
	if docID == "" {
		docID = node.Label
	}
	selfMatched := matchedIDs[docID]
	keepDescendants := ancestorMatched || selfMatched
	var kept []*TreeNode
	for _, c := range node.Children {
		fc := pruneUnmatchedInner(c, matchedIDs, keepDescendants)
		if fc != nil {
			kept = append(kept, fc)
		}
	}
	if keepDescendants || len(kept) > 0 || node.Kind == TreeNodeCategory {
		if node.Kind == TreeNodeCategory && len(kept) == 0 && !selfMatched && !ancestorMatched {
			return nil
		}
		copy := *node
		copy.Children = kept
		return &copy
	}
	return nil
}

// 🎨RenderMonorepoTree MUST produce a complete monorepo tree output.
// 🎨RenderMonorepoTree renders the monorepo tree into its output representation.
func RenderMonorepoTree(root *TreeNode) string {
	var sb strings.Builder
	for i, c := range root.Children {
		renderTreeNodeText(&sb, c, "", i == len(root.Children)-1, true)
	}
	return sb.String()
}

// 📰RenderMonorepoTreeMarkdown MUST produce a complete monorepo tree markdown output.
// 📰RenderMonorepoTreeMarkdown renders the monorepo tree markdown into its output representation.
func RenderMonorepoTreeMarkdown(root *TreeNode) string {
	var sb strings.Builder
	for _, c := range root.Children {
		renderTreeNodeMarkdown(&sb, c, "")
	}
	return sb.String()
}

// 🌿treeNodeKindToEntityKind holds the data fields for a treeNodeKindToEntityKind record.
func treeNodeKindToEntityKind(k TreeNodeKind) string {
	switch k {
	case TreeNodeTechnology:
		return "technology"
	case TreeNodeBundle:
		return "bundle"
	case TreeNodeFolder:
		return "folder"
	case TreeNodeFile:
		return "file"
	case TreeNodeSection:
		return "section"
	case TreeNodeDefinition:
		return "definition"
	case TreeNodeGoal:
		return "goal"
	case TreeNodeTicket:
		return "ticket"
	case TreeNodeDraft:
		return "draft"
	case TreeNodeTodo:
		return "todo"
	case TreeNodePolicy:
		return "policy"
	case TreeNodeBreach:
		return "breach"
	case TreeNodeContributor:
		return "contributor"
	case TreeNodeCheckpoint:
		return "checkpoint"
	case TreeNodeSession:
		return "session"
	case TreeNodeCategory:
		return ""
	}
	return ""
}

// 🔺renderTreeNodeText holds the data fields for a renderTreeNodeText record.
func renderTreeNodeText(sb *strings.Builder, node *TreeNode, prefix string, isLast bool, isRoot bool) {
	connector := "├── "
	if isLast {
		connector = "└── "
	}
	if isRoot {
		connector = ""
	}

	label := node.Label
	if node.Kind == TreeNodeCategory {
		if node.URI != "" {
			label = "[" + node.Label + "](" + node.URI + ")"
		}
	} else if node.Data != nil {
		entityKind := treeNodeKindToEntityKind(node.Kind)
		if entityKind == "" {
			entityKind = string(node.Kind)
		}
		origParentId, hadParentId := node.Data["parentId"]
		node.Data["parentId"] = ""
		result := renderEntityHuman(entityKind, node.Data, false)
		if hadParentId {
			node.Data["parentId"] = origParentId
		} else {
			delete(node.Data, "parentId")
		}
		if result != "" {
			label = result
		}
	}

	sb.WriteString(prefix + connector + label + "\n")

	newPrefix := prefix
	if !isRoot {
		if isLast {
			newPrefix += "    "
		} else {
			newPrefix += "│   "
		}
	}

	for i, c := range node.Children {
		renderTreeNodeText(sb, c, newPrefix, i == len(node.Children)-1, false)
	}
}

// 🔻renderTreeNodeMarkdown holds the data fields for a renderTreeNodeMarkdown record.
func renderTreeNodeMarkdown(sb *strings.Builder, node *TreeNode, indent string) {
	if node.Kind == TreeNodeCategory {
		sb.WriteString(renderTemplate(mdTpl, "md/tree_node_category", map[string]interface{}{
			"Indent": indent,
			"Label":  node.Label,
			"URI":    node.URI,
		}) + "\n")
	} else if node.Data != nil {
		entityKind := treeNodeKindToEntityKind(node.Kind)
		if entityKind == "" {
			entityKind = string(node.Kind)
		}
		sb.WriteString(renderTemplate(mdTpl, "md/tree_node_entity", map[string]interface{}{
			"Indent":  indent,
			"Content": renderEntityMarkdown(entityKind, node.Data),
		}) + "\n")
	} else {
		sb.WriteString(renderTemplate(mdTpl, "md/tree_node_category", map[string]interface{}{
			"Indent": indent,
			"Label":  node.Label,
			"URI":    node.URI,
		}) + "\n")
	}
	for _, c := range node.Children {
		renderTreeNodeMarkdown(sb, c, indent+"  ")
	}
}

// #endregion 🩻Monorepo Tree

// #region 🎊Query Cache
// Local Bleve index under .repo/cache for keyword search. Uses composite git fingerprint (supertechnology HEAD, dirty state, submodule pointers and working state) for invalidation. Supports incremental updates via git diff.
// 📌cacheSchemaVersion holds the data fields for a cacheSchemaVersion record.
const cacheSchemaVersion = 3

// 💿cacheMeta holds the data fields for a cacheMeta record.
type cacheMeta struct {
	SchemaVersion     int               `json:"SchemaVersion"`
	SuperHead         string            `json:"SuperHead"`
	SuperDirtyHash    string            `json:"SuperDirtyHash"`
	SubmodulePointers map[string]string `json:"SubmodulePointers"`
	SubmoduleHeads    map[string]string `json:"SubmoduleHeads,omitempty"`
	SubmoduleDirty    map[string]string `json:"SubmoduleDirty,omitempty"`
	PointersHash      string            `json:"PointersHash"`
	SubWorkingHash    string            `json:"SubWorkingHash"`
	Fingerprint       string            `json:"Fingerprint"`
	IncludeSections   bool              `json:"IncludeSections"`
}

// 💾getCacheDir holds the data fields for a getCacheDir record.
func getCacheDir() string {
	abs, _ := filepath.Abs(GetRootDir())
	h := sha256.Sum256([]byte(abs))
	return filepath.Join(GetRepoMetaDir(), "cache", hex.EncodeToString(h[:]))
}

func computeCompositeFingerprint(repoRoot string) (fp string, meta *cacheMeta) {
	meta = &cacheMeta{
		SchemaVersion:     cacheSchemaVersion,
		SubmodulePointers: map[string]string{},
		SubmoduleHeads:    map[string]string{},
		SubmoduleDirty:    map[string]string{},
	}
	stdout, _, _ := ExecCommand("git", []string{"rev-parse", "HEAD"}, repoRoot)
	meta.SuperHead = strings.TrimSpace(stdout)
	statusOut, _, _ := ExecCommand("git", []string{"status", "--porcelain", "-z", "--untracked-files=no"}, repoRoot)
	meta.SuperDirtyHash = hashString(statusOut)
	subOut := getSubmoduleStatus(repoRoot)
	lines := strings.Split(strings.TrimSpace(subOut), "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		path := parts[1]
		meta.SubmodulePointers[path] = parts[0]
		if strings.HasPrefix(parts[0], "-") {
			continue
		}
		subPath := filepath.Join(repoRoot, path)
		subHead, _, _ := ExecCommand("git", []string{"rev-parse", "HEAD"}, subPath)
		meta.SubmoduleHeads[path] = strings.TrimSpace(subHead)
		subStatus, _, _ := ExecCommand("git", []string{"status", "--porcelain", "-z", "--untracked-files=no"}, subPath)
		meta.SubmoduleDirty[path] = hashString(subStatus)
	}
	meta.PointersHash = hashString(subOut)
	paths := make([]string, 0, len(meta.SubmoduleHeads))
	for k := range meta.SubmoduleHeads {
		paths = append(paths, k)
	}
	sort.Strings(paths)
	var subWork []string
	for _, path := range paths {
		subWork = append(subWork, path+"="+meta.SubmoduleHeads[path]+":"+meta.SubmoduleDirty[path])
	}
	semioMetaHash := hashSemioMetaState(repoRoot)
	meta.SubWorkingHash = hashString(strings.Join(subWork, "|"))
	fp = hashString(meta.SuperHead + meta.SuperDirtyHash + meta.PointersHash + meta.SubWorkingHash + semioMetaHash + strconv.Itoa(cacheSchemaVersion))
	meta.Fingerprint = fp
	return fp, meta
}

// 🧭getSubmoduleStatus returns recursive submodule status when available.
func getSubmoduleStatus(repoRoot string) string {
	stdout, _, exitCode := ExecCommand("git", []string{"submodule", "status", "--recursive"}, repoRoot)
	if exitCode == 0 {
		return stdout
	}
	fallback, _, fallbackExitCode := ExecCommand("git", []string{"submodule", "status"}, repoRoot)
	if fallbackExitCode == 0 {
		return fallback
	}
	return stdout
}

// ♻️hashSemioMetaState MUST produce a stable hash for semio metadata state changes.
// hashSemioMetaState computes and returns a hash for semio metadata content relevant to tree cache invalidation.
// Only structural changes (new goals, tickets, policies, drafts) invalidate the cache.
// ✏️Ephemeral data (agent session logs, ticket agent tracking updates) is excluded.
func hashSemioMetaState(repoRoot string) string {
	metaRoot := filepath.Join(repoRoot, ".repo")
	if !FileExists(metaRoot) {
		return ""
	}

	var entries []string
	_ = filepath.WalkDir(metaRoot, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		rel, relErr := filepath.Rel(metaRoot, path)
		if relErr != nil {
			return nil
		}
		rel = filepath.ToSlash(rel)
		if rel == "." {
			return nil
		}
		// Skip directories that are either caches or ephemeral hook artifacts.
		// These change frequently and must not invalidate the tree cache.
		switch {
		case rel == "cache" || strings.HasPrefix(rel, "cache/"):
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		case rel == "⚡" || strings.HasPrefix(rel, "⚡/"):
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if d.IsDir() {
			entries = append(entries, "d:"+rel)
			return nil
		}
		// For ticket files, hooks constantly update agent tracking metadata
		// (via trackHookInOpenTicket) without changing tree-relevant structure.
		// Only track ticket directory existence (not file contents/modtimes)
		// so the cache invalidates on ticket open/close but not on every hook.
		if strings.Contains(rel, "🎫") && !d.IsDir() {
			return nil
		}
		info, statErr := d.Info()
		if statErr != nil {
			return nil
		}
		entries = append(entries, fmt.Sprintf("f:%s:%d:%d", rel, info.Size(), info.ModTime().UnixNano()))
		return nil
	})

	sort.Strings(entries)
	return hashString(strings.Join(entries, "|"))
}

func treeNodeScopePath(node *TreeNode) string {
	if node.Data == nil {
		return ""
	}
	switch node.Kind {
	case TreeNodeFile, TreeNodeFolder:
		if p, ok := node.Data["path"].(string); ok {
			return p
		}
	case TreeNodeBundle:
		if r, ok := node.Data["root"].(string); ok {
			return r
		}
	case TreeNodeTechnology:
		if n, ok := node.Data["name"].(string); ok {
			return "technology:" + n
		}
	}
	return ""
}

// 🔤hashString holds the data fields for a hashString record.
func hashString(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

// 🔷loadCacheMeta holds the data fields for a loadCacheMeta record.
func loadCacheMeta() (*cacheMeta, error) {
	p := filepath.Join(getCacheDir(), "meta.json")
	data, err := os.ReadFile(p)
	if err != nil {
		return nil, err
	}
	var m cacheMeta
	if err := json.Unmarshal(data, &m); err != nil {
		return nil, err
	}
	if m.SchemaVersion != cacheSchemaVersion {
		return nil, fmt.Errorf("schema version mismatch")
	}
	return &m, nil
}

// 🔶saveCacheMeta holds the data fields for a saveCacheMeta record.
func saveCacheMeta(m *cacheMeta) error {
	dir := getCacheDir()
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "meta.json"), data, 0644)
}

// 🛤️getChangedPathsFromGit holds the data fields for a getChangedPathsFromGit record.
func getChangedPathsFromGit(repoRoot string) []string {
	statusOut, _, _ := ExecCommand("git", []string{"status", "--porcelain", "-z"}, repoRoot)
	diffOut, _, _ := ExecCommand("git", []string{"diff", "--name-only", "HEAD"}, repoRoot)
	untrackedOut, _, _ := ExecCommand("git", []string{"ls-files", "-o", "--exclude-standard"}, repoRoot)
	paths := make(map[string]bool)
	for _, s := range strings.Split(strings.TrimSpace(statusOut), "\x00") {
		s = strings.TrimSpace(s)
		if len(s) >= 4 {
			paths[strings.TrimSpace(s[3:])] = true
		}
	}
	for _, p := range strings.Split(strings.TrimSpace(diffOut), "\n") {
		p = strings.TrimSpace(p)
		if p != "" {
			paths[p] = true
		}
	}
	for _, p := range strings.Split(strings.TrimSpace(untrackedOut), "\n") {
		if p != "" {
			paths[p] = true
		}
	}
	var result []string
	for p := range paths {
		result = append(result, p)
	}
	return result
}

// 🔹expandPathsWithAncestors holds the data fields for a expandPathsWithAncestors record.
func expandPathsWithAncestors(paths []string) []string {
	technologies := LoadTechnologies()
	bundleByPath := make(map[string]string)
	technologyByBundle := make(map[string]string)
	for _, p := range technologies {
		for _, b := range p.Bundles {
			root := b.Root
			if b.SourceRoot != "" {
				root = b.SourceRoot
			}
			bundleByPath[root] = root
			technologyByBundle[root] = "technology:" + p.Name
		}
	}
	expanded := make(map[string]bool)
	for _, p := range paths {
		expanded[p] = true
		dir := p
		for {
			dir = filepath.Dir(dir)
			if dir == "." || dir == "" {
				break
			}
			expanded[dir] = true
		}
		var bundle string
		for root := range bundleByPath {
			if strings.HasPrefix(p, root+"/") || p == root {
				if len(root) > len(bundle) {
					bundle = root
				}
			}
		}
		if bundle != "" {
			expanded[bundle] = true
			if proj := technologyByBundle[bundle]; proj != "" {
				expanded[proj] = true
			}
		}
	}
	var result []string
	for p := range expanded {
		result = append(result, p)
	}
	return result
}

func pathToNodesMap(root *TreeNode) map[string][]*TreeNode {
	m := make(map[string][]*TreeNode)
	var walk func(node *TreeNode)
	walk = func(node *TreeNode) {
		if node.Kind != TreeNodeCategory {
			p := treeNodeScopePath(node)
			if p != "" {
				m[p] = append(m[p], node)
			}
		}
		for _, c := range node.Children {
			walk(c)
		}
	}
	walk(root)
	return m
}

// 🔸ensureCacheIndexed holds the data fields for a ensureCacheIndexed record.
func ensureCacheIndexed(ctx context.Context, root *TreeNode) (bleve.Index, error) {
	repoRoot := GetRootDir()
	fp, newMeta := computeCompositeFingerprint(repoRoot)
	dir := getCacheDir()
	idxPath := filepath.Join(dir, "index.bleve")
	lockPath := filepath.Join(dir, ".lock")

	existing, loadErr := loadCacheMeta()
	if loadErr == nil && existing.Fingerprint == fp {
		idx, openErr := bleve.Open(idxPath)
		if openErr == nil {
			return idx, nil
		}
	}
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, err
	}
	var lock *os.File
	var err error
	for i := 0; i < 60; i++ {
		lock, err = os.OpenFile(lockPath, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0644)
		if err == nil {
			break
		}
		if fi, e := os.Stat(lockPath); e == nil && time.Since(fi.ModTime()) > 5*time.Minute {
			os.Remove(lockPath)
		}
		if i < 59 {
			time.Sleep(200 * time.Millisecond)
		}
	}
	if err != nil {
		return nil, err
	}
	lock.Close()
	defer os.Remove(lockPath)

	idx, openErr := bleve.Open(idxPath)
	if openErr == nil {
		changedPaths := getChangedPathsFromGit(repoRoot)
		if len(changedPaths) > 0 {
			pathsToUpdate := expandPathsWithAncestors(changedPaths)
			pathToNodes := pathToNodesMap(root)
			for _, scopePath := range pathsToUpdate {
				for _, node := range pathToNodes[scopePath] {
					docID := node.ID
					if docID == "" {
						docID = node.Label
					}
					idx.Delete(docID)
				}
			}
			indexDoc := func(node *TreeNode) {
				if node.Kind == TreeNodeCategory {
					return
				}
				docID := node.ID
				if docID == "" {
					docID = node.Label
				}
				doc := map[string]interface{}{"text": buildSearchDocumentText(node)}
				if p := treeNodeScopePath(node); p != "" {
					doc["path"] = p
				}
				idx.Index(docID, doc)
			}
			for _, scopePath := range pathsToUpdate {
				for _, node := range pathToNodes[scopePath] {
					indexDoc(node)
				}
			}
			if err := saveCacheMeta(newMeta); err != nil {
				idx.Close()
				return nil, err
			}
			return idx, nil
		}
		idx.Close()
	}

	os.RemoveAll(idxPath)
	time.Sleep(100 * time.Millisecond)
	os.RemoveAll(idxPath)
	mapping := bleve.NewIndexMapping()
	idx, err = bleve.New(idxPath, mapping)
	if err != nil {
		return nil, err
	}

	var indexNodes func(node *TreeNode)
	indexNodes = func(node *TreeNode) {
		if node.Kind != TreeNodeCategory {
			docID := node.ID
			if docID == "" {
				docID = node.Label
			}
			doc := map[string]interface{}{"text": buildSearchDocumentText(node)}
			if p := treeNodeScopePath(node); p != "" {
				doc["path"] = p
			}
			idx.Index(docID, doc)
		}
		for _, c := range node.Children {
			indexNodes(c)
		}
	}
	indexNodes(root)

	if err := saveCacheMeta(newMeta); err != nil {
		idx.Close()
		return nil, err
	}
	return idx, nil
}

// 🔍queryCacheIndex holds the data fields for a queryCacheIndex record.
func queryCacheIndex(idx bleve.Index, query string, limit int) ([]string, error) {
	if query == "" {
		return nil, nil
	}
	terms := strings.Fields(query)
	queries := make([]blevequery.Query, 0, len(terms))
	for _, term := range terms {
		match := bleve.NewMatchQuery(term)
		match.SetFuzziness(2)
		queries = append(queries, match)
	}
	var q blevequery.Query
	switch len(queries) {
	case 0:
		return nil, nil
	case 1:
		q = queries[0]
	default:
		q = bleve.NewConjunctionQuery(queries...)
	}
	req := bleve.NewSearchRequest(q)
	req.Size = limit
	results, err := idx.Search(req)
	if err != nil {
		return nil, err
	}
	var ids []string
	for _, hit := range results.Hits {
		ids = append(ids, hit.ID)
	}
	return ids, nil
}

// #endregion 🎊Query Cache

// #region 📌Tree Cache
// Gzip-compressed JSON cache of the full TreeNode tree under .repo/cache. Uses same git fingerprint as Query Cache for invalidation. Saves ~95% of tree build time on cache hit.

// 🌳getTreeCachePath holds the data fields for a getTreeCachePath record.
func getTreeCachePath() string {
	return filepath.Join(getCacheDir(), "tree.json.gz")
}

func getTreeCacheMetaPath() string {
	return filepath.Join(getCacheDir(), "tree-meta.json")
}

// 💿saveTreeCache holds the data fields for a saveTreeCache record.
func saveTreeCache(tree *TreeNode, meta *cacheMeta) error {
	dir := getCacheDir()
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := json.Marshal(tree)
	if err != nil {
		return err
	}
	var buf bytes.Buffer
	gz, err := gzip.NewWriterLevel(&buf, gzip.BestSpeed)
	if err != nil {
		return err
	}
	if _, err := gz.Write(data); err != nil {
		gz.Close()
		return err
	}
	if err := gz.Close(); err != nil {
		return err
	}
	if err := os.WriteFile(getTreeCachePath(), buf.Bytes(), 0644); err != nil {
		return err
	}
	metaData, err := json.MarshalIndent(meta, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(getTreeCacheMetaPath(), metaData, 0644)
}

func loadTreeCache() (*TreeNode, *cacheMeta, error) {
	metaData, err := os.ReadFile(getTreeCacheMetaPath())
	if err != nil {
		return nil, nil, err
	}
	var meta cacheMeta
	if err := json.Unmarshal(metaData, &meta); err != nil {
		return nil, nil, err
	}
	if meta.SchemaVersion != cacheSchemaVersion {
		return nil, nil, fmt.Errorf("schema version mismatch")
	}
	compressed, err := os.ReadFile(getTreeCachePath())
	if err != nil {
		return nil, nil, err
	}
	gz, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		return nil, nil, err
	}
	defer gz.Close()
	data, err := io.ReadAll(gz)
	if err != nil {
		return nil, nil, err
	}
	var tree TreeNode
	if err := json.Unmarshal(data, &tree); err != nil {
		return nil, nil, err
	}
	return &tree, &meta, nil
}

// 🏢BuildMonorepoTreeCached holds the data fields for a BuildMonorepoTreeCached record.
func BuildMonorepoTreeCached(ctx context.Context, opts ...TreeBuildOptions) *TreeNode {
	var buildOpts TreeBuildOptions
	if len(opts) > 0 {
		buildOpts = opts[0]
	}
	repoRoot := GetRootDir()

	// Acquire a directory-based lock so only one CLI process builds the tree at a time.
	// Other concurrent processes will block here and then use the cache.
	lockPath := filepath.Join(getCacheDir(), "tree.lock")
	os.MkdirAll(filepath.Dir(lockPath), 0755)
	for {
		err := os.Mkdir(lockPath, 0755)
		if err == nil {
			break
		}
		// If the lock directory exists, another process holds the lock.
		// Check if it's stale (older than 60 seconds) and remove it.
		if info, statErr := os.Stat(lockPath); statErr == nil {
			if time.Since(info.ModTime()) > 60*time.Second {
				os.RemoveAll(lockPath)
				continue
			}
		}
		time.Sleep(100 * time.Millisecond)
	}
	defer os.RemoveAll(lockPath)

	fp, newMeta := computeCompositeFingerprint(repoRoot)
	newMeta.IncludeSections = buildOpts.IncludeSections
	cached, cachedMeta, err := loadTreeCache()
	if err == nil && cachedMeta.Fingerprint == fp && cachedMeta.IncludeSections == buildOpts.IncludeSections {
		return cached
	}
	tree := BuildMonorepoTree(ctx, buildOpts)
	saveTreeCache(tree, newMeta)
	return tree
}

// #endregion 📌Tree Cache

// #endregion 🏩Tree Logic

// #region 🌩️CLI Renderers
// Stream renderers that format engine events for NDJSON, human-readable, and markdown output.

// 🔌StreamRenderer defines the interface contract for stream renderer operations.
type StreamRenderer interface {
	Render(ctx context.Context, out, errOut io.Writer, stream <-chan Event) (int, error)
}

// 🎨NDJSONRenderer holds the data fields for a n d j s o n renderer record.
type NDJSONRenderer struct{}

// 🔷Render MUST produce a complete  output.
// 💾Render renders the  into its output representation.
func (r NDJSONRenderer) Render(ctx context.Context, out, errOut io.Writer, stream <-chan Event) (int, error) {
	encoder := json.NewEncoder(out)
	encoder.SetEscapeHTML(false)

	errEncoder := json.NewEncoder(errOut)
	errEncoder.SetEscapeHTML(false)

	exitCode := 0
	for event := range stream {
		if event.Kind == KindDone && event.Done != nil {
			exitCode = event.Done.ExitCode
		}
		if event.Kind == KindResult && event.Data != nil {
			out.Write(event.Data)
			out.Write([]byte("\n"))
		}
		if event.Kind == KindError && event.Error != nil {
			errEncoder.Encode(event.Error)
		}

		if f, ok := out.(interface{ Flush() error }); ok {
			f.Flush()
		}
	}
	return exitCode, nil
}

// #region 🧊ANSI
// ANSI escape code constants for terminal colorization.

const (
	ColorReset  = "\033[0m"
	ColorRed    = "\033[31m"
	ColorGreen  = "\033[32m"
	ColorYellow = "\033[33m"
	ColorBlue   = "\033[34m"
	ColorDim    = "\033[2m"
	ColorBold   = "\033[1m"
)

// 💿colorize holds the data fields for a colorize record.
func colorize(s string, color string, enabled bool) string {
	if !enabled {
		return s
	}
	return color + s + ColorReset
}

// #endregion 🧊ANSI

// 💿HumanRenderer holds the data fields for a human renderer record.
type HumanRenderer struct {
	Verbose bool
}

// 🔶Render MUST produce a complete  output.
// ⏹️Render renders the  into its output representation.
func (r HumanRenderer) Render(ctx context.Context, out, errOut io.Writer, stream <-chan Event) (int, error) {
	exitCode := 0
	isTTY := false
	if f, ok := out.(*os.File); ok {
		stat, _ := f.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			isTTY = true
		}
	}

	if os.Getenv("NO_COLOR") != "" {
		isTTY = false
	}

	startTime := time.Now()

	for event := range stream {
		if event.Kind == KindDone && event.Done != nil {
			exitCode = event.Done.ExitCode
			duration := time.Since(startTime).Round(time.Millisecond)

			var summary string
			if exitCode != 0 {
				summary = renderTemplate(textTpl, "text/done_failure", map[string]interface{}{
					"IsTTY":    isTTY,
					"Command":  event.Command,
					"Duration": duration,
					"ExitCode": exitCode,
				})
			} else {
				summary = renderTemplate(textTpl, "text/done_success", map[string]interface{}{
					"IsTTY":    isTTY,
					"Command":  event.Command,
					"Duration": duration,
				})
			}

			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprintln(out, summary)
			continue
		}
		if event.Kind == KindError && event.Error != nil {
			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprintln(errOut, renderTemplate(textTpl, "text/error", map[string]interface{}{
				"IsTTY":   isTTY,
				"Message": event.Error.Message,
			}))
			if r.Verbose && event.Error.Detail != "" {
				fmt.Fprintln(errOut, renderTemplate(textTpl, "text/error_detail", map[string]interface{}{
					"Detail": event.Error.Detail,
				}))
			}
			continue
		}
		if event.Kind == KindLog && event.Message != "" {
			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprintln(errOut, renderTemplate(textTpl, "text/log", map[string]interface{}{
				"IsTTY":   isTTY,
				"Message": event.Message,
			}))
			continue
		}
		if event.Kind == KindResult && len(event.Data) > 0 {
			if isTTY {
				fmt.Fprint(out, "\r\033[K")
			}
			fmt.Fprint(out, formatResult(event.Command, event.Data, isTTY))
		}
		if event.Kind == KindProgress && event.Progress != nil {
			if isTTY {
				fmt.Fprint(out, renderTemplate(textTpl, "text/progress_tty", map[string]interface{}{
					"Percent": event.Progress.Percent,
					"Current": event.Progress.Current,
					"Total":   event.Progress.Total,
					"Step":    event.Progress.Step,
				}))
			} else {
				if event.Progress.Percent%10 == 0 && event.Progress.Percent > 0 {
					fmt.Fprintln(out, renderTemplate(textTpl, "text/progress", map[string]interface{}{
						"Percent": event.Progress.Percent,
						"Step":    event.Progress.Step,
					}))
				}
			}
		}
	}
	return exitCode, nil
}

func formatResult(command string, data json.RawMessage, isTTY bool) string {
	var raw map[string]interface{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return renderTemplate(textTpl, "text/result_fallback", map[string]interface{}{
			"IsTTY": isTTY,
			"Data":  string(data),
		}) + "\n"
	}
	payload := raw
	if inner, ok := raw["data"].(map[string]interface{}); ok {
		payload = inner
	}

	var sb strings.Builder

	if output, ok := payload["markdown"].(string); ok {
		return output
	}

	if analyze, ok := payload["analyze"].(map[string]interface{}); ok {
		if metrics, ok := analyze["metrics"].(map[string]interface{}); ok {
			total := metrics["total"]
			autofixable := metrics["autofixable"]
			sb.WriteString(renderTemplate(textTpl, "text/analyze_summary", map[string]interface{}{
				"IsTTY":       isTTY,
				"Total":       total,
				"Autofixable": autofixable,
			}) + "\n")
		}
		if breachs, ok := analyze["breachs"].([]interface{}); ok {
			for _, v := range breachs {
				if vio, ok := v.(map[string]interface{}); ok {
					kind := ""
					if k, ok := vio["kind"].(map[string]interface{}); ok {
						kind = fmt.Sprintf("%v", k["id"])
					} else if kStr, ok := vio["kind"].(string); ok {
						kind = kStr
					}
					scope := fmt.Sprintf("%v", vio["scope"])
					line := fmt.Sprintf("%v", vio["line"])
					summary := fmt.Sprintf("%v", vio["summary"])
					sb.WriteString(renderTemplate(textTpl, "text/breach", map[string]interface{}{
						"IsTTY":   isTTY,
						"Kind":    kind,
						"Scope":   scope,
						"Line":    line,
						"Summary": summary,
					}) + "\n")
				}
			}
		}
		if sb.Len() > 0 {
			return sb.String()
		}
	}

	if fix, ok := payload["fix"].(map[string]interface{}); ok {
		fixed := fix["fixed"]
		remaining := fix["remaining"]
		return renderTemplate(textTpl, "text/fix", map[string]interface{}{
			"IsTTY":     isTTY,
			"Fixed":     fixed,
			"Remaining": remaining,
		}) + "\n"
	}

	if repo, ok := payload["repo"].(map[string]interface{}); ok {
		goals, goalsOk := repo["goals"].([]interface{})
		tickets, _ := repo["tickets"].([]interface{})
		if goalsOk {
			return renderGoalTree(goals, tickets, isTTY, false)
		}
	}

	termWidth := 0
	if isTTY {
		termWidth = getTerminalWidth()
	}

	renderList := func(kind string, items []interface{}) (string, bool) {
		if len(items) == 0 {
			return "", true
		}
		var b strings.Builder
		for _, it := range items {
			if m, ok := it.(map[string]interface{}); ok {
				line := renderEntityHuman(kind, m, isTTY)
				if termWidth > 0 {
					line = truncateANSI(line, termWidth)
				}
				b.WriteString(line)
				b.WriteString("\n")
			}
		}
		return b.String(), true
	}

	if repo, ok := payload["repo"].(map[string]interface{}); ok {
		listKindPairs := []struct {
			key  string
			kind string
		}{
			{"tickets", "ticket"},
			{"goals", "goal"},
			{"bundles", "bundle"},
			{"technologies", "technology"},
			{"folders", "folder"},
			{"files", "file"},
			{"contributors", "contributor"},
			{"policies", "policy"},
			{"statutes", "statute"},
		}
		for _, lk := range listKindPairs {
			if items, ok := repo[lk.key].([]interface{}); ok {
				out, _ := renderList(lk.kind, items)
				return out
			}
		}
	}

	topListPairs := []struct {
		key  string
		kind string
	}{
		{"todos", "todo"},
		{"sections", "section"},
		{"definitions", "definition"},
		{"drafts", "draft"},
	}
	for _, lk := range topListPairs {
		if items, ok := payload[lk.key].([]interface{}); ok {
			out, _ := renderList(lk.kind, items)
			return out
		}
	}

	singleKeys := []string{
		"ticket", "goal", "bundle", "folder", "policy",
		"contributor", "draft", "todo", "technology", "definition",
	}
	for _, key := range singleKeys {
		if entity, ok := payload[key].(map[string]interface{}); ok {
			if topID, ok := payload["id"].(string); ok {
				if _, has := entity["id"]; !has {
					entity["id"] = topID
				}
			}
			return renderEntityHuman(key, entity, isTTY) + "\n"
		}
	}

	if file, ok := payload["file"].(map[string]interface{}); ok {
		line := renderEntityHuman("file", file, isTTY)
		if termWidth > 0 {
			line = truncateANSI(line, termWidth)
		}
		sb.WriteString(line + "\n")
		if sections, ok := file["sections"].([]interface{}); ok {
			var printSections func(items []interface{}, indent string)
			printSections = func(items []interface{}, indent string) {
				for _, item := range items {
					if sec, ok := item.(map[string]interface{}); ok {
						secStr := renderEntityHuman("section", sec, isTTY)
						if termWidth > 0 {
							secStr = truncateANSI(secStr, termWidth)
						}
						sb.WriteString(indent + secStr + "\n")
						if children, ok := sec["children"].([]interface{}); ok && len(children) > 0 {
							printSections(children, indent+"  ")
						}
					}
				}
			}
			printSections(sections, "  ")
		}
		if definitions, ok := file["definitions"].([]interface{}); ok {
			for _, d := range definitions {
				if def, ok := d.(map[string]interface{}); ok {
					defStr := renderEntityHuman("definition", def, isTTY)
					if termWidth > 0 {
						defStr = truncateANSI(defStr, termWidth)
					}
					sb.WriteString("  " + defStr + "\n")
				}
			}
		}
		if sb.Len() > 0 {
			return sb.String()
		}
	}

	if sec, ok := payload["section"].(map[string]interface{}); ok {
		b, _ := json.Marshal(sec)
		var s Section
		json.Unmarshal(b, &s)
		return renderSectionTree(&s, isTTY, false)
	}

	for key, val := range payload {
		if entityMap, ok := val.(map[string]interface{}); ok {
			kind := inferEntityKind(key)
			if kind != "" {
				return renderEntityHuman(kind, entityMap, isTTY) + "\n"
			}
		}
	}

	if id, ok := payload["id"].(string); ok {
		if path, ok := payload["path"].(string); ok {
			return renderTemplate(textTpl, "text/id_path", map[string]interface{}{
				"IsTTY": isTTY,
				"ID":    id,
				"Path":  path,
			}) + "\n"
		}
		return renderTemplate(textTpl, "text/id_only", map[string]interface{}{
			"IsTTY": isTTY,
			"ID":    id,
		}) + "\n"
	}

	return renderEntityHuman("root", payload, isTTY) + "\n"
}

// 📰MarkdownRenderer holds the data fields for a markdown renderer record.
type MarkdownRenderer struct{}

// 🔹Render MUST produce a complete  output.
// 🔢Render renders the  into its output representation.
func (r MarkdownRenderer) Render(ctx context.Context, out, errOut io.Writer, stream <-chan Event) (int, error) {
	exitCode := 0
	for event := range stream {
		if event.Kind == KindDone && event.Done != nil {
			exitCode = event.Done.ExitCode
			continue
		}
		if event.Kind == KindResult && len(event.Data) > 0 {
			fmt.Fprint(out, formatMarkdownResult(event.Command, event.Data))
		}
		if event.Kind == KindError && event.Error != nil {
			fmt.Fprintln(errOut, renderTemplate(mdTpl, "md/error", map[string]interface{}{
				"Message": event.Error.Message,
			}))
			if event.Error.Detail != "" {
				fmt.Fprintln(errOut, renderTemplate(mdTpl, "md/error_detail", map[string]interface{}{
					"Detail": event.Error.Detail,
				}))
			}
		}
	}
	return exitCode, nil
}

// 📋formatMarkdownResult holds the data fields for a formatMarkdownResult record.
func formatMarkdownResult(command string, data json.RawMessage) string {
	var raw map[string]interface{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return renderEntityMarkdownLink("root", map[string]interface{}{"name": string(data)}) + "\n"
	}
	payload := raw
	if inner, ok := raw["data"].(map[string]interface{}); ok {
		payload = inner
	}

	var sb strings.Builder

	if markdown, ok := payload["markdown"].(string); ok {
		return markdown
	}

	if analyze, ok := payload["analyze"].(map[string]interface{}); ok {
		if metrics, ok := analyze["metrics"].(map[string]interface{}); ok {
			total := metrics["total"]
			autofixable := metrics["autofixable"]
			sb.WriteString(renderTemplate(mdTpl, "md/analyze_total", map[string]interface{}{
				"Total": total,
			}) + "\n")
			if autofixable != nil {
				sb.WriteString(renderTemplate(mdTpl, "md/analyze_autofixable", map[string]interface{}{
					"Autofixable": autofixable,
				}) + "\n")
			}
		}
		if breachs, ok := analyze["breachs"].([]interface{}); ok {
			for _, v := range breachs {
				if vio, ok := v.(map[string]interface{}); ok {
					kind := ""
					if k, ok := vio["kind"].(map[string]interface{}); ok {
						kind = fmt.Sprintf("%v", k["id"])
					} else if kStr, ok := vio["kind"].(string); ok {
						kind = kStr
					}
					scope := fmt.Sprintf("%v", vio["scope"])
					line := fmt.Sprintf("%v", vio["line"])
					summary := fmt.Sprintf("%v", vio["summary"])
					sb.WriteString(renderTemplate(mdTpl, "md/breach", map[string]interface{}{
						"Kind":    kind,
						"Scope":   scope,
						"Line":    line,
						"Summary": summary,
					}) + "\n")
				}
			}
		}
		return sb.String()
	}

	if repo, ok := payload["repo"].(map[string]interface{}); ok {
		goals, goalsOk := repo["goals"].([]interface{})
		tickets, _ := repo["tickets"].([]interface{})
		if goalsOk {
			return renderGoalTree(goals, tickets, false, true)
		}
	}

	listKeys := []struct {
		wrap string
		key  string
		kind string
	}{
		{"repo", "tickets", "ticket"},
		{"repo", "goals", "goal"},
		{"repo", "bundles", "bundle"},
		{"repo", "technologies", "technology"},
		{"repo", "folders", "folder"},
		{"repo", "files", "file"},
		{"repo", "contributors", "contributor"},
		{"repo", "policies", "policy"},
		{"repo", "statutes", "statute"},
		{"", "todos", "todo"},
		{"", "sections", "section"},
		{"", "definitions", "definition"},
		{"", "drafts", "draft"},
	}
	for _, lk := range listKeys {
		var container map[string]interface{}
		if lk.wrap != "" {
			if w, ok := payload[lk.wrap].(map[string]interface{}); ok {
				container = w
			}
		} else {
			container = payload
		}
		if container == nil {
			continue
		}
		if items, ok := container[lk.key].([]interface{}); ok {
			for _, item := range items {
				if m, ok := item.(map[string]interface{}); ok {
					sb.WriteString(renderEntityMarkdown(lk.kind, m) + "\n")
				}
			}
			return sb.String()
		}
	}

	isList := strings.HasSuffix(command, " list") || strings.HasSuffix(command, " tree")

	singleKeys := []string{
		"ticket", "goal", "bundle", "folder", "file", "definition",
		"contributor", "policy", "technology", "draft", "todo", "checkpoint",
	}
	for _, key := range singleKeys {
		if entity, ok := payload[key].(map[string]interface{}); ok {
			if topID, ok := payload["id"].(string); ok {
				if _, has := entity["id"]; !has {
					entity["id"] = topID
				}
			}
			if key == "file" && !isList {
				return formatMarkdownFile(entity)
			}
			if key == "section" {
				b, _ := json.Marshal(entity)
				var s Section
				json.Unmarshal(b, &s)
				return renderSectionTree(&s, false, true)
			}
			if isList {
				return renderEntityMarkdown(key, entity) + "\n"
			}
			return renderEntityMarkdownLink(key, entity) + "\n"
		}
	}

	if sec, ok := payload["section"].(map[string]interface{}); ok {
		b, _ := json.Marshal(sec)
		var s Section
		json.Unmarshal(b, &s)
		return renderSectionTree(&s, false, true)
	}

	for key, val := range payload {
		if entityMap, ok := val.(map[string]interface{}); ok {
			kind := inferEntityKind(key)
			if kind != "" {
				return renderEntityMarkdownLink(kind, entityMap) + "\n"
			}
		}
	}

	return renderEntityMarkdownLink("root", payload) + "\n"
}

// 📄formatMarkdownFile holds the data fields for a formatMarkdownFile record.
func formatMarkdownFile(file map[string]interface{}) string {
	var sb strings.Builder
	sb.WriteString(renderEntityMarkdownLink("file", file) + "\n")

	filePath, _ := file["path"].(string)
	if id, ok := file["id"].(string); ok && id != "" {
		filePath = id
	}

	if sections, ok := file["sections"].([]interface{}); ok {
		var printSections func(items []interface{}, indent string)
		printSections = func(items []interface{}, indent string) {
			for _, item := range items {
				if sec, ok := item.(map[string]interface{}); ok {
					if _, hasPath := sec["filePath"]; !hasPath {
						sec["filePath"] = filePath
					}
					line := renderEntityMarkdown("section", sec)
					sb.WriteString(fmt.Sprintf("%s%s\n", indent, line))
					if children, ok := sec["children"].([]interface{}); ok && len(children) > 0 {
						printSections(children, indent+"  ")
					}
				}
			}
		}
		printSections(sections, "  ")
	}

	if definitions, ok := file["definitions"].([]interface{}); ok {
		for _, d := range definitions {
			if def, ok := d.(map[string]interface{}); ok {
				if _, hasPath := def["filePath"]; !hasPath {
					def["filePath"] = filePath
				}
				sb.WriteString("  " + renderEntityMarkdown("definition", def) + "\n")
			}
		}
	}
	return sb.String()
}

// 🔸renderStream holds the data fields for a renderStream record.
func renderStream(cmd *cobra.Command, config *Config, stream <-chan Event) error {
	var renderer StreamRenderer
	if config.IsJSON() {
		renderer = NDJSONRenderer{}
	} else if config.IsMarkdown() {
		renderer = MarkdownRenderer{}
	} else {
		renderer = HumanRenderer{Verbose: config.Verbose}
	}

	exitCode, err := renderer.Render(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), stream)
	if err != nil {
		return err
	}
	if exitCode != 0 {
		return ExitError{Code: exitCode}
	}
	return nil
}

// 📡renderEventsToMarkdown holds the data fields for a renderEventsToMarkdown record.
func renderEventsToMarkdown(events []Event) string {
	var sb strings.Builder
	for _, event := range events {
		if event.Kind == KindResult && len(event.Data) > 0 {
			sb.WriteString(formatMarkdownResult(event.Command, event.Data))
		}
		if event.Kind == KindError && event.Error != nil {
			sb.WriteString(renderTemplate(mdTpl, "md/error", map[string]interface{}{
				"Message": event.Error.Message,
			}) + "\n")
		}
	}
	return sb.String()
}

// ❌toolErrorResult holds the data fields for a toolErrorResult record.
func toolErrorResult(err error) ToolResult {
	output := NewOutput()
	output.Error(fmt.Sprintf("Error: %v", err))
	return ToolResult{Output: *output, Error: err.Error()}
}

// 🔺toolErrorMsg holds the data fields for a toolErrorMsg record.
func toolErrorMsg(msg string) ToolResult {
	output := NewOutput()
	output.Error(fmt.Sprintf("Error: %s", msg))
	return ToolResult{Output: *output, Error: msg}
}

// 🔻toolResultFromEvents holds the data fields for a toolResultFromEvents record.
func toolResultFromEvents(events []Event, data interface{}) ToolResult {
	text := renderEventsToMarkdown(events)
	output := NewOutput()
	if text != "" {
		output.Plain(text)
	}
	for _, event := range events {
		if event.Kind == KindError && event.Error != nil {
			return ToolResult{Output: *output, Data: data, Error: event.Error.Message}
		}
		if event.Kind == KindDone && event.Done != nil && event.Done.ExitCode != 0 {
			output.ExitCode = event.Done.ExitCode
		}
	}
	return ToolResult{Output: *output, Data: data}
}

// 🌳toolResultFromTreeList holds the data fields for a toolResultFromTreeList record.
func toolResultFromTreeList(nodeKind TreeNodeKind) ToolResult {
	ctx := context.Background()
	tree := BuildMonorepoTreeCached(ctx, TreeBuildOptions{})
	filter := TreeFilter{OnlyKinds: map[TreeNodeKind]bool{nodeKind: true}}
	tree = FilterMonorepoTree(tree, &filter)
	var nodes []*TreeNode
	flattenTreeNodes(tree, &nodes)
	var sb strings.Builder
	for _, n := range nodes {
		entityKind := treeNodeKindToEntityKind(n.Kind)
		if entityKind == "" {
			entityKind = string(n.Kind)
		}
		if n.Data != nil {
			sb.WriteString(renderEntityMarkdown(entityKind, n.Data) + "\n")
		}
	}
	output := NewOutput()
	output.Plain(sb.String())
	return ToolResult{Output: *output}
}

// ⬛toolResultFromTreeRender holds the data fields for a toolResultFromTreeRender record.
func toolResultFromTreeRender(nodeKind TreeNodeKind) ToolResult {
	ctx := context.Background()
	tree := BuildMonorepoTreeCached(ctx, TreeBuildOptions{})
	filter := TreeFilter{OnlyKinds: map[TreeNodeKind]bool{nodeKind: true}}
	tree = FilterMonorepoTree(tree, &filter)
	text := RenderMonorepoTreeMarkdown(tree)
	output := NewOutput()
	output.Plain(text)
	return ToolResult{Output: *output}
}

// 🕸️runGraphQL holds the data fields for a runGraphQL record.
func runGraphQL(cmd *cobra.Command, factory EngineFactory, config *Config, query string, variables map[string]interface{}) error {
	argsPayload := GraphQLArgs{Query: query, Variables: variables}
	payloadBytes, err := json.Marshal(argsPayload)
	if err != nil {
		return err
	}
	engine, err := factory(*config)
	if err != nil {
		return err
	}
	ctx := context.Background()
	if config.Timeout > 0 {
		ctxWithTimeout, cancel := context.WithTimeout(ctx, config.Timeout)
		defer cancel()
		ctx = ctxWithTimeout
	}
	request := Request{Command: CmdGraphQL, Args: payloadBytes, RepoRoot: config.Repo, Verbose: config.Verbose}
	stream := engine.Run(ctx, request)
	return renderStream(cmd, config, stream)
}

// #region 🔢LOC Command
// 📈locDefaultBranch: dev walk branch (⛳ wip).
// 📈locDefaultLanguageList: internal scan + git line classification.
const locDefaultBranch = "⛳wip"

// 🧮locAggCode/locAggMarkup/locAggData/locAggTotal: synthetic aggregate row labels for `loc` tables.
const (
	locAggCode   = "Code"
	locAggMarkup = "Markup"
	locAggData   = "Data"
	locAggTotal  = "Total"
)

// 💿LocLangStats holds the data fields for a line-of-code per-language metrics record.
// 📊LocLangStats: per-row LOC, % of tree Total, % of branch WIP churn, and git delta sums.
type LocLangStats struct {
	Loc                 int      `json:"loc"`
	Percent             float64  `json:"percent"`
	SincePrevLocPercent *float64 `json:"since_prev_loc_percent,omitempty"`
	WipPercent          float64  `json:"wip_percent"`
	Edited              int      `json:"edited"`
	Added               int      `json:"added"`
	Removed             int      `json:"removed"`
}

// 💿LocReport: JSON payload for `loc` output and rendering.
type LocReport struct {
	Snapshot       map[string]LocLangStats            `json:"snapshot"`
	ByContributors map[string]map[string]LocLangStats `json:"byContributors,omitempty"`
	History        []LocHistoryEntry                  `json:"history,omitempty"`
	Branch         string                             `json:"branch,omitempty"`
}

// 💿LocHistoryEntry: one commit step on the time series; Languages xor ByContributors.
type LocHistoryEntry struct {
	SHA            string                             `json:"sha"`
	Date           string                             `json:"date"`
	Author         string                             `json:"author,omitempty"`
	Languages      map[string]LocLangStats            `json:"languages,omitempty"`
	ByContributors map[string]map[string]LocLangStats `json:"byContributors,omitempty"`
}

// 💿locRawCommit holds a single parsed commit and its per-language line deltas.
type locRawCommit struct {
	SHA        string
	WhenUnix   int64
	Author     string
	AuthorMail string
	Delta      map[string]locPair
}

// 💿locPair: added/removed in one file change.
type locPair struct{ Added, Removed int }

// 🔧locContributorAlias maps git author to canonical id via first-author resolution.
// 👤 locContributorAlias resolves first-author to contributor alias.
func locContributorAlias(name, email string) string {
	author := strings.TrimSpace(name)
	em := strings.TrimSpace(email)
	if em != "" {
		author = fmt.Sprintf("%s <%s>", author, em)
	}
	if author == "" {
		return "unknown"
	}
	return FindAndUpdateContributor(author)
}

// 🪷 locPathSkipped returns true for paths that must not be counted (.repo, gitignore).
// 🗂️ locPathSkipped filters repo-internal and gitignored relative paths.
func locPathSkipped(relPath string) bool {
	rel := normalizeRepoPath(relPath)
	rel = filepath.ToSlash(rel)
	if rel == "" {
		return true
	}
	if rel == ".repo" || strings.HasPrefix(rel, ".repo/") {
		return true
	}
	return isIgnoredByGitignore(rel)
}

// 🫥 locPathHasHiddenSegment returns true when any path segment starts with "." (excluding "." / "..").
func locPathHasHiddenSegment(relPath string) bool {
	rel := filepath.ToSlash(normalizeRepoPath(relPath))
	for _, seg := range strings.Split(rel, "/") {
		if seg == "" || seg == "." || seg == ".." {
			continue
		}
		if strings.HasPrefix(seg, ".") {
			return true
		}
	}
	return false
}

// 🗂️ locPathSkippedForLoc combines gitignore/.repo skips with hidden-directory-segment skips for `loc`.
func locPathSkippedForLoc(relPath string) bool {
	if locPathSkipped(relPath) {
		return true
	}
	return locPathHasHiddenSegment(relPath)
}

// 🏷️ locClassifyLocBucket maps a path extension to a `loc` bucket key (code language, Markup, Data) or "".
func locClassifyLocBucket(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".ts", ".tsx", ".cts", ".mts", ".mtsx":
		return "TypeScript"
	case ".go":
		return "Go"
	case ".cs":
		return "C#"
	case ".py":
		return "Python"
	case ".rs":
		return "Rust"
	case ".html", ".htm", ".xhtml", ".md", ".markdown", ".mdown", ".mkd", ".mdx", ".mdc", ".svx", ".svxtheme":
		return locAggMarkup
	case ".json", ".jsonc", ".yaml", ".yml", ".toml", ".csv", ".xml", ".ini", ".cfg", ".conf", ".properties", ".editorconfig", ".gitattributes", ".gitmodules":
		return locAggData
	default:
		return ""
	}
}

// 🏷️ locClassifyForNumstat returns a bucket key when the path is allowed by the active `loc` weight map.
func locClassifyForNumstat(path string, w map[string]bool) string {
	b := locClassifyLocBucket(path)
	if b == "" || !w[b] {
		return ""
	}
	return b
}

// 🏷️ locClassifyLanguage classifies a repo-relative path when the bucket is enabled in langs, else "".
func locClassifyLanguage(path string, langs map[string]bool) string {
	return locClassifyForNumstat(path, langs)
}

// 🧾 locMakeNumstatLangSet extends the `--languages` code set with Markup and Data buckets for git deltas.
func locMakeNumstatLangSet(languages []string) map[string]bool {
	m := locMakeLangSet(languages)
	m[locAggMarkup] = true
	m[locAggData] = true
	return m
}

func locMakeLangSet(languages []string) map[string]bool {
	m := make(map[string]bool, len(languages))
	for _, l := range languages {
		m[strings.TrimSpace(l)] = true
	}
	return m
}

func locZeroSnapshot(langs map[string]bool) map[string]LocLangStats {
	s := make(map[string]LocLangStats)
	for l := range langs {
		s[l] = LocLangStats{}
	}
	return s
}

// 🔧locCumulativePair holds running added/removed per key.
// 📊 locCumulativePair: running sums for a dimension (language or contributor+language).
type locCumulativePair struct {
	Added, Removed int
}

func locCumulativeFromRaw(commits []locRawCommit, languages []string, byContrib bool, contribFilter string) (map[string]locCumulativePair, map[string]map[string]locCumulativePair, error) {
	langW := locMakeNumstatLangSet(languages)
	cum := make(map[string]locCumulativePair)
	for l := range langW {
		cum[l] = locCumulativePair{}
	}
	var byCont map[string]map[string]locCumulativePair
	if byContrib {
		byCont = make(map[string]map[string]locCumulativePair)
	}
	filt := strings.TrimSpace(contribFilter)
	for _, c := range commits {
		alias := locContributorAlias(c.Author, c.AuthorMail)
		if filt != "" && !strings.EqualFold(filt, alias) {
			continue
		}
		if byContrib {
			if byCont[alias] == nil {
				byCont[alias] = make(map[string]locCumulativePair)
				for l := range langW {
					byCont[alias][l] = locCumulativePair{}
				}
			}
		}
		for l, p := range c.Delta {
			if !langW[l] {
				continue
			}
			agg := cum[l]
			agg.Added += p.Added
			agg.Removed += p.Removed
			cum[l] = agg
			if byContrib {
				agg2 := byCont[alias][l]
				agg2.Added += p.Added
				agg2.Removed += p.Removed
				byCont[alias][l] = agg2
			}
		}
	}
	return cum, byCont, nil
}

// 📏 locPhysicalLineCount counts newline-terminated lines like wc -l (non-empty files have ≥1 line).
func locPhysicalLineCount(data []byte) int {
	if len(data) == 0 {
		return 0
	}
	return bytes.Count(data, []byte("\n")) + 1
}

// 🧮 locCountJSONKeys counts JSON object keys recursively (each key is one logical LOC unit for Data JSON).
func locCountJSONKeys(v any) int {
	switch t := v.(type) {
	case map[string]any:
		n := len(t)
		for _, vv := range t {
			n += locCountJSONKeys(vv)
		}
		return n
	case []any:
		var n int
		for _, vv := range t {
			n += locCountJSONKeys(vv)
		}
		return n
	default:
		return 0
	}
}

// 🧮 locJSONKeyCount parses JSON and counts object keys; returns 0 when not valid JSON.
func locJSONKeyCount(data []byte) int {
	d := bytes.TrimSpace(data)
	if len(d) == 0 {
		return 0
	}
	var v any
	if err := json.Unmarshal(d, &v); err != nil {
		return 0
	}
	return locCountJSONKeys(v)
}

// 🧮 locCountBucketLoc returns LOC for a tracked file body using Data JSON key rules vs physical lines.
func locCountBucketLoc(path string, data []byte) int {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".json", ".jsonc":
		k := locJSONKeyCount(data)
		if k > 0 {
			return k
		}
		if len(bytes.TrimSpace(data)) == 0 {
			return 0
		}
		return locPhysicalLineCount(data)
	default:
		return locPhysicalLineCount(data)
	}
}

// 🧾 locGitListTrackedPaths lists repo-relative paths at HEAD (tracked) or at ref (git tree).
func locGitListTrackedPaths(repo, ref string) ([]string, error) {
	var args []string
	if ref == "" {
		args = []string{"-C", repo, "ls-files", "-z"}
	} else {
		args = []string{"-C", repo, "ls-tree", "-r", "--name-only", "-z", ref}
	}
	stdout, stderr, code := ExecCommand("git", args, repo)
	if code != 0 {
		return nil, fmt.Errorf("git paths: %s", strings.TrimSpace(stderr))
	}
	var out []string
	for _, p := range strings.Split(stdout, "\x00") {
		if p == "" {
			continue
		}
		out = append(out, filepath.ToSlash(p))
	}
	return out, nil
}

// 🧾 locGitReadTrackedBytes reads tracked file bytes at HEAD or at ref via git show.
func locGitReadTrackedBytes(repo, ref, relPath string) ([]byte, error) {
	rel := filepath.ToSlash(relPath)
	if ref == "" {
		fp := filepath.Join(repo, filepath.FromSlash(rel))
		return os.ReadFile(fp)
	}
	spec := ref + ":" + rel
	stdout, stderr, code := ExecCommand("git", []string{"-C", repo, "show", spec}, repo)
	if code != 0 {
		return nil, fmt.Errorf("git show: %s", strings.TrimSpace(stderr))
	}
	return []byte(stdout), nil
}

// 🧮 locGitSnapshotLocCounts walks tracked paths and sums LOC per `loc` bucket (no cloc).
func locGitSnapshotLocCounts(repo, ref string, languages []string) (map[string]int, error) {
	w := locMakeNumstatLangSet(languages)
	paths, err := locGitListTrackedPaths(repo, ref)
	if err != nil {
		return nil, err
	}
	counts := make(map[string]int, len(w))
	for k := range w {
		counts[k] = 0
	}
	for _, rel := range paths {
		if locPathSkippedForLoc(rel) {
			continue
		}
		bucket := locClassifyForNumstat(rel, w)
		if bucket == "" {
			continue
		}
		data, err := locGitReadTrackedBytes(repo, ref, rel)
		if err != nil {
			continue
		}
		if len(data) > 0 && bytes.IndexByte(data, 0) >= 0 {
			continue
		}
		counts[bucket] += locCountBucketLoc(rel, data)
	}
	return counts, nil
}

// 🧾 locZeroScanCounts returns zero scan counts for every numstat bucket (contributor-only rows).
func locZeroScanCounts(languages []string) map[string]int {
	w := locMakeNumstatLangSet(languages)
	z := make(map[string]int, len(w))
	for k := range w {
		z[k] = 0
	}
	return z
}

// 🧩 locStatFromPairAndScan builds one row from scan LOC and cumulative git pairs.
func locStatFromPairAndScan(c map[string]locCumulativePair, scanned map[string]int, key string) LocLangStats {
	st := LocLangStats{}
	if scanned != nil {
		st.Loc = scanned[key]
	}
	if p, ok := c[key]; ok {
		st.Added = p.Added
		st.Removed = p.Removed
		st.Edited = p.Added + p.Removed
	}
	return st
}

// 🧮 locApplyPercents sets Percent from Total.loc as denominator (Total row is 100%).
func locApplyPercents(rows map[string]LocLangStats) {
	denom := rows[locAggTotal].Loc
	if denom <= 0 {
		for k, s := range rows {
			s.Percent = 0
			rows[k] = s
		}
		return
	}
	for k, s := range rows {
		if k == locAggTotal {
			s.Percent = 100
		} else {
			s.Percent = math.Round(10000*float64(s.Loc)/float64(denom)) / 100
		}
		rows[k] = s
	}
}

// 📊 locSumEditedPairs sums added+removed across all weighted buckets (branch WIP impulse on the logged ref).
func locSumEditedPairs(m map[string]locCumulativePair, w map[string]bool) int {
	var t int
	for l := range w {
		if p, ok := m[l]; ok {
			t += p.Added + p.Removed
		}
	}
	return t
}

// 🧮 locApplyWipPercents sets WipPercent from edited-line churn: each row vs globalDenom (0 = use Total.Edited).
func locApplyWipPercents(rows map[string]LocLangStats, globalDenom int) {
	denom := globalDenom
	if denom <= 0 {
		denom = rows[locAggTotal].Edited
	}
	if denom <= 0 {
		for k, s := range rows {
			s.WipPercent = 0
			rows[k] = s
		}
		return
	}
	for k, s := range rows {
		s.WipPercent = math.Round(10000*float64(s.Edited)/float64(denom)) / 100
		rows[k] = s
	}
}

// 📊 locComposeLocReportSnapshot merges scan counts, git deltas, and aggregate Code/Total rows with percents.
func locComposeLocReportSnapshot(c map[string]locCumulativePair, scanned map[string]int, languages []string, wipGlobalDenom int) map[string]LocLangStats {
	w := locMakeNumstatLangSet(languages)
	out := make(map[string]LocLangStats)
	codeOrder := []string{"TypeScript", "Go", "C#", "Python", "Rust"}
	var codeLoc, codeAdded, codeRemoved, codeEdited int
	for _, ln := range codeOrder {
		if !w[ln] {
			continue
		}
		st := locStatFromPairAndScan(c, scanned, ln)
		out[ln] = st
		codeLoc += st.Loc
		codeAdded += st.Added
		codeRemoved += st.Removed
		codeEdited += st.Edited
	}
	mk := locStatFromPairAndScan(c, scanned, locAggMarkup)
	out[locAggMarkup] = mk
	da := locStatFromPairAndScan(c, scanned, locAggData)
	out[locAggData] = da
	out[locAggCode] = LocLangStats{
		Loc:     codeLoc,
		Edited:  codeEdited,
		Added:   codeAdded,
		Removed: codeRemoved,
	}
	totalLoc := codeLoc + mk.Loc + da.Loc
	totalEdited := codeEdited + mk.Edited + da.Edited
	totalAdded := codeAdded + mk.Added + da.Added
	totalRemoved := codeRemoved + mk.Removed + da.Removed
	out[locAggTotal] = LocLangStats{
		Loc:     totalLoc,
		Edited:  totalEdited,
		Added:   totalAdded,
		Removed: totalRemoved,
	}
	locApplyPercents(out)
	locApplyWipPercents(out, wipGlobalDenom)
	return out
}

// 📶 locSortedRowKeys returns row names sorted by LOC descending with Total last.
func locSortedRowKeys(rows map[string]LocLangStats) []string {
	var ks []string
	for k := range rows {
		if k == locAggTotal {
			continue
		}
		ks = append(ks, k)
	}
	sort.Slice(ks, func(i, j int) bool {
		li := rows[ks[i]].Loc
		lj := rows[ks[j]].Loc
		if li != lj {
			return li > lj
		}
		return ks[i] < ks[j]
	})
	ks = append(ks, locAggTotal)
	return ks
}

// 📶 locSortedRowKeysChurn sorts detail rows by edited (git churn) descending; Total last (delta-only tables).
func locSortedRowKeysChurn(rows map[string]LocLangStats) []string {
	var ks []string
	for k := range rows {
		if k == locAggTotal {
			continue
		}
		ks = append(ks, k)
	}
	sort.Slice(ks, func(i, j int) bool {
		ei := rows[ks[i]].Edited
		ej := rows[ks[j]].Edited
		if ei != ej {
			return ei > ej
		}
		return ks[i] < ks[j]
	})
	ks = append(ks, locAggTotal)
	return ks
}

// 🧾 locUseFullTreeTable is true when the table has non-zero tree LOC (snapshot / merged history); false for contributor-only deltas.
func locUseFullTreeTable(rows map[string]LocLangStats) bool {
	return rows != nil && rows[locAggTotal].Loc > 0
}

// 🔗 locMergeCumulativeCloc materializes LocLangStats rows (scan replaces cloc).
func locMergeCumulativeCloc(c map[string]locCumulativePair, scanned map[string]int, languages []string) map[string]LocLangStats {
	return locComposeLocReportSnapshot(c, scanned, languages, 0)
}

// 💿LocCumulative: exported for tests; mirrors locCumulativePair from numstat.
type LocCumulative struct{ Added, Removed int }

// 🔗 locMergeCumulativeClocEx wraps locMergeCumulativeCloc for exported LocCumulative maps.
// 🔗 locMergeCumulativeClocEx builds LocLangStats from a LocCumulative map.
func locMergeCumulativeClocEx(c map[string]LocCumulative, clocData map[string]int, languages []string) map[string]LocLangStats {
	m := make(map[string]locCumulativePair, len(c))
	for k, v := range c {
		m[k] = locCumulativePair{Added: v.Added, Removed: v.Removed}
	}
	return locMergeCumulativeCloc(m, clocData, languages)
}

// 🔧 locWalkGitLog returns commits oldest-first; ref empty means from HEAD, else limit to that ref.
// 📜 locWalkGitLog runs `git log --numstat` and parses the stream.
func locWalkGitLog(repo string, languages []string, ref string) ([]locRawCommit, error) {
	// COMMIT%09%H%09%aN%09%aE%09%at
	pretty := "COMMIT%x09%H%x09%aN%x09%aE%x09%at"
	args := []string{
		"-C", repo, "log", "--no-merges", "--numstat", "--first-parent", "--reverse",
		"--pretty=format:" + pretty,
	}
	if ref != "" {
		args = append(args, ref)
	}
	stdout, stderr, code := ExecCommand("git", args, repo)
	if code != 0 {
		return nil, fmt.Errorf("git log failed: %s", strings.TrimSpace(stderr))
	}
	return locParseNumstatLog(stdout, locMakeNumstatLangSet(languages))
}

// 🧩 locParseNumstatLog breaks numstat + COMMIT-pretty output into per-commit records.
// 🧩 locParseNumstatLog is exported for unit tests.
func locParseNumstatLog(stdout string, langW map[string]bool) ([]locRawCommit, error) {
	var out []locRawCommit
	lines := strings.Split(stdout, "\n")
	var cur *locRawCommit
	for _, line := range lines {
		line = strings.TrimRight(line, "\r")
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "COMMIT") {
			fields := strings.SplitN(line, "\t", 5)
			if len(fields) < 5 {
				continue
			}
			if cur != nil {
				out = append(out, *cur)
			}
			sha := fields[1]
			authorName := fields[2]
			authorMail := fields[3]
			ts, _ := strconv.ParseInt(fields[4], 10, 64)
			cur = &locRawCommit{SHA: sha, Author: authorName, AuthorMail: authorMail, WhenUnix: ts, Delta: make(map[string]locPair)}
			continue
		}
		if cur == nil {
			continue
		}
		parts := strings.SplitN(line, "\t", 3)
		if len(parts) < 3 {
			continue
		}
		if parts[0] == "-" || parts[1] == "-" {
			continue
		}
		added, err1 := strconv.Atoi(parts[0])
		removed, err2 := strconv.Atoi(parts[1])
		if err1 != nil || err2 != nil {
			continue
		}
		relpath := parts[2]
		if locPathSkippedForLoc(relpath) {
			continue
		}
		lang := locClassifyForNumstat(relpath, langW)
		if lang == "" {
			continue
		}
		d := cur.Delta[lang]
		d.Added += added
		d.Removed += removed
		cur.Delta[lang] = d
	}
	if cur != nil {
		out = append(out, *cur)
	}
	return out, nil
}

// 🔧 locByContributorsToSnapshot builds a contributor -> language -> stats map; loc=0 in leaf rows.
// 🧩 locByContributorsToSnapshot builds contributor breakdown from by-contrib cumulative pairs.
func locByContributorsToSnapshot(m map[string]map[string]locCumulativePair, languages []string, branchWipDenom int) map[string]map[string]LocLangStats {
	if m == nil {
		return nil
	}
	out := make(map[string]map[string]LocLangStats, len(m))
	for alias, lp := range m {
		out[alias] = locComposeLocReportSnapshot(lp, locZeroScanCounts(languages), languages, branchWipDenom)
	}
	return out
}

// 🔧 locBuildHistory: running totals + per-commit tree scan for accurate LOC at each SHA on the logged ref.
// 📅 locBuildHistory assembles the optional --history time series.
func locBuildHistory(repo string, languages []string, byContrib bool, commits []locRawCommit, contribFilter string) ([]LocHistoryEntry, error) {
	langW := locMakeNumstatLangSet(languages)
	running := make(map[string]locCumulativePair)
	runningBranch := make(map[string]locCumulativePair)
	for l := range langW {
		running[l] = locCumulativePair{}
		runningBranch[l] = locCumulativePair{}
	}
	byContRun := make(map[string]map[string]locCumulativePair)
	if byContrib {
		byContRun = make(map[string]map[string]locCumulativePair)
	}
	var hist []LocHistoryEntry
	var lastScan map[string]int
	filt := strings.TrimSpace(contribFilter)
	for _, c := range commits {
		for l, p := range c.Delta {
			if !langW[l] {
				continue
			}
			br := runningBranch[l]
			br.Added += p.Added
			br.Removed += p.Removed
			runningBranch[l] = br
		}
		alias := locContributorAlias(c.Author, c.AuthorMail)
		if filt != "" && !strings.EqualFold(filt, alias) {
			continue
		}
		if byContrib {
			if byContRun[alias] == nil {
				byContRun[alias] = make(map[string]locCumulativePair)
				for l := range langW {
					byContRun[alias][l] = locCumulativePair{}
				}
			}
		}
		for l, p := range c.Delta {
			if !langW[l] {
				continue
			}
			agg := running[l]
			agg.Added += p.Added
			agg.Removed += p.Removed
			running[l] = agg
			if byContrib {
				a2 := byContRun[alias][l]
				a2.Added += p.Added
				a2.Removed += p.Removed
				byContRun[alias][l] = a2
			}
		}
		// Always scan each commit tree so history rows show true LOC at that SHA (Δ% vs prior row uses consecutive samples).
		m, err := locGitSnapshotLocCounts(repo, c.SHA, languages)
		if err != nil {
			return nil, err
		}
		lastScan = m
		wipBranchDenom := locSumEditedPairs(runningBranch, langW)
		iso := time.Unix(c.WhenUnix, 0).UTC().Format(time.RFC3339)
		entry := LocHistoryEntry{SHA: c.SHA, Date: iso, Author: alias}
		if byContrib {
			row := make(map[string]map[string]LocLangStats, 1)
			row[alias] = locComposeLocReportSnapshot(byContRun[alias], lastScan, languages, wipBranchDenom)
			entry.ByContributors = row
		} else {
			entry.Languages = locComposeLocReportSnapshot(running, lastScan, languages, wipBranchDenom)
		}
		hist = append(hist, entry)
	}
	return hist, nil
}

// 📉 locHistoryEntryStatsMap returns language rows for one history step (merged tree or single contributor snapshot).
func locHistoryEntryStatsMap(e *LocHistoryEntry) map[string]LocLangStats {
	if e == nil {
		return nil
	}
	if len(e.Languages) > 0 {
		return e.Languages
	}
	if e.ByContributors != nil {
		for _, row := range e.ByContributors {
			return row
		}
	}
	return nil
}

// 📉 locPctLocSincePrevPtr is percent change in physical LOC from the prior history row (same category); prev 0 and curr>0 yields 100.
func locPctLocSincePrevPtr(prevLoc, currLoc int) *float64 {
	var v float64
	switch {
	case prevLoc == 0 && currLoc == 0:
		v = 0
	case prevLoc == 0:
		v = 100
	default:
		v = 100 * float64(currLoc-prevLoc) / float64(prevLoc)
	}
	v = math.Round(100*v) / 100
	return &v
}

// 📉 locApplyHistoryLocSincePrev stamps SincePrevLocPercent vs the previous history entry (nil on first row / missing keys).
func locApplyHistoryLocSincePrev(h []LocHistoryEntry) {
	var prev map[string]int
	first := true
	for i := range h {
		rows := locHistoryEntryStatsMap(&h[i])
		if rows == nil {
			continue
		}
		for k, st := range rows {
			var pct *float64
			if !first && prev != nil {
				pr := 0
				if p, ok := prev[k]; ok {
					pr = p
				}
				pct = locPctLocSincePrevPtr(pr, st.Loc)
			}
			st.SincePrevLocPercent = pct
			rows[k] = st
		}
		next := make(map[string]int, len(rows))
		for k, st := range rows {
			next[k] = st.Loc
		}
		prev = next
		first = false
	}
}

// 📉 locDisplayHistoryBranch maps common ref spellings to the same emoji id as the default wip branch (⛳wip).
func locDisplayHistoryBranch(ref string) string {
	s := strings.TrimSpace(ref)
	if s == "" {
		return s
	}
	s = strings.TrimPrefix(s, "refs/heads/")
	if strings.EqualFold(s, "wip") {
		return locDefaultBranch
	}
	if s == locDefaultBranch {
		return locDefaultBranch
	}
	return strings.TrimSpace(ref)
}

// 📉 locHistoryCheckpointLabel is the short checkpoint-style id (🔀 + 7 hex), matching checkpoint nodes.
func locHistoryCheckpointLabel(sha string) string {
	short := strings.TrimSpace(sha)
	if len(short) > 7 {
		short = short[:7]
	}
	return emojiText(EmojiCheckpoint) + short
}

// 📉 locContributorEmojiID matches contributor entity ids (🧑‍💻 + flat alias).
func locContributorEmojiID(alias string) string {
	return emojiText(EmojiContributor) + Flat(strings.TrimSpace(alias))
}

// 🫡 runLocCommand runs `loc` and prints using global --format.
func runLocCommand(cmd *cobra.Command, config *Config, languages []string, history, byContrib bool, historyBranch, contribFilter string) error {
	repoRoot := config.Repo
	if strings.TrimSpace(repoRoot) == "" {
		if wd, err := os.Getwd(); err == nil {
			repoRoot = findRepoRoot(wd)
		} else {
			repoRoot = "."
		}
	} else {
		repoRoot = findRepoRoot(repoRoot)
	}
	SetRootDir(repoRoot)
	logRef := ""
	if history {
		if strings.TrimSpace(historyBranch) == "" {
			historyBranch = locDefaultBranch
		}
		logRef = historyBranch
	}
	commits, err := locWalkGitLog(repoRoot, languages, logRef)
	if err != nil {
		return err
	}
	cumAll, byC, _ := locCumulativeFromRaw(commits, languages, byContrib, "")
	if cumAll == nil {
		cumAll = make(map[string]locCumulativePair)
	}
	cumForSnap := cumAll
	cf := strings.TrimSpace(contribFilter)
	if cf != "" {
		c2, _, _ := locCumulativeFromRaw(commits, languages, false, cf)
		if c2 != nil {
			cumForSnap = c2
		}
	}
	cl, err := locGitSnapshotLocCounts(repoRoot, "", languages)
	if err != nil {
		return err
	}
	wipBranchDenom := locSumEditedPairs(cumAll, locMakeNumstatLangSet(languages))
	snap := locComposeLocReportSnapshot(cumForSnap, cl, languages, wipBranchDenom)
	rep := LocReport{Snapshot: snap, Branch: ""}
	if logRef != "" {
		rep.Branch = logRef
	}
	if byContrib {
		byUse := byC
		if cf != "" && byC != nil {
			if one, ok := byC[cf]; ok {
				byUse = map[string]map[string]locCumulativePair{cf: one}
			} else {
				found := false
				for k, v := range byC {
					if strings.EqualFold(k, cf) {
						byUse = map[string]map[string]locCumulativePair{k: v}
						found = true
						break
					}
				}
				if !found {
					byUse = nil
				}
			}
		}
		rep.ByContributors = locByContributorsToSnapshot(byUse, languages, wipBranchDenom)
	}
	if history {
		h, err := locBuildHistory(repoRoot, languages, byContrib, commits, cf)
		if err != nil {
			return err
		}
		locApplyHistoryLocSincePrev(h)
		rep.History = h
	}
	out := cmd.OutOrStdout()
	if config.IsJSON() {
		enc := json.NewEncoder(out)
		enc.SetIndent("", "  ")
		if err := enc.Encode(map[string]LocReport{"loc": rep}); err != nil {
			return err
		}
		return nil
	}
	if config.IsMarkdown() {
		renderLocMarkdown(out, &rep, history, byContrib)
		return nil
	}
	isTTY := false
	if f, ok := out.(*os.File); ok {
		if st, e := f.Stat(); e == nil {
			if (st.Mode() & os.ModeCharDevice) != 0 {
				isTTY = true
			}
		}
	}
	if os.Getenv("NO_COLOR") != "" {
		isTTY = false
	}
	renderLocText(out, &rep, history, byContrib, isTTY)
	return nil
}

// 📤 renderLocMarkdown outputs GitHub-flavoured tables for `loc`.
func renderLocMarkdown(w io.Writer, r *LocReport, withHistory, byContrib bool) {
	fmt.Fprintln(w, "## LOC")
	fmt.Fprintln(w, locMarkdownTable("Snapshot", r.Snapshot, locUseFullTreeTable(r.Snapshot), false))
	if byContrib && len(r.ByContributors) > 0 {
		keys := make([]string, 0, len(r.ByContributors))
		for a := range r.ByContributors {
			keys = append(keys, a)
		}
		sort.Strings(keys)
		fmt.Fprintln(w, "")
		fmt.Fprintln(w, "## By contributor")
		for _, a := range keys {
			s := r.ByContributors[a]
			fmt.Fprintln(w, "")
			fmt.Fprintf(w, "### %s\n\n", locContributorEmojiID(a))
			fmt.Fprintln(w, locMarkdownTable("", s, locUseFullTreeTable(s), false))
		}
	}
	if withHistory && len(r.History) > 0 {
		fmt.Fprintln(w, "")
		fmt.Fprintln(w, "## History (", locDisplayHistoryBranch(r.Branch), ")")
		if byContrib {
			for _, e := range r.History {
				fmt.Fprintln(w, "")
				fmt.Fprintf(w, "#### %s  %s  %s\n", locHistoryCheckpointLabel(e.SHA), e.Date, locContributorEmojiID(e.Author))
				acs := make([]string, 0, len(e.ByContributors))
				for a := range e.ByContributors {
					acs = append(acs, a)
				}
				sort.Strings(acs)
				for _, a := range acs {
					if e.ByContributors == nil {
						break
					}
					s := e.ByContributors[a]
					showSub := len(acs) > 1 || !strings.EqualFold(strings.TrimSpace(a), strings.TrimSpace(e.Author))
					if showSub {
						fmt.Fprintln(w, "")
						fmt.Fprintf(w, "- **%s**\n\n", locContributorEmojiID(a))
					} else {
						fmt.Fprintln(w, "")
					}
					fmt.Fprintln(w, locMarkdownTable("", s, locUseFullTreeTable(s), true))
				}
			}
		} else {
			for _, e := range r.History {
				fmt.Fprintln(w, "")
				fmt.Fprintf(w, "#### %s  %s\n\n", locHistoryCheckpointLabel(e.SHA), e.Date)
				if e.Languages != nil {
					fmt.Fprintln(w, locMarkdownTable("", e.Languages, locUseFullTreeTable(e.Languages), true))
				}
			}
		}
	}
}

// 📤 locMarkdownTable renders a GH-flavoured pipe table. sincePrevCol adds Δ% vs prior history row (fullTree only).
func locMarkdownTable(title string, rows map[string]LocLangStats, fullTree, sincePrevCol bool) string {
	var langs []string
	if fullTree {
		langs = locSortedRowKeys(rows)
	} else {
		langs = locSortedRowKeysChurn(rows)
	}
	var b strings.Builder
	if title != "" {
		b.WriteString("### " + title + "\n\n")
	}
	if fullTree {
		if sincePrevCol {
			b.WriteString("| Category | loc | Δ% | % | wip% | edited | added | removed |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |\n")
			for _, l := range langs {
				st := rows[l]
				d := "—"
				if st.SincePrevLocPercent != nil {
					d = fmt.Sprintf("%+.2f%%", *st.SincePrevLocPercent)
				}
				b.WriteString(fmt.Sprintf("| %s | %d | %s | %.2f%% | %.2f%% | %d | %d | %d |\n", l, st.Loc, d, st.Percent, st.WipPercent, st.Edited, st.Added, st.Removed))
			}
		} else {
			b.WriteString("| Category | loc | % | wip% | edited | added | removed |\n| --- | ---: | ---: | ---: | ---: | ---: | ---: |\n")
			for _, l := range langs {
				st := rows[l]
				b.WriteString(fmt.Sprintf("| %s | %d | %.2f%% | %.2f%% | %d | %d | %d |\n", l, st.Loc, st.Percent, st.WipPercent, st.Edited, st.Added, st.Removed))
			}
		}
	} else {
		b.WriteString("| Category | wip% | edited | added | removed |\n| --- | ---: | ---: | ---: | ---: | ---: |\n")
		for _, l := range langs {
			st := rows[l]
			b.WriteString(fmt.Sprintf("| %s | %.2f%% | %d | %d | %d |\n", l, st.WipPercent, st.Edited, st.Added, st.Removed))
		}
	}
	return b.String()
}

// 🔤 renderLocText prints a colored fixed-width table for TTY; plain for pipes.
func renderLocText(w io.Writer, r *LocReport, withHistory, byContrib, isTTY bool) {
	locTextTable(w, "Snapshot", r.Snapshot, isTTY, locUseFullTreeTable(r.Snapshot), false)
	if byContrib && len(r.ByContributors) > 0 {
		ks := make([]string, 0, len(r.ByContributors))
		for a := range r.ByContributors {
			ks = append(ks, a)
		}
		sort.Strings(ks)
		for _, a := range ks {
			s := r.ByContributors[a]
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, colorize("Contributor: "+locContributorEmojiID(a), ColorBlue, isTTY))
			locTextTable(w, "", s, isTTY, locUseFullTreeTable(s), false)
		}
	}
	if withHistory && len(r.History) > 0 {
		fmt.Fprintln(w, "")
		fmt.Fprintln(w, colorize("History: "+locDisplayHistoryBranch(r.Branch), ColorBold, isTTY))
		if byContrib {
			for _, e := range r.History {
				fmt.Fprintln(w, colorize(locHistoryCheckpointLabel(e.SHA)+"  "+e.Date, ColorDim, isTTY), locContributorEmojiID(e.Author))
				if e.ByContributors == nil {
					continue
				}
				acs := make([]string, 0, len(e.ByContributors))
				for a := range e.ByContributors {
					acs = append(acs, a)
				}
				sort.Strings(acs)
				for _, a := range acs {
					s := e.ByContributors[a]
					showSub := len(acs) > 1 || !strings.EqualFold(strings.TrimSpace(a), strings.TrimSpace(e.Author))
					if showSub {
						fmt.Fprint(w, "  ")
						fmt.Fprintln(w, colorize(locContributorEmojiID(a), ColorBlue, isTTY))
						locTextTable(w, "  ", s, isTTY, locUseFullTreeTable(s), true)
					} else {
						locTextTable(w, "", s, isTTY, locUseFullTreeTable(s), true)
					}
				}
			}
		} else {
			for _, e := range r.History {
				fmt.Fprintln(w, colorize(locHistoryCheckpointLabel(e.SHA)+"  "+e.Date, ColorDim, isTTY))
				locTextTable(w, "", e.Languages, isTTY, locUseFullTreeTable(e.Languages), true)
			}
		}
	}
}

// 🔤 locTextTable prints a simple aligned table; title may be a prefix. sincePrevCol adds Δ% after loc (fullTree only).
func locTextTable(w io.Writer, title string, rows map[string]LocLangStats, isTTY, fullTree, sincePrevCol bool) {
	var keys []string
	if fullTree {
		keys = locSortedRowKeys(rows)
	} else {
		keys = locSortedRowKeysChurn(rows)
	}
	if title != "" && !strings.HasPrefix(title, "  ") {
		fmt.Fprintln(w, colorize(title, ColorBold, isTTY))
	}
	if len(keys) == 0 {
		return
	}
	if fullTree {
		if sincePrevCol {
			fmt.Fprintf(w, "%-14s%8s%8s%7s%7s%8s%8s%8s\n", "Category", "loc", "Δ%", "%", "wip", "edited", "added", "removed")
			for _, l := range keys {
				s := rows[l]
				d := "    —"
				if s.SincePrevLocPercent != nil {
					d = fmt.Sprintf("%+6.1f%%", *s.SincePrevLocPercent)
				}
				fmt.Fprintf(w, "%-14s%8d%8s%6.1f%%%6.1f%%%8d%8d%8d\n", l, s.Loc, d, s.Percent, s.WipPercent, s.Edited, s.Added, s.Removed)
			}
		} else {
			fmt.Fprintf(w, "%-14s%8s%7s%7s%8s%8s%8s\n", "Category", "loc", "%", "wip", "edited", "added", "removed")
			for _, l := range keys {
				s := rows[l]
				fmt.Fprintf(w, "%-14s%8d%6.1f%%%6.1f%%%8d%8d%8d\n", l, s.Loc, s.Percent, s.WipPercent, s.Edited, s.Added, s.Removed)
			}
		}
	} else {
		fmt.Fprintf(w, "%-14s%7s%8s%8s%8s\n", "Category", "wip", "edited", "added", "removed")
		for _, l := range keys {
			s := rows[l]
			fmt.Fprintf(w, "%-14s%6.1f%%%8d%8d%8d\n", l, s.WipPercent, s.Edited, s.Added, s.Removed)
		}
	}
}

// 🔢 locCommand wires the `loc` Cobra subcommand.
func locCommand(factory EngineFactory, config *Config) *cobra.Command {
	_ = factory
	cmd := &cobra.Command{
		Use:   "loc",
		Short: "Tracked-file LOC (code, markup, data) plus git deltas; internal scan (no cloc)",
		Long:  "Counts tracked files via git (not cloc). The runnable CLI is built from repo/client/mcp (package main), not repo/client (library): go build -o repo/client/client.exe ./repo/client/mcp. Wip% is each row's edited churn vs the whole first-parent walk on the logged ref (default ⛳wip), including all contributors. With --history, each row scans the tree at that commit for physical LOC; Δ% is change vs the previous printed history step. Branch and checkpoint lines use the same emoji ids as the repo tree (⛳wip, 🔀abc1234, 🧑‍💻alias).",
		Args:  cobra.NoArgs,
		RunE: func(c *cobra.Command, args []string) error {
			langs, _ := c.Flags().GetStringSlice("languages")
			if len(langs) == 0 {
				langs = []string{"TypeScript", "Go", "C#", "Python", "Rust"}
			}
			h, _ := c.Flags().GetBool("history")
			by, _ := c.Flags().GetBool("by-contributors")
			br, _ := c.Flags().GetString("branch")
			bc, _ := c.Flags().GetString("by-contributor")
			if h {
				if strings.TrimSpace(br) == "" {
					br = locDefaultBranch
				}
			} else {
				br = ""
			}
			return runLocCommand(c, config, langs, h, by, br, bc)
		},
	}
	cmd.Flags().Bool("history", false, "Per-commit time series; walks --branch (default: "+locDefaultBranch+") without checkout")
	cmd.Flags().Bool("by-contributors", false, "Break down cumulative line deltas by first author (FindAndUpdateContributor alias)")
	cmd.Flags().String("by-contributor", "", "Restrict git deltas and history rows to this contributor alias (case-insensitive)")
	cmd.Flags().String("branch", locDefaultBranch, "With --history: git ref to log (default dev branch). Ignored when --history is false")
	cmd.Flags().StringSlice("languages", []string{"TypeScript", "Go", "C#", "Python", "Rust"}, "Limits which programming-language buckets are counted; markup/data always included when matched")
	return cmd
}

