func (p *GitHubManagementProvider) ListRepoLabels() ([]ManagementLabel, error) {
	labels, err := ghListRepoLabels()
	if err != nil {
		return nil, err
	}
	result := make([]ManagementLabel, len(labels))
	for i, l := range labels {
		result[i] = ManagementLabel{Name: l.Name}
	}
	return result, nil
}

