// Ticket and goal lifecycle management including creation, closing, reopening, deletion, and diff computation.

// 🎫GetTicketsDir MUST return the stored value without modification.
// 📖GetTicketsDir returns the tickets dir of the value.
func GetTicketsDir() string {
	return filepath.Join(GetRepoMetaDir(), "🎫")
}

// 🏪GetTicketPath MUST return the stored value without modification.
// 📦GetTicketPath returns the ticket path of the value.
func GetTicketPath(year, month, day int, slug string) string {
	return filepath.Join(GetTicketsDir(), PadNumber(year, 2), PadNumber(month, 2), PadNumber(day, 2), slug)
}

// 📥GetImportantFilePath MUST return the stored value without modification.
// 📥GetImportantFilePath returns the important file path of the value.
func GetImportantFilePath(year, month, day int, slug string) string {
	return filepath.Join(GetTicketPath(year, month, day, slug), "important.md")
}

// 🛤️GetTicketJsonPath MUST return the stored value without modification.
// ⬛GetTicketJsonPath returns the ticket json path of the value.
func GetTicketJsonPath(year, month, day int, slug string) string {
	return filepath.Join(GetTicketPath(year, month, day, slug), "ticket.json")
}

// 💿normalizeTicketKeyword holds the data fields for a normalizeTicketKeyword record.
func normalizeTicketKeyword(value string) string {
	return strings.ToUpper(strings.TrimSpace(value))
}

// 🔷hasTicketKeyword holds the data fields for a hasTicketKeyword record.
func hasTicketKeyword(text, keyword string) bool {
	return strings.Contains(strings.ToUpper(text), keyword)
}

// 🎯FindTicketBySlug MUST return nil when no match is found.
// 🔎FindTicketBySlug searches for and returns the matching ticket by slug.
func FindTicketBySlug(slug string) (*Ticket, error) {
	tickets, err := ListTickets(nil, nil, nil)
	if err != nil {
		return nil, err
	}
	for i := len(tickets) - 1; i >= 0; i-- {
		t := tickets[i]
		if t.Slug == slug || filepath.Base(t.Slug) == slug {
			return &t, nil
		}
	}
	return nil, fmt.Errorf("ticket not found: %s", slug)
}

// 🧪LatestTicket MUST complete the operation and return consistent results.
func LatestTicket() (*Ticket, error) {
	tickets, err := ListTickets(nil, nil, nil)
	if err != nil {
		return nil, err
	}
	if len(tickets) == 0 {
		return nil, fmt.Errorf("no tickets found")
	}
	sort.Slice(tickets, func(i, j int) bool {
		if tickets[i].Year != tickets[j].Year {
			return tickets[i].Year > tickets[j].Year
		}
		if tickets[i].Month != tickets[j].Month {
			return tickets[i].Month > tickets[j].Month
		}
		if tickets[i].Day != tickets[j].Day {
			return tickets[i].Day > tickets[j].Day
		}
		return tickets[i].GetDateStarted().After(tickets[j].GetDateStarted())
	})
	return &tickets[0], nil
}

// 🔶shouldContinueTicket holds the data fields for a shouldContinueTicket record.
func shouldContinueTicket(prompt string) bool {
	return hasTicketKeyword(prompt, "CONTINUE")
}

// 🔹shouldSkipTicket holds the data fields for a shouldSkipTicket record.
func shouldSkipTicket(prompt string) bool {
	return hasTicketKeyword(prompt, "NOTICKET")
}

// 📬OpenTicket MUST complete the operation and return consistent results.
func OpenTicket(emoji, title, prompt, llm, client, draft string, noIssue bool, goal string, parent string, noManagement bool, issue string, mcpKind McpClientKind, planID, specID string) (*Ticket, error) {
	if prompt == "" {
		prompt = title
	}
	if shouldSkipTicket(prompt) {
		return nil, nil
	}
	if shouldContinueTicket(prompt) {
		latest, err := LatestTicket()
		if err != nil {
			return nil, err
		}
		if latest.GetStatus() == TicketStatusClosed {
			return latest, ReopenTicket(latest, prompt, llm, client, draft, goal, parent, noManagement, mcpKind, planID, specID)
		}
		return latest, nil
	}
	return CreateTicket(emoji, title, prompt, llm, client, draft, noIssue, goal, parent, noManagement, issue, mcpKind, planID, specID)
}

// ⛳OpenGoal MUST complete the operation and return consistent results.
func OpenGoal(title, description, prompt, dueDate, client, llm string, noManagement bool) (*Goal, error) {
	ctx := NewRepoContext(rootDir)
	input := GoalCreateInput{
		Title:        title,
		Description:  description,
		Prompt:       prompt,
		DueDate:      dueDate,
		Client:       client,
		LLM:          llm,
		NoManagement: noManagement,
	}
	return ctx.GoalCreate(input)
}

// 🎫validateTicketEmojiTitle MUST validate the emoji and title and return the derived slug.
// 🎫Requires a non-empty emoji that extractEntityEmoji recognizes and a non-empty title.
// 🎫Does NOT enforce any shape on the title string.
func validateTicketEmojiTitle(emoji, title string) (string, error) {
	emoji = strings.TrimSpace(emoji)
	if emoji == "" {
		return "", fmt.Errorf("ticket emoji is required")
	}
	extracted, remaining := extractEntityEmoji(emoji)
	if extracted == "" || strings.TrimSpace(remaining) != "" {
		return "", fmt.Errorf("ticket emoji must be a single emoji character")
	}
	title = strings.TrimSpace(title)
	if title == "" {
		return "", fmt.Errorf("ticket title is required")
	}
	slug := Slugify(title)
	if slug == "" {
		return "", fmt.Errorf("ticket title must contain at least one alphanumeric character")
	}
	return slug, nil
}

// 🔁UpdateTicketTitle MUST complete the operation and return consistent results.
// 🔁Only validates that the title is non-empty; does NOT enforce any shape on the title string.
func UpdateTicketTitle(ticket *Ticket, title string) error {
	if ticket == nil {
		return fmt.Errorf("ticket is nil")
	}
	title = strings.TrimSpace(title)
	if title == "" {
		return fmt.Errorf("ticket title is required")
	}
	slug := Slugify(title)
	if slug == "" {
		return fmt.Errorf("ticket title must contain at least one alphanumeric character")
	}

	parentDir := filepath.Dir(ticket.Slug)
	if parentDir != "." {
		slug = filepath.ToSlash(filepath.Join(parentDir, slug))
	}

	newFolderPath := GetTicketPath(ticket.Year, ticket.Month, ticket.Day, slug)
	if slug != ticket.Slug {
		if FileExists(newFolderPath) {
			return fmt.Errorf("ticket folder already exists: %s", newFolderPath)
		}
		if err := EnsureDir(filepath.Dir(newFolderPath)); err != nil {
			return err
		}
		if err := os.Rename(ticket.FolderPath, newFolderPath); err != nil {
			return err
		}
	}
	ticket.Title = title
	ticket.Slug = slug
	ticket.FolderPath = newFolderPath
	ticket.JsonPath = GetTicketJsonPath(ticket.Year, ticket.Month, ticket.Day, slug)
	ticket.ImportantPath = GetImportantFilePath(ticket.Year, ticket.Month, ticket.Day, slug)
	return nil
}

// 🆕CreateTicket MUST persist the new entity and return a reference to it.
// 🆕CreateTicket creates a new ticket and persists it.
func CreateTicket(emoji, title, prompt, llm, client, draft string, noIssue bool, goal string, parent string, noManagement bool, issue string, mcpKind McpClientKind, planID, specID string) (*Ticket, error) {
	if goal == "" {
		return nil, fmt.Errorf("ticket goal is required")
	}
	slug, err := validateTicketEmojiTitle(emoji, title)
	if err != nil {
		return nil, err
	}
	emoji = strings.TrimSpace(emoji)
	title = strings.TrimSpace(title)

	now := time.Now()
	year, month, day := FormatDate(now)

	if parent != "" {
		pTicket, err := FindTicketBySlug(parent)
		if err != nil {
			return nil, fmt.Errorf("failed to find parent ticket '%s': %w", parent, err)
		}
		year = pTicket.Year
		month = pTicket.Month
		day = pTicket.Day
		slug = filepath.ToSlash(filepath.Join(pTicket.Slug, slug))
	}

	var llmSlug string
	if llm != "" {
		llmSlug, err = ResolveAllowedLLM(llm)
		if err != nil {
			return nil, err
		}
	}
	uiSlug, err := ResolveAllowedClient(client)
	if err != nil {
		return nil, err
	}

	ticketDir := GetTicketPath(year, month, day, slug)
	if err := EnsureDir(ticketDir); err != nil {
		return nil, err
	}
	jsonPath := GetTicketJsonPath(year, month, day, slug)

	importantFilePath := GetImportantFilePath(year, month, day, slug)

	if draft != "" {
		draftPath := filepath.Join(GetDraftsPath(), draft)
		if IsDir(draftPath) {
			entries, err := os.ReadDir(draftPath)
			if err == nil {
				for _, entry := range entries {
					src := filepath.Join(draftPath, entry.Name())
					dst := filepath.Join(ticketDir, entry.Name())
					if err := MoveFile(src, dst); err != nil {
						fmt.Printf("Warning: Failed to move draft file %s: %v\n", entry.Name(), err)
						continue
					}
				}
			}
			os.RemoveAll(draftPath)
		}
	}

	if err := WriteTextFile(importantFilePath, ""); err != nil {
		return nil, fmt.Errorf("failed to write important file: %w", err)
	}

	ticket := &Ticket{
		Year:          year,
		Month:         month,
		Day:           day,
		Slug:          slug,
		Title:         title,
		Emoji:         emoji,
		Status:        TicketStatusOpen,
		Description:   prompt,
		Goal:          goal,
		Parent:        parent,
		FolderPath:    ticketDir,
		JsonPath:      jsonPath,
		ImportantPath: importantFilePath,
		Interactions: []Interaction{{
			Kind:   "ticket.open",
			Prompt: prompt,
			LLM:    llmSlug,
			System: GetSystem(),
			Client: uiSlug,
			Date:   now.Format("2006-01-02 15:04:05"),
		}},
	}
	appendTicketSessionID(ticket, currentTicketSessionID())

	if err := ApplyTicketPlanFromIDs(ticket, mcpKind, planID, specID); err != nil {
		return nil, err
	}

	skipIssue := noIssue || noManagement || strings.Contains(prompt, "NOISSUE")
	if !skipIssue {
		if issue != "" {

			ticket.Management = &TicketManagementData{Issue: issue}
			GetManagementProvider().AddIssueToProject(issue)
		} else {

			issueBody := formatPromptHeading(prompt)

			var milestone *int
			if goal != "" {
				milestone, _ = getRootGoalMilestone(goal)
			}

			issueURL, err := GetManagementProvider().CreateIssue(title, issueBody, milestone)
			if err == nil && issueURL != "" {
				ticket.Management = &TicketManagementData{Issue: issueURL}
			} else if err != nil {
				fmt.Printf("Warning: Failed to create GitHub issue: %v\n", err)
			}
		}
	}

	if err := SaveTicket(ticket); err != nil {
		return nil, err
	}
	ticketID := fmt.Sprintf("%d/%02d/%02d/%s", ticket.Year, ticket.Month, ticket.Day, ticket.Slug)
	repopkg.Emit(repopkg.EventTicketOpenEnded, "repo-cli", repopkg.TicketOpenPayload{
		TicketPayload: repopkg.TicketPayload{ID: ticketID, Year: ticket.Year, Month: ticket.Month, Day: ticket.Day, Slug: ticket.Slug},
		Title:         ticket.Title, Prompt: ticket.Description, LLM: llmSlug, Client: uiSlug, Author: GetGitAuthorAlias(), Goal: goal, Parent: parent,
	})
	return ticket, nil
}

// 📌ghGetMilestoneTitle holds the data fields for a ghGetMilestoneTitle record.
func ghGetMilestoneTitle(number int) (string, error) {
	stdout, stderr, exitCode := ExecCommand("gh", []string{"api", fmt.Sprintf("repos/{owner}/{repo}/milestones/%d", number), "--jq", ".title"}, "")
	if exitCode != 0 {
		return "", fmt.Errorf("gh api milestone failed: %s", strings.TrimSpace(stderr))
	}
	return strings.TrimSpace(stdout), nil
}

// 🔸ghCreateIssue holds the data fields for a ghCreateIssue record.
func ghCreateIssue(title, body string, milestone *int) (string, error) {
	args := []string{"issue", "create", "--title", title, "--body", body, "--label", "ticket"}
	if milestone != nil {
		milestoneTitle, err := ghGetMilestoneTitle(*milestone)
		if err != nil {
			return "", fmt.Errorf("could not resolve milestone %d: %w", *milestone, err)
		}
		args = append(args, "--milestone", milestoneTitle)
	}
	stdout, stderr, exitCode := ExecCommand("gh", args, "")
	if exitCode != 0 {
		return "", fmt.Errorf("gh issue create failed: %s", strings.TrimSpace(stderr))
	}
	issueURL := strings.TrimSpace(stdout)
	if issueURL != "" {
		ghAddIssueToProject(issueURL)
		ghAssignIssueToCurrentUser(issueURL)
	}
	return issueURL, nil
}

