// 🩷StreamFolders MUST invoke the callback for each matching folders entry.
// 📄StreamFolders streams folders entries through the callback.
func StreamFolders(ctx context.Context, scope string, out chan<- Folder, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	root := rootDir
	if bundleName, found := strings.CutPrefix(scope, "semio/"); found {
		bundles := GetTechnologies()
		for _, b := range bundles {
			if b.Name == bundleName || normalizeBundleLabel(b.Name) == bundleName {
				root = filepath.Join(rootDir, b.Root)
				break
			}
		}
	} else if scope != "" && scope != "semio" {
		if filepath.IsAbs(scope) {
			root = scope
		} else {
			root = filepath.Join(rootDir, scope)
		}
	}

	var folders []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if !info.IsDir() {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		if rel == "." {
			return nil
		}
		if isRepoExcludedPath(path) {
			return filepath.SkipDir
		}
		if isGitIgnored(path) && !options.ShowIgnored {
			return filepath.SkipDir
		}
		folders = append(folders, path)
		return nil
	})
	if err != nil {
		return err
	}

	for _, folderPath := range folders {
		ignored := isGitIgnored(folderPath)
		relPath, _ := filepath.Rel(rootDir, folderPath)
		generated := IsGenerated(folderPath) || IsGeneratedFolder(relPath)
		folderKind := DeriveFolderKind(relPath)

		if ignored && !options.ShowIgnored {
			continue
		}
		if generated && !options.ShowGenerated {
			continue
		}

		if !shouldIncludeFolderKind(folderKind, options) {
			continue
		}

		if !matchesFilter(filepath.Base(folderPath), options) {
			continue
		}
		if !matchesQuery(folderPath, options) {
			continue
		}

		var bundleID *string
		if b := GetBundleByPath(relPath); b != nil {
			id := b.GetID()
			bundleID = &id
		}

		parentPath := filepath.Dir(relPath)
		var parentID *string
		if parentPath != "." {
			id := buildFolderID(parentPath, bundleID)
			parentID = &id
		}

		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			out <- Folder{
				ID:        buildFolderID(relPath, bundleID),
				Path:      relPath,
				URI:       buildFolderUriFromPath(relPath),
				Name:      filepath.Base(relPath),
				ParentID:  parentID,
				BundleID:  bundleID,
				Kind:      folderKind,
				Ignored:   ignored,
				Generated: generated,
			}
		}
	}
	return nil
}

// 💜StreamFiles MUST invoke the callback for each matching files entry.
// 🔲StreamFiles streams files entries through the callback.
func StreamFiles(ctx context.Context, scope string, out chan<- File, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	root := rootDir
	if scope != "" && scope != "semio" {
		bundles := GetTechnologies()
		matched := false
		for _, b := range bundles {
			if b.Name == scope || b.Root == scope || normalizeBundleLabel(b.Name) == scope {
				root = filepath.Join(rootDir, b.Root)
				matched = true
				break
			}
		}
		if !matched {
			parts := strings.SplitN(scope, "/", 3)
			if len(parts) == 3 {
				bundleScope := parts[0] + "/" + parts[1]
				subPath := parts[2]
				for _, b := range bundles {
					if b.Name == bundleScope || b.Root == bundleScope || normalizeBundleLabel(b.Name) == bundleScope {
						root = filepath.Join(rootDir, b.Root, subPath)
						matched = true
						break
					}
				}
			}
		}
		if !matched {
			if filepath.IsAbs(scope) {
				root = scope
			} else {
				root = filepath.Join(rootDir, scope)
			}
		}
	}

	if info, err := os.Stat(root); err == nil && !info.IsDir() {
		relPath, _ := filepath.Rel(rootDir, root)
		var bundleID *string
		if b := GetBundleByPath(relPath); b != nil {
			id := b.GetID()
			bundleID = &id
		}
		folderPath := filepath.Dir(relPath)
		var folderID *string
		if folderPath != "." {
			id := buildFolderID(folderPath, bundleID)
			folderID = &id
		}
		out <- File{
			ID:        buildFileID(relPath, bundleID),
			Path:      relPath,
			URI:       buildFileUriFromPath(relPath),
			Name:      filepath.Base(relPath),
			Extension: filepath.Ext(relPath),
			FolderID:  folderID,
			BundleID:  bundleID,
			Kind:      DeriveFileKind(filepath.Base(relPath)),
			Ignored:   isGitIgnored(root),
			Generated: IsGenerated(root),
		}
		return nil
	}

	var files []string
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			rel, _ := filepath.Rel(root, path)
			if rel != "." {
				if isRepoExcludedPath(path) {
					return filepath.SkipDir
				}
				if isGitIgnored(path) && !options.ShowIgnored {
					return filepath.SkipDir
				}
			}
			return nil
		}
		if isRepoExcludedPath(path) {
			return nil
		}
		if isGitIgnored(path) && !options.ShowIgnored {
			return nil
		}
		files = append(files, path)
		return nil
	})
	if err != nil {
		return err
	}

	for _, filePath := range files {
		ignored := isGitIgnored(filePath)
		generated := IsGenerated(filePath)
		kind := DeriveFileKind(filepath.Base(filePath))

		if ignored && !options.ShowIgnored {
			continue
		}
		if generated && !options.ShowGenerated {
			continue
		}

		if !shouldIncludeKind(kind, options) {
			continue
		}

		name := filepath.Base(filePath)
		if !matchesFilter(name, options) {
			continue
		}
		if !matchesQuery(filePath, options) {
			continue
		}

		relPath, _ := filepath.Rel(rootDir, filePath)
		var bundleID *string
		if b := GetBundleByPath(relPath); b != nil {
			id := b.GetID()
			bundleID = &id
		}

		folderPath := filepath.Dir(relPath)
		var folderID *string
		if folderPath != "." {
			id := buildFolderID(folderPath, bundleID)
			folderID = &id
		}

		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
			out <- File{
				ID:        buildFileID(relPath, bundleID),
				Path:      relPath,
				URI:       buildFileUriFromPath(relPath),
				Name:      filepath.Base(relPath),
				Extension: filepath.Ext(relPath),
				FolderID:  folderID,
				BundleID:  bundleID,
				Kind:      kind,
				Ignored:   ignored,
				Generated: generated,
			}
		}
	}
	return nil
}

// 💙flattenSections holds the data fields for a flattenSections record.
func flattenSections(sections []Section) []Section {
	return flattenSectionsWithPrefix(sections, "")
}

// 🔧flattenSectionsWithPrefix holds the data fields for a flattenSectionsWithPrefix record.
func flattenSectionsWithPrefix(sections []Section, prefix string) []Section {
	var result []Section
	for _, s := range sections {
		children := s.Children
		s.Children = nil
		sPrefix := s.Name
		if s.Emoji != "" {
			sPrefix = s.Emoji + s.Name
		}
		if prefix != "" {
			s.Path = prefix + "#" + sPrefix
		} else {
			s.Path = sPrefix
		}
		result = append(result, s)
		result = append(result, flattenSectionsWithPrefix(children, s.Path)...)
	}
	return result
}

// 💚hydrateSectionMetadata holds the data fields for a hydrateSectionMetadata record.
func hydrateSectionMetadata(s *Section, filePath string, prefix string) {
	s.FilePath = filePath
	s.Path = prefix
	for i := range s.Children {
		childEmoji := s.Children[i].Emoji
		childPrefix := s.Children[i].Name
		if childEmoji != "" {
			childPrefix = childEmoji + childPrefix
		}
		childPath := prefix + "#" + childPrefix
		hydrateSectionMetadata(&s.Children[i], filePath, childPath)
	}
}

// 💛StreamSections MUST invoke the callback for each matching sections entry.
// ▪️StreamSections streams sections entries through the callback.
func StreamSections(ctx context.Context, scope string, out chan<- Section, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	filesOpts := options
	filesOpts.Filter = ""
	filesOpts.Regex = false

	fileChan := make(chan File)
	go func() {
		StreamFiles(ctx, scope, fileChan, filesOpts)
	}()

	for f := range fileChan {
		fullPath := f.Path
		if !filepath.IsAbs(fullPath) {
			fullPath = filepath.Join(rootDir, fullPath)
		}
		content, err := ReadTextFile(fullPath)
		if err != nil {
			continue
		}
		sections := ParseSections(content, f.Path)
		if options.Filter != "" || options.Regex {
			flatSections := flattenSections(sections)
			for _, s := range flatSections {
				s.FilePath = f.Path
				if !matchesFilter(s.Name, options) {
					continue
				}
				if !matchesQuery(s.Name+" "+s.FilePath, options) {
					continue
				}

				select {
				case <-ctx.Done():
					return ctx.Err()
				default:
					out <- s
				}
			}
		} else {
			for i := range sections {
				rootPrefix := sections[i].Name
				if sections[i].Emoji != "" {
					rootPrefix = sections[i].Emoji + rootPrefix
				}
				hydrateSectionMetadata(&sections[i], f.Path, rootPrefix)
				select {
				case <-ctx.Done():
					return ctx.Err()
				default:
					out <- sections[i]
				}
			}
		}
	}
	return nil
}

// 🧡StreamDefinitions MUST invoke the callback for each matching definitions entry.
// ▶️StreamDefinitions streams definitions entries through the callback.
func StreamDefinitions(ctx context.Context, scope string, out chan<- Definition, opts ...StreamOptions) error {
	defer close(out)
	var options StreamOptions
	if len(opts) > 0 {
		options = opts[0]
	}

	filesOpts := options
	filesOpts.Filter = ""
	filesOpts.Regex = false

	fileChan := make(chan File)
	go func() {
		StreamFiles(ctx, scope, fileChan, filesOpts)
	}()

	for f := range fileChan {
		fullPath := f.Path
		if !filepath.IsAbs(fullPath) {
			fullPath = filepath.Join(rootDir, fullPath)
		}
		content, err := ReadTextFile(fullPath)
		if err != nil {
			continue
		}
		lang := GetLanguage(f.Path)
		if lang == nil {
			continue
		}
		lines := strings.Split(content, "\n")
		defs := lang.ParseDefinitions(content, lines)
		for _, d := range defs {
			rawKind := d.Kind
			if rawKind == "" {
				rawKind = "definition"
			}
			kind := DeriveDefinitionKind(rawKind)

			if !shouldIncludeDefinitionKind(kind, options) {
				continue
			}

			def := Definition{
				Name:      d.Name,
				Kind:      kind,
				FilePath:  f.Path,
				StartLine: d.Start,
				EndLine:   d.End,
			}

			if !matchesFilter(def.Name, options) {
				continue
			}
			if !matchesQuery(def.Name+" "+string(def.Kind)+" "+def.FilePath, options) {
				continue
			}

			select {
			case <-ctx.Done():
				return ctx.Err()
			default:
				out <- def
			}
		}
	}
	return nil
}

// ❤️ResolveBundleForPath MUST return the resolved value or an error if unresolvable.
// 📩ResolveBundleForPath resolves and returns the bundle for path.
func ResolveBundleForPath(filePath string, bundles []Bundle) string {
	var bestMatch string
	var maxLen int
	for _, b := range bundles {
		if b.Name == "" {
			continue
		}
		if strings.HasPrefix(filePath, b.Root+"/") || filePath == b.Root {
			if len(b.Root) > maxLen {
				maxLen = len(b.Root)
				bestMatch = normalizeBundleLabel(b.Name)
			}
		}
	}
	return bestMatch
}

// 🤍formatLineMetrics holds the data fields for a formatLineMetrics record.
func formatLineMetrics(metrics *LineMetrics) string {
	if metrics == nil {
		return ""
	}
	var parts []string
	if metrics.Removed > 0 {
		parts = append(parts, fmt.Sprintf("-%d", metrics.Removed))
	}
	if metrics.Added > 0 {
		parts = append(parts, fmt.Sprintf("+%d", metrics.Added))
	}
	if len(parts) == 0 {
		return ""
	}
	return " " + strings.Join(parts, " ")
}

// 🖤formatPathWithBundle holds the data fields for a formatPathWithBundle record.
func formatPathWithBundle(path string, bundles []Bundle) string {
	bundleName := ResolveBundleForPath(path, bundles)
	if bundleName == "" {
		return path
	}
	bundleLabel := normalizeBundleLabel(bundleName)
	root := ""
	for _, bundle := range bundles {
		if normalizeBundleLabel(bundle.Name) == bundleLabel || bundle.Name == bundleName {
			root = bundle.Root
			break
		}
	}
	if root != "" {
		relative := strings.TrimPrefix(path, root+"/")
		if relative != path {
			if relative == "" {
				return bundleLabel
			}
			return bundleLabel + "/" + relative
		}
	}
	return bundleLabel + "/" + path
}

// 🤎formatSemanticPath holds the data fields for a formatSemanticPath record.
func formatSemanticPath(path string, bundles []Bundle) string {
	filePath := extractFilePrefix(path)
	remainder := path[len(filePath):]
	return formatPathWithBundle(filePath, bundles) + remainder
}

// 💗formatDeletedPath holds the data fields for a formatDeletedPath record.
func formatDeletedPath(path string, bundles []Bundle) string {
	filePath := extractFilePrefix(path)
	remainder := path[len(filePath):]
	base := formatPathWithBundle(filePath, bundles)
	if remainder == "" {
		return "<del>" + base + "</del>"
	}
	return base + "<del>" + remainder + "</del>"
}

// 💖commonPrefixLength holds the data fields for a commonPrefixLength record.
func commonPrefixLength(a, b string) int {
	limit := len(a)
	if len(b) < limit {
		limit = len(b)
	}
	idx := 0
	for idx < limit {
		if a[idx] != b[idx] {
			break
		}
		idx++
	}
	return idx
}

// 💝commonSuffixLength holds the data fields for a commonSuffixLength record.
func commonSuffixLength(a, b string, prefix int) int {
	max := len(a) - prefix
	if len(b)-prefix < max {
		max = len(b) - prefix
	}
	idx := 0
	for idx < max {
		if a[len(a)-1-idx] != b[len(b)-1-idx] {
			break
		}
		idx++
	}
	return idx
}

// 💘formatRenameDelta holds the data fields for a formatRenameDelta record.
func formatRenameDelta(from, to string) string {
	if from == to {
		return from
	}
	prefix := commonPrefixLength(from, to)
	suffix := commonSuffixLength(from, to, prefix)
	fromMiddle := from[prefix : len(from)-suffix]
	toMiddle := to[prefix : len(to)-suffix]
	return from[:prefix] + "<del>" + fromMiddle + "</del>" + toMiddle + from[len(from)-suffix:]
}

func formatRenamePath(from, to string, bundles []Bundle) string {
	fromFormatted := formatSemanticPath(from, bundles)
	toFormatted := formatSemanticPath(to, bundles)
	return formatRenameDelta(fromFormatted, toFormatted)
}

// ➡️appendDiffLines holds the data fields for a appendDiffLines record.
func appendDiffLines(lines *[]string, diffSet TicketDiffSet, iconAdded, iconChanged, iconRemoved, iconRenamed string, bundles []Bundle, formatter func(string) string, renameFormatter func(string, string) string) {
	if len(diffSet.Added) > 0 {
		sort.Slice(diffSet.Added, func(i, j int) bool { return diffSet.Added[i].Path < diffSet.Added[j].Path })
		for _, entry := range diffSet.Added {
			path := formatter(entry.Path)
			*lines = append(*lines, fmt.Sprintf("%s%s%s", iconAdded, path, formatLineMetrics(entry.Lines)))
		}
	}
	if len(diffSet.Modified) > 0 {
		sort.Slice(diffSet.Modified, func(i, j int) bool { return diffSet.Modified[i].Path < diffSet.Modified[j].Path })
		for _, entry := range diffSet.Modified {
			path := formatter(entry.Path)
			*lines = append(*lines, fmt.Sprintf("%s%s%s", iconChanged, path, formatLineMetrics(entry.Lines)))
		}
	}
	if len(diffSet.Renamed) > 0 {
		sort.Slice(diffSet.Renamed, func(i, j int) bool { return diffSet.Renamed[i].To < diffSet.Renamed[j].To })
		for _, entry := range diffSet.Renamed {
			path := renameFormatter(entry.From, entry.To)
			*lines = append(*lines, fmt.Sprintf("%s%s%s", iconRenamed, path, formatLineMetrics(entry.Lines)))
		}
	}
	if len(diffSet.Deleted) > 0 {
		sort.Slice(diffSet.Deleted, func(i, j int) bool { return diffSet.Deleted[i].Path < diffSet.Deleted[j].Path })
		for _, entry := range diffSet.Deleted {
			path := formatDeletedPath(entry.Path, bundles)
			*lines = append(*lines, fmt.Sprintf("%s%s%s", iconRemoved, path, formatLineMetrics(entry.Lines)))
		}
	}
}

// 💕generateMetricsComment holds the data fields for a generateMetricsComment record.
func generateMetricsComment(diffs *TicketDiffs, bundles []Bundle) string {
	if diffs == nil {
		return ""
	}
	var lines []string
	appendDiffLines(&lines, diffs.Bundles, "📦", "📦", "📦", "📦", bundles, func(path string) string {
		return path
	}, func(from, to string) string {
		return formatRenameDelta(from, to)
	})
	appendDiffLines(&lines, diffs.Folders, "📂", "📁", "📁", "📁", bundles, func(path string) string {
		return formatPathWithBundle(path, bundles)
	}, func(from, to string) string {
		return formatRenamePath(from, to, bundles)
	})
	appendDiffLines(&lines, diffs.Files, "📄", "📝", "📄", "📄", bundles, func(path string) string {
		return formatSemanticPath(path, bundles)
	}, func(from, to string) string {
		return formatRenamePath(from, to, bundles)
	})
	appendDiffLines(&lines, diffs.Sections, "📑", "🔖", "🔖", "🔖", bundles, func(path string) string {
		return formatSemanticPath(path, bundles)
	}, func(from, to string) string {
		return formatRenamePath(from, to, bundles)
	})
	appendDiffLines(&lines, diffs.Definitions, "🏷️", "🏷️", "🏷️", "🏷️", bundles, func(path string) string {
		return formatSemanticPath(path, bundles)
	}, func(from, to string) string {
		return formatRenamePath(from, to, bundles)
	})
	if len(lines) == 0 {
		return ""
	}
	return strings.Join(lines, "\n")
}

// 🔖FinishTicket MUST return a non-nil error when the operation fails.
func FinishTicket(ticket *Ticket, summary string, files []string, noManagement bool, bulk bool) error {
	if ticket.Status != TicketStatusOpen {
		return fmt.Errorf("ticket is not open")
	}
	files = normalizeTicketFileInputs(files)
	if !bulk {
		if summary == "" {
			return fmt.Errorf("summary is required to finish a ticket")
		}
		if len(files) == 0 {
			return fmt.Errorf("at least one file is required to finish a ticket")
		}
	} else {
		if summary == "" {
			summary = "Bulk close"
		}
	}

	if !bulk && FileExists(ticket.ImportantPath) {
		importantContent, err := ReadTextFile(ticket.ImportantPath)
		if err == nil && strings.TrimSpace(importantContent) != "" {
			return fmt.Errorf("cannot finish ticket: %s is not empty. Please complete all compulsory actions", filepath.Base(ticket.ImportantPath))
		}

		if err := os.Remove(ticket.ImportantPath); err != nil {
			fmt.Printf("Warning: Failed to delete %s: %v\n", filepath.Base(ticket.ImportantPath), err)
		}
	}

	var tickFilesResult *TicketDiffs
	var err error
	if !bulk || len(files) > 0 {
		tickFilesResult, err = ComputeTicketFiles(ticket, files)
		if err != nil {
			return err
		}
	}

	if ticket.Management != nil && ticket.Management.Issue != "" && !noManagement {
		issueURL := ticket.Management.Issue

		if !bulk {

			bundles := GetTechnologies()
			labels := make(map[string]struct{})
			if tickFilesResult != nil {
				addLabel := func(path string) {
					if path == "" {
						return
					}
					labels[path] = struct{}{}
				}
				bundleDiffs := tickFilesResult.Bundles
				for _, entry := range bundleDiffs.Added {
					addLabel(entry.Path)
				}
				for _, entry := range bundleDiffs.Modified {
					addLabel(entry.Path)
				}
				for _, entry := range bundleDiffs.Deleted {
					addLabel(entry.Path)
				}
				for _, entry := range bundleDiffs.Renamed {
					addLabel(entry.From)
					addLabel(entry.To)
				}
			}
			var labelList []string
			for l := range labels {
				labelList = append(labelList, l)
			}
			if len(labelList) > 0 {
				if err := GetManagementProvider().AddLabels(issueURL, labelList); err != nil {
					fmt.Printf("Warning: Failed to add labels to GitHub issue: %v\n", err)
				}
			}

			comment := formatSummaryHeading(summary)
			metricsComment := generateMetricsComment(tickFilesResult, bundles)
			if metricsComment != "" {
				comment += "\n\n#✍Changes\n\n" + metricsComment
			}

			if err := GetManagementProvider().AddComment(issueURL, comment); err != nil {
				fmt.Printf("Warning: Failed to add summary and metrics comment to GitHub issue: %v\n", err)
			}
		}

		if err := GetManagementProvider().CloseIssue(issueURL); err != nil {
			fmt.Printf("Warning: Failed to close GitHub issue: %v\n", err)
		}
	}

	ticket.Summary = summary
	ticket.Status = TicketStatusClosed
	now := time.Now()
	nowStr := now.Format("2006-01-02 15:04:05")
	closeClient := ""
	if len(ticket.Interactions) > 0 {
		closeClient = ticket.Interactions[len(ticket.Interactions)-1].Client
	}
	var interactionFiles []InteractionFile
	if tickFilesResult != nil {
		seen := make(map[string]struct{})
		addFile := func(path string) {
			if _, ok := seen[path]; ok {
				return
			}
			seen[path] = struct{}{}
			interactionFiles = append(interactionFiles, InteractionFile{Path: path})
		}
		for _, f := range tickFilesResult.Files.Added {
			addFile(f.Path)
		}
		for _, f := range tickFilesResult.Files.Modified {
			addFile(f.Path)
		}
		for _, f := range tickFilesResult.Files.Deleted {
			addFile(f.Path)
		}
		for _, f := range tickFilesResult.Files.Renamed {
			addFile(f.To)
		}
	}
	ticket.Interactions = append(ticket.Interactions, Interaction{
		Kind:       "ticket.close",
		Author:     GetGitAuthorAlias(),
		System:     GetSystem(),
		Client:     closeClient,
		Checkpoint: GetGitCheckpoint(),
		Date:       nowStr,
		Summary:    summary,
		Files:      interactionFiles,
	})
	if err := moveTicketPlanIntoFolder(ticket); err != nil {
		return err
	}
	if err := SaveTicket(ticket); err != nil {
		return err
	}
	ticketID := fmt.Sprintf("%d/%02d/%02d/%s", ticket.Year, ticket.Month, ticket.Day, ticket.Slug)
	fileList := files
	if len(fileList) == 0 {
		for _, f := range interactionFiles {
			fileList = append(fileList, f.Path)
		}
	}
	repopkg.Emit(repopkg.EventTicketCloseEnded, "repo-cli", repopkg.TicketClosePayload{
		TicketPayload: repopkg.TicketPayload{ID: ticketID, Year: ticket.Year, Month: ticket.Month, Day: ticket.Day, Slug: ticket.Slug},
		Summary:       summary, Files: fileList, Author: GetGitAuthorAlias(),
	})
	return nil
}

// 🔖ReopenTicket MUST return a non-nil error when the operation fails.
func ReopenTicket(ticket *Ticket, prompt, llm, client, draft string, goal string, parent string, noManagement bool, mcpKind McpClientKind, planID, specID string) error {
	if ticket.Status == TicketStatusOpen {
		return fmt.Errorf("ticket is already open")
	}
	if goal != "" {
		ticket.Goal = goal
	}
	if parent != "" {
		ticket.Parent = parent
	}
	var llmSlug string
	var uiSlug string
	var err error
	if llm != "" {
		llmSlug, err = ResolveAllowedLLM(llm)
		if err != nil {
			return err
		}
	}
	if client != "" {
		uiSlug, err = ResolveAllowedClient(client)
		if err != nil {
			return err
		}
	} else {
		return fmt.Errorf("client is required")
	}
	if err := ApplyTicketPlanFromIDs(ticket, mcpKind, planID, specID); err != nil {
		return err
	}

	interaction := Interaction{
		Kind:   "ticket.reopen",
		Prompt: prompt,
		LLM:    llmSlug,
		System: GetSystem(),
		Client: uiSlug,
		Date:   time.Now().Format("2006-01-02 15:04:05"),
	}

	if draft != "" {
		draftPath := filepath.Join(GetDraftsPath(), draft)
		if IsDir(draftPath) {
			entries, err := os.ReadDir(draftPath)
			if err == nil {
				for _, entry := range entries {
					src := filepath.Join(draftPath, entry.Name())
					dst := filepath.Join(ticket.FolderPath, entry.Name())

					if FileExists(dst) {
						ext := filepath.Ext(entry.Name())
						name := strings.TrimSuffix(entry.Name(), ext)
						for i := 2; ; i++ {
							newDst := filepath.Join(ticket.FolderPath, fmt.Sprintf("%s_%d%s", name, i, ext))
							if !FileExists(newDst) {
								dst = newDst
								break
							}
						}
					}
					if err := MoveFile(src, dst); err != nil {
						fmt.Printf("Warning: Failed to move draft file %s: %v\n", entry.Name(), err)
						continue
					}
				}
			}
			os.RemoveAll(draftPath)
		}
	}

	ticket.Interactions = append(ticket.Interactions, interaction)
	appendTicketSessionID(ticket, currentTicketSessionID())
	ticket.Status = TicketStatusOpen

	if ticket.Management != nil && ticket.Management.Issue != "" && !noManagement {
		issueURL := ticket.Management.Issue
		if err := GetManagementProvider().ReopenIssue(issueURL); err != nil {
			fmt.Printf("Warning: Failed to reopen GitHub issue: %v\n", err)
		}
		GetManagementProvider().AddIssueToProject(issueURL)
		comment := formatPromptHeading(prompt)
		if err := GetManagementProvider().AddComment(issueURL, comment); err != nil {
			fmt.Printf("Warning: Failed to add prompt comment to GitHub issue: %v\n", err)
		}
	}

	if err := SaveTicket(ticket); err != nil {
		return err
	}
	ticketID := fmt.Sprintf("%d/%02d/%02d/%s", ticket.Year, ticket.Month, ticket.Day, ticket.Slug)
	repopkg.Emit(repopkg.EventTicketReopenEnded, "repo-cli", repopkg.TicketReopenPayload{
		TicketPayload: repopkg.TicketPayload{ID: ticketID, Year: ticket.Year, Month: ticket.Month, Day: ticket.Day, Slug: ticket.Slug},
		Prompt:        prompt, LLM: llmSlug, Client: uiSlug, Author: GetGitAuthorAlias(),
	})
	return nil
}

// 🔖ToolTicketOpen MUST complete the operation successfully.
func ToolTicketOpen(emoji, title, prompt, llm, client, draft string, noIssue bool, goal string, parent string, noManagement bool, issue string, mcpKind McpClientKind, planID, specID string) ToolResult {
	repopkg.Emit(repopkg.EventTicketOpenStarting, "repo-cli", repopkg.TicketOpenPayload{
		Title: title, Prompt: prompt, LLM: llm, Client: client, Goal: goal, Parent: parent,
	})
	ticket, err := OpenTicket(emoji, title, prompt, llm, client, draft, noIssue, goal, parent, noManagement, issue, mcpKind, planID, specID)
	if err != nil {
		return toolErrorResult(err)
	}
	if ticket == nil {
		output := NewOutput()
		output.Info("Ticket creation skipped (NOTICKET)")
		return ToolResult{Output: *output}
	}
	data, _ := json.Marshal(map[string]interface{}{
		"ticketOpen": map[string]interface{}{
			"id":     ticket.GetID(),
			"slug":   ticket.Slug,
			"year":   ticket.Year,
			"month":  ticket.Month,
			"day":    ticket.Day,
			"status": ticket.Status,
			"path":   ticket.FolderPath,
			"uri":    ticket.GetURI(),
		},
	})
	events := []Event{{Kind: KindResult, Command: "graphql", Data: data}}
	return toolResultFromEvents(events, ticket)
}

// 🔖ToolTicketList MUST complete the operation successfully.
// Always lists from ticket storage without building the full monorepo tree.
func ToolTicketList(year, month, day *int) ToolResult {
	tickets, err := ListTickets(year, month, day)
	if err != nil {
		return toolErrorResult(err)
	}
	var sb strings.Builder
	for _, t := range tickets {
		created := fmt.Sprintf("%04d-%02d-%02dT00:00:00Z", 2000+t.Year, t.Month, t.Day)
		if started := t.GetDateStarted(); !started.IsZero() {
			created = started.Format(time.RFC3339)
		}
		data := map[string]interface{}{
			"slug":      t.Slug,
			"year":      t.Year,
			"month":     t.Month,
			"day":       t.Day,
			"title":     t.Title,
			"status":    t.Status,
			"createdAt": created,
		}
		sb.WriteString(renderEntityMarkdown("ticket", data) + "\n")
	}
	output := NewOutput()
	output.Plain(sb.String())
	return ToolResult{Output: *output, Data: tickets}
}

// 🔖ToolTicketRead MUST complete the operation successfully.
func ToolTicketRead(year, month, day int, slug string) ToolResult {
	ticket, err := ReadTicket(year, month, day, slug)
	if err != nil {
		return toolErrorResult(err)
	}
	created := fmt.Sprintf("%04d-%02d-%02dT00:00:00Z", 2000+ticket.Year, ticket.Month, ticket.Day)
	if started := ticket.GetDateStarted(); !started.IsZero() {
		created = started.Format(time.RFC3339)
	}
	dates := map[string]interface{}{"created": created}
	if finished := ticket.GetDateFinished(); finished != nil {
		dates["finished"] = finished.Format(time.RFC3339)
	}
	flat := map[string]interface{}{
		"slug":   ticket.Slug,
		"year":   ticket.Year,
		"month":  ticket.Month,
		"day":    ticket.Day,
		"title":  ticket.Title,
		"status": ticket.Status,
		"date":   dates,
	}
	data, _ := json.Marshal(map[string]interface{}{"ticket": flat})
	events := []Event{{Kind: KindResult, Command: "ticket read", Data: data}}
	return toolResultFromEvents(events, ticket)
}

// 🔖ToolTicketClose MUST complete the operation successfully.
func ToolTicketClose(year, month, day int, slug, summary string, files []string, title string, noManagement bool) ToolResult {
	repopkg.Emit(repopkg.EventTicketCloseStarting, "repo-cli", repopkg.TicketClosePayload{
		TicketPayload: repopkg.TicketPayload{ID: fmt.Sprintf("%d/%02d/%02d/%s", year, month, day, slug), Year: year, Month: month, Day: day, Slug: slug},
		Summary:       summary, Files: files,
	})
	ticket, err := ReadTicket(year, month, day, slug)
	if err != nil {
		return toolErrorResult(err)
	}
	if title != "" {
		if err := UpdateTicketTitle(ticket, title); err != nil {
			return toolErrorResult(err)
		}
		if ticket.Management != nil && ticket.Management.Issue != "" && !noManagement {
			if err := GetManagementProvider().UpdateIssueTitle(ticket.Management.Issue, title); err != nil {
				fmt.Printf("Warning: Failed to update GitHub issue title: %v\n", err)
			}
		}
	}
	if err := FinishTicket(ticket, summary, files, noManagement, false); err != nil {
		return toolErrorResult(err)
	}
	created := fmt.Sprintf("%04d-%02d-%02dT00:00:00Z", 2000+ticket.Year, ticket.Month, ticket.Day)
	if started := ticket.GetDateStarted(); !started.IsZero() {
		created = started.Format(time.RFC3339)
	}
	closeDates := map[string]interface{}{"created": created}
	if finished := ticket.GetDateFinished(); finished != nil {
		closeDates["finished"] = finished.Format(time.RFC3339)
	}
	data, _ := json.Marshal(map[string]interface{}{
		"ticketClose": map[string]interface{}{
			"id":     ticket.GetID(),
			"slug":   ticket.Slug,
			"status": ticket.Status,
			"dates":  closeDates,
		},
	})
	events := []Event{{Kind: KindResult, Command: "graphql", Data: data}}
	return toolResultFromEvents(events, ticket)
}

