// 🔹Breachs MUST return a non-nil error when the operation fails.
func (r *Resolver) Breachs(ctx context.Context, repo *Repo, scope *string) ([]*Breach, error) {
	analysis, err := r.Ctx.Analyze(scope)
	if err != nil {
		return nil, err
	}
	return analysis.Breachs, nil
}

