// 🎫ensureTicketAgent holds the data fields for a ensureTicketAgent record.
func ensureTicketAgent(ticket *Ticket, sessionID string, client string) int {
	for i := range ticket.Agents {
		if ticket.Agents[i].Session == sessionID {
			if ticket.Agents[i].Client == "" {
				ticket.Agents[i].Client = client
			}
			return i
		}
	}
	ticket.Agents = append(ticket.Agents, TicketAgent{
		Session:     sessionID,
		Contributor: GetGitAuthorAlias(),
		System:      GetSystem(),
		Client:      client,
	})
	return len(ticket.Agents) - 1
}

// 📬trackHookInOpenTicket updates agent metadata and plan in the latest open ticket.
func trackHookInOpenTicket(hctx HookContext, result HookResult) {
	ticket, err := latestOpenTicket()
	if err != nil || ticket == nil {
		return
	}
	sessionID := extractSessionIDFromInput(hctx.Input)
	if sessionID == "" {
		if len(ticket.Agents) > 0 {
			sessionID = ticket.Agents[len(ticket.Agents)-1].Session
		} else {
			sessionID = generateHookSessionID()
		}
	}
	agentIndex := ensureTicketAgent(ticket, sessionID, hctx.Client)
	agent := &ticket.Agents[agentIndex]
	llm := extractLLMFromInput(hctx.Input)
	if llm != "" && agent.LLM == "" {
		agent.LLM = llm
	}
	transcript := extractTranscriptFromInput(hctx.Input)
	if transcript != "" && agent.Transcript == "" {
		agent.Transcript = transcript
	}
	if hctx.Event == HookAgentToolPlanUpdatingEnded {
		second := hctx.Second
		if second == "" {
			second = time.Now().UTC().Format(time.RFC3339)
		}
		if planResult, ok := result.(HookResultAgentToolPlanUpdating); ok && len(planResult.Steps) > 0 {
			var existing []TicketAgentPlanStep
			if agent.Plan != nil {
				existing = agent.Plan.Steps
			}
			merged := mergeTicketAgentPlanSteps(existing, planResult.Steps, second)
			agent.Plan = &TicketAgentPlan{Steps: merged}
		}
	}
	_ = SaveTicket(ticket)
}

// ♻️computeCheckpointDiff computes a semantic code diff from git changes for a checkpoint.
func computeCheckpointDiff(repoRoot string, checkpointID string) *CheckpointDiff {
	diff := &CheckpointDiff{}
	stdout, _, exitCode := ExecCommand("git", []string{"diff-tree", "--no-commit-id", "-r", "--name-status", checkpointID}, repoRoot)
	if exitCode != 0 {
		return diff
	}
	for _, line := range strings.Split(strings.TrimSpace(stdout), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		status := parts[0]
		filePath := parts[1]
		fileID := buildFileID(filePath, nil)
		dir := filepath.Dir(filePath)
		folderID := ""
		if dir != "." && dir != "" {
			folderID = buildFolderID(dir, nil)
		}
		var bundleID, technologyID string
		bundle := GetBundleByPath(filePath)
		if bundle != nil {
			bundleID = bundle.GetID()
			technologyName := bundle.TechnologyName
			if technologyName == "" {
				nameParts := strings.SplitN(bundle.Name, "/", 2)
				technologyName = nameParts[0]
			}
			pKind := DeriveTechnologyKind(technologyName)
			technologyID = emojiText(string(pKind)) + Flat(technologyName)
		}
		switch {
		case status == "A":
			diff.Files.Created = appendUniqueString(diff.Files.Created, fileID)
			if folderID != "" {
				diff.Folders.Modified = appendUniqueString(diff.Folders.Modified, folderID)
			}
			if bundleID != "" {
				diff.Bundles.Modified = appendUniqueString(diff.Bundles.Modified, bundleID)
			}
			if technologyID != "" {
				diff.Technologies.Modified = appendUniqueString(diff.Technologies.Modified, technologyID)
			}
		case status == "D":
			diff.Files.Deleted = appendUniqueString(diff.Files.Deleted, fileID)
			if folderID != "" {
				diff.Folders.Modified = appendUniqueString(diff.Folders.Modified, folderID)
			}
			if bundleID != "" {
				diff.Bundles.Modified = appendUniqueString(diff.Bundles.Modified, bundleID)
			}
			if technologyID != "" {
				diff.Technologies.Modified = appendUniqueString(diff.Technologies.Modified, technologyID)
			}
		case strings.HasPrefix(status, "R"):
			if len(parts) >= 3 {
				oldPath := parts[1]
				newPath := parts[2]
				oldFileID := buildFileID(oldPath, nil)
				newFileID := buildFileID(newPath, nil)
				diff.Files.Renamed = append(diff.Files.Renamed, CheckpointDiffRename{From: oldFileID, To: newFileID})
			} else {
				diff.Files.Modified = appendUniqueString(diff.Files.Modified, fileID)
			}
			if folderID != "" {
				diff.Folders.Modified = appendUniqueString(diff.Folders.Modified, folderID)
			}
			if bundleID != "" {
				diff.Bundles.Modified = appendUniqueString(diff.Bundles.Modified, bundleID)
			}
			if technologyID != "" {
				diff.Technologies.Modified = appendUniqueString(diff.Technologies.Modified, technologyID)
			}
		default:
			diff.Files.Modified = appendUniqueString(diff.Files.Modified, fileID)
			if folderID != "" {
				diff.Folders.Modified = appendUniqueString(diff.Folders.Modified, folderID)
			}
			if bundleID != "" {
				diff.Bundles.Modified = appendUniqueString(diff.Bundles.Modified, bundleID)
			}
			if technologyID != "" {
				diff.Technologies.Modified = appendUniqueString(diff.Technologies.Modified, technologyID)
			}
		}
	}
	return diff
}

// 🏪storeCheckpointDiff stores a semantic code diff at .repo/🔀/YY/MM/DD/<checkpoint-id>.json.
func storeCheckpointDiff(repoRoot string, checkpointID string) {
	if checkpointID == "" || checkpointID == "unknown" {
		return
	}
	diff := computeCheckpointDiff(repoRoot, checkpointID)
	now := time.Now().UTC()
	yy := fmt.Sprintf("%02d", now.Year()%100)
	mm := fmt.Sprintf("%02d", int(now.Month()))
	dd := fmt.Sprintf("%02d", now.Day())
	repoRoot = findRepoRoot(repoRoot)
	diffDir := filepath.Join(repoRoot, ".repo", "🔀", yy, mm, dd)
	if err := os.MkdirAll(diffDir, 0755); err != nil {
		return
	}
	data, err := json.MarshalIndent(diff, "", "  ")
	if err != nil {
		return
	}
	_ = os.WriteFile(filepath.Join(diffDir, checkpointID+".json"), data, 0644)
}

// ✔️runCheckpointStartingHook holds the data fields for a runCheckpointStartingHook record.
func runCheckpointStartingHook(hctx HookContext) HookResultVersionCheckpointStarting {
	repoRoot := hctx.RepoRoot
	if repoRoot == "" {
		cwd, err := os.Getwd()
		if err != nil {
			return HookResultVersionCheckpointStarting{HookResultBase: HookResultBase{Allowed: false, Message: fmt.Sprintf("cannot determine cwd: %v", err)}}
		}
		repoRoot = findRepoRoot(cwd)
	}
	SetRootDir(repoRoot)
	return HookResultVersionCheckpointStarting{
		HookResultBase: HookResultBase{Allowed: true, Message: "checkpoint starting hook passed"},
		Checkpoint:     extractCheckpointSHAFromInput(hctx.Input),
		Description:    extractCheckpointMessageFromInput(hctx.Input, repoRoot),
	}
}

// 🔤ValidateHookEvent checks if the given string is a valid hook event.
func ValidateHookEvent(s string) (HookEvent, error) {
	for _, e := range AllHookEvents {
		if string(e) == s {
			return e, nil
		}
	}
	return "", fmt.Errorf("invalid hook event %q, valid events: %s", s, strings.Join(hookEventStrings(), ", "))
}

func hookEventStrings() []string {
	result := make([]string, len(AllHookEvents))
	for i, e := range AllHookEvents {
		result[i] = string(e)
	}
	return result
}

// runHookExecution runs the hook pipeline (shared by CLI `hook` and per-IDE `RunHookFor`).
func runHookExecution(client, eventStr, toolName, toolArgs, filePath, parentInfo, repoRoot string, input json.RawMessage, jsonMode bool, stdout, stderr io.Writer) error {
	if toolName == "" {
		if tn := extractToolNameFromStdin(input); tn != "" {
			toolName = tn
		}
	}
	event, resolvedParent, err := ResolveHookEvent(eventStr, client, toolName, input)
	if err != nil {
		return err
	}
	if parentInfo == "" {
		parentInfo = resolvedParent
	}
	hctx := HookContext{
		Event:      event,
		Client:     client,
		Second:     time.Now().UTC().Format(time.RFC3339),
		RepoRoot:   repoRoot,
		ToolName:   toolName,
		ToolArgs:   toolArgs,
		FilePath:   filePath,
		ParentInfo: parentInfo,
		Input:      input,
	}
	result := RunHook(hctx)
	provider := GetEditorProvider(client)
	if provider != nil && provider.Kind() == "copilot-chat" {
		hookEventName := extractHookEventNameFromStdin(input)
		if hookEventName == "" {
			hookEventName = provider.NativeEventFromHookEvent(event, parentInfo)
		}
		out := provider.FormatHookOutput(hookEventName, result)
		fmt.Fprintln(stdout, out)
		return nil
	}
	if jsonMode {
		out, _ := json.Marshal(result)
		fmt.Fprintln(stdout, string(out))
		return nil
	}
	if !result.IsAllowed() {
		fmt.Fprintln(stderr, result.GetMessage())
		return ExitError{Code: 2}
	}
	msg := result.GetMessage()
	if msg != "" {
		fmt.Fprintln(stdout, msg)
	}
	return nil
}

// 🆕hookCommand creates the `hook <event> <client>` cobra command.
func hookCommand(factory EngineFactory, config *Config) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "hook <event> <client>",
		Short: "Run a lifecycle hook (git or agent)",
		Long: `Run a lifecycle hook for a given event and client.
Accepts neutral repo events or native client events (inlet adapter resolves to neutral).

📦 Version hooks:
  version.checkpoint.starting  Run before a version checkpoint
  version.checkpoint.ended     Run after a version checkpoint (e.g. post-checkpoint)
  version.checkin.starting     Run before a version checkin (e.g. fast-forward to main)
  version.checkin.ended        Run after a version checkin
  version.checkout.starting    Run before a version checkout (e.g. squash merge)
  version.checkout.ended       Run after a version checkout

🤖 Neutral agent hooks:
  agent.started                Agent session started
  agent.ended                  Agent session stopped
  agent.prompt.submitting      User submitting a prompt
  agent.compacting             Context compaction event
  agent.tool.starting          Tool starting (generic, excludes plan, search, code, test, build, terminal)
  agent.tool.ended             Tool completed (generic, excludes plan, search, code, test, build, terminal)
  agent.tool.plan.updating.starting  Plan/task list updating start
  agent.tool.plan.updating.ended     Plan/task list updating end
  agent.file.read.starting     Code search/read starting
  agent.file.read.ended        Code search/read ended
  agent.tool.code.edit.starting Code edit starting
  agent.tool.code.edit.ended   Code edit completed
  agent.tool.test.starting     Test starting
  agent.tool.test.ended        Test completed
  agent.tool.build.starting    Build starting
  agent.tool.build.ended       Build completed
  agent.tool.terminal.starting Terminal command starting (supports blocking)
  agent.tool.terminal.ended    Terminal command completed
  agent.thinking.starting      Agent thinking started
  agent.thinking.ended         Agent thinking completed (cursor: afterAgentThought)

🏢 Native client events (resolved by inlet adapter):
  copilot-chat:    SessionStart, Stop, SubagentStart, SubagentStop, UserPromptSubmit, PreCompact, PreToolUse, PostToolUse
  cursor-chat:     sessionStart, sessionEnd, stop, subagentStart, subagentStop, beforeSubmitPrompt, preCompact, preToolUse, postToolUse, beforeReadFile, afterFileEdit, beforeShellExecution, afterShellExecution, beforeMCPExecution, afterMCPExecution
  windsurf-chat:   pre_user_prompt, post_cascade_response, post_setup_worktree, pre_mcp_tool_use, post_mcp_tool_use, pre_read_code, post_read_code, pre_write_code, post_write_code, pre_run_command, post_run_command
  claude-code/droid/codex/antigravity: SessionStart, SessionEnd, SubagentStart, SubagentStop, Stop, UserPromptSubmit, PreCompact, PreToolUse, PostToolUse, PostToolUseFailure, TaskCompleted, Notification
  kiro-cli:        agentSpawn, userPromptSubmit, preToolUse, postToolUse, stop`,
		Args: cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			eventStr := args[0]
			client := ""
			if len(args) > 1 {
				client = args[1]
			}
			toolName, _ := cmd.Flags().GetString("tool-name")
			toolArgs, _ := cmd.Flags().GetString("tool-args")
			filePath, _ := cmd.Flags().GetString("file")
			parentInfo, _ := cmd.Flags().GetString("parent")
			repoRoot := config.Repo
			if repoRoot == "" {
				cwd, _ := os.Getwd()
				repoRoot = findRepoRoot(cwd)
			}
			var input json.RawMessage
			stdinReader := cmd.InOrStdin()
			if stdinReader == os.Stdin {
				if stat, err := os.Stdin.Stat(); err == nil && (stat.Mode()&os.ModeCharDevice) == 0 {
					if data, err := io.ReadAll(os.Stdin); err == nil && len(data) > 0 {
						input = json.RawMessage(data)
					}
				}
			} else {
				if data, err := io.ReadAll(stdinReader); err == nil && len(data) > 0 {
					input = json.RawMessage(data)
				}
			}
			return runHookExecution(client, eventStr, toolName, toolArgs, filePath, parentInfo, repoRoot, input, config.IsJSON(), cmd.OutOrStdout(), cmd.ErrOrStderr())
		},
	}
	cmd.Flags().String("tool-name", "", "Tool name for tool-related events")
	cmd.Flags().String("tool-args", "", "Tool arguments for tool-related events")
	cmd.Flags().String("file", "", "File path for code events")
	cmd.Flags().String("parent", "", "Parent agent info for agent events")
	return cmd
}

