func renderEntityHuman(kind string, data map[string]interface{}, isTTY bool) string {
	id := GetArtifactID(kind, data)
	props := collectEntityProps(kind, data, false)
	return sanitizeSingleLine(renderTemplate(textTpl, "text/entity", map[string]interface{}{
		"ID":    id,
		"Props": props,
		"IsTTY": isTTY,
	}))
}

func inferEntityKind(key string) string {
	key = strings.ToLower(key)
	prefixes := []struct {
		prefix string
		kind   string
	}{
		{"ticket", "ticket"},
		{"goal", "goal"},
		{"file", "file"},
		{"folder", "folder"},
		{"section", "section"},
		{"definition", "definition"},
		{"contributor", "contributor"},
		{"todo", "todo"},
		{"draft", "draft"},
		{"policy", "policy"},
		{"breachkind", "statute"},
		{"bundle", "bundle"},
		{"technology", "technology"},
		{"checkpoint", "checkpoint"},
		{"repo", "root"},
		{"syncgithub", "root"},
		{"syncmanagement", "root"},
		{"integrate", "file"},
		{"extract", "file"},
		{"fix", "root"},
	}
	for _, p := range prefixes {
		if strings.HasPrefix(key, p.prefix) {
			return p.kind
		}
	}
	return ""
}

