// 📖resolveAllTestDefinitionIDs resolves all test definition IDs.
func resolveAllTestDefinitionIDs(files []string) []string {
	var ids []string
	seen := map[string]bool{}

	for _, file := range files {
		normalized := normalizeHookPath(file)
		if normalized == "" {
			continue
		}
		absPath := normalized
		if !filepath.IsAbs(absPath) {
			absPath = filepath.Join(GetRootDir(), normalized)
		}
		if _, err := os.Stat(absPath); os.IsNotExist(err) {
			continue
		}
		content, err := os.ReadFile(absPath)
		if err != nil {
			continue
		}
		definitions := collectTestDefinitionsFromContent(string(content), normalized)
		for i := range definitions {
			id := definitions[i].GetID()
			if id == "" || seen[id] {
				continue
			}
			seen[id] = true
			ids = append(ids, id)
		}
	}

	return ids
}

func resolvePHPTestFiles(cwd string) []string {
	var files []string
	_ = filepath.Walk(cwd, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			return nil
		}
		if strings.HasSuffix(path, ".php") {
			base := strings.ToLower(filepath.Base(path))
			if strings.HasSuffix(base, "test.php") || strings.HasSuffix(base, "tests.php") || strings.Contains(strings.ToLower(filepath.Dir(path)), "tests") {
				files = append(files, path)
			}
		}
		return nil
	})
	return files
}

// 🧪latestOpenTicket finds the latest open ticket.
func latestOpenTicket() (*Ticket, error) {
	tickets, err := ListTickets(nil, nil, nil)
	if err != nil {
		return nil, err
	}
	var latest *Ticket
	for i := range tickets {
		ticket := tickets[i]
		if ticket.Status != TicketStatusOpen {
			continue
		}
		if latest == nil ||
			ticket.Year > latest.Year ||
			(ticket.Year == latest.Year && ticket.Month > latest.Month) ||
			(ticket.Year == latest.Year && ticket.Month == latest.Month && ticket.Day > latest.Day) ||
			(ticket.Year == latest.Year && ticket.Month == latest.Month && ticket.Day == latest.Day && ticket.Slug > latest.Slug) {
			copy := ticket
			latest = &copy
		}
	}
	return latest, nil
}

// 🧲extractSessionIDFromInput extracts session ID from input.
func extractSessionIDFromInput(input json.RawMessage) string {
	data := decodeHookInputMap(input)
	if data == nil {
		return ""
	}
	sessionID := findNestedStringValue(
		data,
		"session_id",
		"sessionId",
		"trajectory_id",
		"trajectoryId",
		"conversation_id",
		"conversationId",
		"agent_id",
		"agentId",
	)
	if sessionID != "" {
		return sessionID
	}
	transcript := extractTranscriptFromInput(input)
	if transcript == "" {
		return ""
	}
	base := strings.TrimSpace(filepath.Base(transcript))
	ext := filepath.Ext(base)
	if ext != "" {
		base = strings.TrimSuffix(base, ext)
	}
	return strings.TrimSpace(base)
}

